function stripeSecretMode(value) {
    const key=String(value||"").trim();
    if (/^(?:sk|rk)_live_/i.test(key)) return "live";
    if (/^(?:sk|rk)_test_/i.test(key)) return "test";
    return key ? "unknown" : "disabled";
}
