function canUseModule(
    plan,
    moduleKey
) {

    const module =
        CREATOR_MODULES[
            moduleKey
        ];

    if (!module) {
        return false;
    }

    return hasMinimumPlan(
        plan,
        module.minimum_plan
    );

}


function normalizeModuleKey(
    value
) {

    const key =
        String(
            value ||
            ""
        )
            .trim()
            .toLowerCase();

    if (
        !Object
            .prototype
            .hasOwnProperty
            .call(
                CREATOR_MODULES,
                key
            )
    ) {

        throw new Error(
            "Unbekanntes Creator-Modul."
        );

    }

    return key;

}


function publicModuleRegistry(
    account,
    entitlements = null
) {

    return Object
        .values(
            CREATOR_MODULES
        )
        .map(
            module => ({

                ...module,

                allowed:
                    entitlements && Object.prototype.hasOwnProperty.call(entitlements,module.key)
                        ? Boolean(entitlements[module.key])
                        : canUseModule(account?.plan,module.key)

            })
        );

}
