function defaultCreatorSettings() {

    return {

        profile: {

            bio:
                "",

            accent:
                "#148cff",

            theme:
                "cfs"

        },

        dashboard: {

            start_module:
                "dashboard"

        },

        widgets: {

            enabled: [
                "follower_goal"
            ]

        },

        stream_bot: {
            enabled: false,
            prefix: "!",
            commands: [
                { command: "discord", enabled: true, response: "Discord findest du über meine cfs_zockt-Seite.", response_mode: "overlay", cooldown_seconds: 15 },
                { command: "social", enabled: true, response: "Meine aktuellen Links findest du auf meiner cfs_zockt-Seite.", response_mode: "overlay", cooldown_seconds: 15 }
            ]
        }

    };

}


function sanitizeCreatorSettings(
    input
) {

    if (
        !input ||
        typeof input !==
            "object" ||
        Array.isArray(
            input
        )
    ) {

        return defaultCreatorSettings();

    }

    const json =
        JSON.stringify(
            input
        );

    if (
        Buffer.byteLength(
            json,
            "utf8"
        ) >
        64 * 1024
    ) {

        throw new Error(
            "Creator-Einstellungen sind zu groß."
        );

    }

    return JSON.parse(
        json
    );

}


async function getCreatorSettings(
    creatorId
) {

    const result =
        await pool.query(
            `
            SELECT
                settings,
                updated_at

            FROM creator_settings

            WHERE creator_id = $1

            LIMIT 1
            `,
            [
                creatorId
            ]
        );

    if (
        !result.rows[0]
    ) {

        const defaults =
            defaultCreatorSettings();

        await pool.query(
            `
            INSERT INTO creator_settings (
                creator_id,
                settings,
                updated_at
            )

            VALUES (
                $1,
                $2::jsonb,
                NOW()
            )

            ON CONFLICT (
                creator_id
            )

            DO NOTHING
            `,
            [
                creatorId,
                JSON.stringify(
                    defaults
                )
            ]
        );

        return {

            settings:
                defaults,

            updated_at:
                null

        };

    }

    return {

        settings:
            result
                .rows[0]
                .settings ||
            defaultCreatorSettings(),

        updated_at:
            result
                .rows[0]
                .updated_at ||
            null

    };

}


async function saveCreatorSettings(
    creatorId,
    settings
) {

    const clean =
        sanitizeCreatorSettings(
            settings
        );

    const result =
        await pool.query(
            `
            INSERT INTO creator_settings (
                creator_id,
                settings,
                updated_at
            )

            VALUES (
                $1,
                $2::jsonb,
                NOW()
            )

            ON CONFLICT (
                creator_id
            )

            DO UPDATE SET
                settings =
                    EXCLUDED.settings,

                updated_at =
                    NOW()

            RETURNING
                settings,
                updated_at
            `,
            [
                creatorId,
                JSON.stringify(
                    clean
                )
            ]
        );

    return result.rows[0];

}


