// ============================================================
// WIDGET STUDIO - FOLLOWER GOAL
// ============================================================

function clampNumber(
    value,
    minimum,
    maximum,
    fallback
) {

    const number =
        Number(
            value
        );

    if (
        !Number.isFinite(
            number
        )
    ) {

        return fallback;

    }

    return Math.min(
        maximum,
        Math.max(
            minimum,
            number
        )
    );

}


function normalizeWidgetColor(
    value,
    fallback
) {

    const color =
        String(
            value ||
            ""
        ).trim();

    if (
        /^#[0-9a-fA-F]{6}$/.test(
            color
        )
    ) {

        return color.toLowerCase();

    }

    return fallback;

}


function defaultFollowerGoalWidgetConfig() {

    return {

        enabled:
            true,

        preset:
            "bar",

        label:
            "Follower-Ziel",

        goal:
            200,

        accent:
            "#0a8cff",

        background:
            "#071321",

        text_color:
            "#f4f8ff",

        background_opacity:
            0.9,

        font_size:
            24,

        border_width:
            1,

        border_radius:
            18,

        show_logo:
            true,

        show_progress:
            true,

        show_numbers:
            true

    };

}


function sanitizeFollowerGoalWidgetConfig(
    input
) {

    const defaults =
        defaultFollowerGoalWidgetConfig();

    const source =
        input &&
        typeof input ===
            "object" &&
        !Array.isArray(
            input
        )
            ? input
            : {};

    const preset =
        [
            "bar",
            "compact",
            "card"
        ].includes(
            String(
                source.preset ||
                ""
            )
                .trim()
                .toLowerCase()
        )
            ? String(
                source.preset
            )
                .trim()
                .toLowerCase()
            : defaults.preset;

    const label =
        String(
            source.label ??
            defaults.label
        )
            .trim()
            .replace(
                /\s+/g,
                " "
            )
            .slice(
                0,
                60
            );

    return {

        enabled:
            source.enabled !==
            false,

        preset,

        label:
            label ||
            defaults.label,

        goal:
            Math.round(
                clampNumber(
                    source.goal,
                    1,
                    FOLLOWER_WIDGET_MAX_GOAL,
                    defaults.goal
                )
            ),

        accent:
            normalizeWidgetColor(
                source.accent,
                defaults.accent
            ),

        background:
            normalizeWidgetColor(
                source.background,
                defaults.background
            ),

        text_color:
            normalizeWidgetColor(
                source.text_color,
                defaults.text_color
            ),

        background_opacity:
            Math.round(
                clampNumber(
                    source.background_opacity,
                    0,
                    1,
                    defaults.background_opacity
                ) *
                100
            ) /
            100,

        font_size:
            Math.round(
                clampNumber(
                    source.font_size,
                    14,
                    72,
                    defaults.font_size
                )
            ),

        border_width:
            Math.round(
                clampNumber(
                    source.border_width,
                    0,
                    4,
                    defaults.border_width
                )
            ),

        border_radius:
            Math.round(
                clampNumber(
                    source.border_radius,
                    0,
                    40,
                    defaults.border_radius
                )
            ),

        show_logo:
            source.show_logo !==
            false,

        show_progress:
            source.show_progress !==
            false,

        show_numbers:
            source.show_numbers !==
            false

    };

}


function createWidgetSourceKey() {

    return crypto
        .randomBytes(
            WIDGET_SOURCE_KEY_BYTES
        )
        .toString(
            "hex"
        );

}


function validWidgetSourceKey(
    value
) {

    return new RegExp(
        `^[a-f0-9]{${WIDGET_SOURCE_KEY_BYTES * 2}}$`,
        "i"
    ).test(
        String(
            value ||
            ""
        )
    );

}


async function getFollowerWidgetSourceByCreator(
    creatorId,
    createIfMissing =
        true
) {

    const existing =
        await pool.query(
            `
            SELECT
                creator_id,
                widget_key,
                source_key,
                config,
                created_at,
                updated_at

            FROM creator_widget_sources

            WHERE
                creator_id = $1

            AND
                widget_key = 'follower_goal'

            LIMIT 1
            `,
            [
                creatorId
            ]
        );

    if (
        existing.rows[0] ||
        !createIfMissing
    ) {

        return existing.rows[0] ||
            null;

    }

    for (
        let attempt = 0;
        attempt < 3;
        attempt += 1
    ) {

        const sourceKey =
            createWidgetSourceKey();

        const result =
            await pool.query(
                `
                INSERT INTO creator_widget_sources (
                    creator_id,
                    widget_key,
                    source_key,
                    config,
                    created_at,
                    updated_at
                )

                VALUES (
                    $1,
                    'follower_goal',
                    $2,
                    $3::jsonb,
                    NOW(),
                    NOW()
                )

                ON CONFLICT
                    DO NOTHING

                RETURNING
                    creator_id,
                    widget_key,
                    source_key,
                    config,
                    created_at,
                    updated_at
                `,
                [
                    creatorId,
                    sourceKey,
                    JSON.stringify(
                        defaultFollowerGoalWidgetConfig()
                    )
                ]
            );

        if (
            result.rows[0]
        ) {

            return result.rows[0];

        }

        const afterConflict =
            await getFollowerWidgetSourceByCreator(
                creatorId,
                false
            );

        if (
            afterConflict
        ) {

            return afterConflict;

        }

    }

    throw new Error(
        "Widget-Quelle konnte nicht erstellt werden."
    );

}


async function saveFollowerWidgetSource(
    creatorId,
    config
) {

    const current =
        await getFollowerWidgetSourceByCreator(
            creatorId,
            true
        );

    const clean =
        sanitizeFollowerGoalWidgetConfig(
            config
        );

    const result =
        await pool.query(
            `
            UPDATE creator_widget_sources

            SET
                config = $3::jsonb,
                updated_at = NOW()

            WHERE
                creator_id = $1

            AND
                widget_key = $2

            RETURNING
                creator_id,
                widget_key,
                source_key,
                config,
                created_at,
                updated_at
            `,
            [
                creatorId,
                "follower_goal",
                JSON.stringify(
                    clean
                )
            ]
        );

    return result.rows[0] ||
        current;

}


async function rotateFollowerWidgetSourceKey(
    creatorId
) {

    await getFollowerWidgetSourceByCreator(
        creatorId,
        true
    );

    for (
        let attempt = 0;
        attempt < 3;
        attempt += 1
    ) {

        const sourceKey =
            createWidgetSourceKey();

        try {

            const result =
                await pool.query(
                    `
                    UPDATE creator_widget_sources

                    SET
                        source_key = $2,
                        updated_at = NOW()

                    WHERE
                        creator_id = $1

                    AND
                        widget_key = 'follower_goal'

                    RETURNING
                        creator_id,
                        widget_key,
                        source_key,
                        config,
                        created_at,
                        updated_at
                    `,
                    [
                        creatorId,
                        sourceKey
                    ]
                );

            if (
                result.rows[0]
            ) {

                return result.rows[0];

            }

        }
        catch (error) {

            if (
                error?.code !==
                "23505"
            ) {

                throw error;

            }

        }

    }

    throw new Error(
        "Neuer OBS-Schlüssel konnte nicht erstellt werden."
    );

}


async function getFollowerWidgetSourceByKey(
    sourceKey
) {

    if (
        !validWidgetSourceKey(
            sourceKey
        )
    ) {

        return null;

    }

    const result =
        await pool.query(
            `
            SELECT
                w.creator_id,
                w.widget_key,
                w.source_key,
                w.config,
                w.updated_at,
                a.display_name,
                a.status

            FROM creator_widget_sources w

            INNER JOIN creator_accounts a
                ON a.id = w.creator_id

            WHERE
                w.source_key = $1

            AND
                w.widget_key = 'follower_goal'

            AND
                a.status = 'active'

            LIMIT 1
            `,
            [
                String(
                    sourceKey
                )
            ]
        );

    return result.rows[0] ||
        null;

}


async function canUseLegacyDefaultTikTok(
    creatorId
) {

    const result =
        await pool.query(
            `
            SELECT creator_id
            FROM creator_tiktok_legacy_owner
            WHERE slot = 'default'
            LIMIT 1
            `
        );

    return Boolean(
        result.rows[0]?.creator_id &&
        String(
            result.rows[0].creator_id
        ) ===
        String(
            creatorId
        )
    );

}


async function resolveWidgetTikTokConnection(
    creatorId
) {

    const personal =
        await getConnection(
            creatorId
        );

    if (
        personal?.connected
    ) {

        return {

            creator_id:
                creatorId,

            connection:
                personal,

            source:
                "account"

        };

    }

    if (
        await canUseLegacyDefaultTikTok(
            creatorId
        )
    ) {

        const legacy =
            await getConnection(
                DEFAULT_CREATOR_ID
            );

        if (
            legacy?.connected
        ) {

            return {

                creator_id:
                    DEFAULT_CREATOR_ID,

                connection:
                    legacy,

                source:
                    "legacy_default"

            };

        }

    }

    return {

        creator_id:
            creatorId,

        connection:
            personal,

        source:
            "none"

    };

}


function widgetConnectionNeedsRefresh(
    connection
) {

    const updatedAt =
        connection?.updated_at
            ? new Date(
                connection.updated_at
            ).getTime()
            : 0;

    return Boolean(
        connection?.connected &&
        (
            !updatedAt ||
            Date.now() -
                updatedAt >=
                WIDGET_TIKTOK_REFRESH_MS
        )
    );

}


async function getFollowerWidgetTikTokData(
    creatorId
) {

    const resolved =
        await resolveWidgetTikTokConnection(
            creatorId
        );

    let connection =
        resolved.connection;

    if (
        widgetConnectionNeedsRefresh(
            connection
        )
    ) {

        try {

            await fetchTikTokProfile(
                resolved.creator_id
            );

            connection =
                await getConnection(
                    resolved.creator_id
                );

        }
        catch (error) {

            console.warn(
                "Widget TikTok Refresh Hinweis:",
                error?.message ||
                error
            );

        }

    }

    return {

        connected:
            Boolean(
                connection?.connected
            ),

        source:
            resolved.source,

        display_name:
            connection?.display_name ||
            "",

        avatar_url:
            connection?.avatar_url ||
            "",

        follower_count:
            Number(
                connection?.follower_count ||
                0
            ),

        likes_count:
            Number(
                connection?.likes_count ||
                0
            ),

        following_count:
            Number(
                connection?.following_count ||
                0
            ),

        video_count:
            Number(
                connection?.video_count ||
                0
            ),

        updated_at:
            connection?.updated_at ||
            null

    };

}


function followerWidgetSourceUrl(
    sourceKey
) {

    return (
        APP_BASE_URL +
        "/widgets/follower-goal.html#key=" +
        encodeURIComponent(
            sourceKey
        )
    );

}



