const WIDGET_PROVIDER_TAXONOMY = Object.freeze({
    tiktok: Object.freeze({forbidden_events:new Set(["subscribe","cheer","membership","super_chat"]),forbidden_metric_prefixes:["twitch.","youtube."]}),
    twitch: Object.freeze({forbidden_events:new Set(["gift","share","like","viewer","membership","super_chat"]),forbidden_metric_prefixes:["live.likes","live.gifts","live.shares","live.viewers","profile.likes","youtube."]}),
    youtube: Object.freeze({forbidden_events:new Set(["gift","share","like","viewer","follow","subscribe","cheer"]),forbidden_metric_prefixes:["live.likes","live.gifts","live.shares","live.viewers","profile.likes","twitch."]}),
    obs: Object.freeze({forbidden_events:new Set(["gift","share","subscribe","cheer","membership","super_chat"]),forbidden_metric_prefixes:["live.","profile.","twitch.","youtube."]})
});
function assertWidgetProviderTaxonomy() {
    for (const item of Object.values(WIDGET_STUDIO_WIDGET_TYPES)) {
        const provider=String(item.provider||"").toLowerCase();
        const rules=WIDGET_PROVIDER_TAXONOMY[provider];
        if(!rules)throw new Error(`widget_provider_unknown:${item.key}`);
        const areas=Array.isArray(item.studio_areas)?item.studio_areas:[];
        if(areas.length!==1||areas[0]!==provider)throw new Error(`widget_provider_area_mismatch:${item.key}`);
        const eventType=String(item.event_type||"").toLowerCase();
        if(eventType&&rules.forbidden_events.has(eventType))throw new Error(`widget_provider_event_mismatch:${item.key}`);
        const metrics=[item.metric,...(Array.isArray(item.metric_options)?item.metric_options:[])].map(v=>String(v||"")).filter(Boolean);
        if(metrics.some(metric=>rules.forbidden_metric_prefixes.some(prefix=>metric.startsWith(prefix))))throw new Error(`widget_provider_metric_mismatch:${item.key}`);
    }
}
assertWidgetProviderTaxonomy();

const WIDGET_STUDIO_WIDGET_TYPE_KEYS =
    new Set(Object.keys(WIDGET_STUDIO_WIDGET_TYPES));

function studioWidgetDefinition(value) {
    const key = String(value || "follower_goal");
    return WIDGET_STUDIO_WIDGET_TYPES[key] || WIDGET_STUDIO_WIDGET_TYPES.follower_goal;
}

function studioWidgetProvider(item={}) {
    const explicit=String(item.provider||"").toLowerCase();
    if (["tiktok","twitch","youtube","obs"].includes(explicit)) return explicit;
    if (item.source_kind === "static" || item.source_kind === "manual") return "obs";
    return "tiktok";
}

function studioWidgetRequiredScopes(item={}) {
    const many=Array.isArray(item.required_scopes)?item.required_scopes:[];
    const one=String(item.required_scope||"").trim();
    return [...new Set([...many,one].map(value=>String(value||"").trim()).filter(Boolean))];
}

async function requireWidgetProviderBetaAccess(accountOrId,definition){
    const provider=studioWidgetProvider(definition);
    if(["tiktok","twitch"].includes(provider))return requireProviderBetaAccess(accountOrId,provider);
    return creatorAccessProfile(accountOrId);
}

function studioWidgetRegistryPublic(plan = "free", entitlements = null, providerAccess = null) {
    const effective=entitlements||getPlanEntitlements(plan);
    const hasProviderFilter=providerAccess&&typeof providerAccess==="object";
    const connected={
        obs:true,
        tiktok:Boolean(providerAccess?.tiktok?.connected)&&providerAccess?.tiktok?.beta_access?.allowed!==false,
        twitch:Boolean(providerAccess?.twitch?.connected)&&providerAccess?.twitch?.beta_access?.allowed!==false,
        youtube:Boolean(providerAccess?.youtube?.connected)
    };
    const providerScopes={
        twitch:new Set(Array.isArray(providerAccess?.twitch?.scopes)?providerAccess.twitch.scopes:[]),
        youtube:new Set(Array.isArray(providerAccess?.youtube?.scopes)?providerAccess.youtube.scopes:[])
    };
    return Object.values(WIDGET_STUDIO_WIDGET_TYPES).map((item) => {
        const minimumPlan=item.minimum_plan||"free";
        const provider=studioWidgetProvider(item);
        const platform=item.platform || provider;
        const studioAreas=Array.isArray(item.studio_areas)&&item.studio_areas.length
            ? [...new Set(item.studio_areas.filter(area => ["tiktok","twitch","youtube","obs"].includes(area)))]
            : [platform];
        const planAvailable=item.mode === "static"
            ? Boolean(effective.widget_studio)
            : minimumPlan==="free"
                ? true
                : (["alert","latest","goal_alert"].includes(item.mode)?Boolean(effective.alerts):Boolean(effective.live_widgets));
        const requiredScopes=studioWidgetRequiredScopes(item);
        const grantedScopes=providerScopes[provider]||new Set();
        const scopeAvailable=requiredScopes.length===0||requiredScopes.every(scope=>grantedScopes.has(scope));
        const providerConnected=!hasProviderFilter||connected[provider]===true;
        return {...item,provider,platform,studio_areas:studioAreas,minimum_plan:minimumPlan,required_scopes:requiredScopes,available:planAvailable&&providerConnected&&scopeAvailable,provider_connected:providerConnected,scope_available:scopeAvailable,metric_options:Array.isArray(item.metric_options)?[...item.metric_options]:undefined};
    }).filter(item=>!hasProviderFilter||item.provider==="obs"||item.provider_connected);
}

