app.get("/api/plans/catalog",async(_req,res)=>{
    res.set("Cache-Control","public, max-age=120");
    const plans=publicPlanCatalog().map(plan=>{
        const checkoutAvailable=Boolean(COMMERCIAL_MODE && BILLING_CONFIG.plans?.[plan.key]?.checkout_available);
        return {...plan,price_status:plan.key==="free"?"active":checkoutAvailable?"active":"private_beta",checkout_available:checkoutAvailable};
    });
    return res.json({
        ok:true,
        private_beta:true,
        commercial_mode:COMMERCIAL_MODE,
        billing_enabled:Boolean(COMMERCIAL_MODE && BILLING_CONFIG.enabled),
        checkout_available:Boolean(COMMERCIAL_MODE && BILLING_CONFIG.checkout_available),
        provider:BILLING_CONFIG.provider,
        webhook_ready:Boolean(COMMERCIAL_MODE && BILLING_CONFIG.webhook_ready),
        grace_days:BILLING_CONFIG.grace_days,
        plans
    });
});

app.get("/api/public/legal/status",(_req,res)=>{
    res.set("Cache-Control","public, max-age=300");
    return res.json({
        ok:true,
        private_beta:true,
        commercial_mode:COMMERCIAL_MODE,
        paid_checkout_enabled:Boolean(COMMERCIAL_MODE && BILLING_CONFIG.checkout_available),
        minimum_age:PRIVATE_BETA_MINIMUM_AGE,
        terms_version:LEGAL_TERMS_VERSION,
        privacy_notice_version:LEGAL_PRIVACY_NOTICE_VERSION,
        beta_notice_version:LEGAL_BETA_NOTICE_VERSION,
        optional_tracking_enabled:false,
        advertising_tracking_enabled:false
    });
});

