app.post(
    "/api/account/register",

    accountRegisterLimiter,

    async (
        req,
        res
    ) => {

        res.set(
            "Cache-Control",
            "no-store"
        );

        try {

            const email =
                normalizeEmail(
                    req.body?.email
                );

            const password =
                String(
                    req.body?.password ||
                    ""
                );

            const displayName =
                normalizeDisplayName(
                    req.body?.display_name
                );

            const legalFlag = value => value === true || String(value || "").trim().toLowerCase() === "true" || String(value || "").trim().toLowerCase() === "on";
            const termsAccepted = legalFlag(req.body?.terms_accepted);
            const privacyAcknowledged = legalFlag(req.body?.privacy_acknowledged);
            const betaAcknowledged = legalFlag(req.body?.beta_acknowledged);
            const ageConfirmed = legalFlag(req.body?.age_18_confirmed);

            if (!termsAccepted || !privacyAcknowledged || !betaAcknowledged) {
                return res.status(400).json({
                    ok:false,
                    code:"legal_acceptance_required",
                    error:"Bitte bestätige Nutzungsbedingungen, Datenschutzhinweise und Beta-Hinweis."
                });
            }

            if (!ageConfirmed) {
                return res.status(400).json({
                    ok:false,
                    code:"minimum_age_required",
                    error:`Die geschlossene Beta ist derzeit nur für Personen ab ${PRIVATE_BETA_MINIMUM_AGE} Jahren freigegeben.`
                });
            }


            if (
                !validEmail(
                    email
                )
            ) {

                return res
                    .status(400)
                    .json({

                        ok:
                            false,

                        error:
                            "Bitte gib eine gültige E-Mail-Adresse ein."

                    });

            }


            if (
                password.length <
                PASSWORD_MIN_LENGTH
            ) {

                return res
                    .status(400)
                    .json({

                        ok:
                            false,

                        error:
                            `Das Passwort muss mindestens ${PASSWORD_MIN_LENGTH} Zeichen lang sein.`

                    });

            }


            if (
                password.length >
                PASSWORD_MAX_LENGTH
            ) {

                return res
                    .status(400)
                    .json({

                        ok:
                            false,

                        error:
                            `Das Passwort darf höchstens ${PASSWORD_MAX_LENGTH} Zeichen lang sein.`

                    });

            }


            if (
                !displayName
            ) {

                return res
                    .status(400)
                    .json({

                        ok:
                            false,

                        error:
                            "Bitte gib einen Creator-Namen ein."

                    });

            }


            const passwordPolicyProblem =
                passwordPolicyError(
                    password,
                    {
                        email,
                        displayName
                    }
                );

            if (
                passwordPolicyProblem
            ) {

                return res
                    .status(400)
                    .json({
                        ok: false,
                        error: passwordPolicyProblem
                    });

            }


            const existing =
                await findCreatorByEmail(
                    email
                );

            if (
                existing
            ) {

                return res
                    .status(409)
                    .json({

                        ok:
                            false,

                        error:
                            "Die Registrierung konnte nicht abgeschlossen werden. Falls bereits ein Konto existiert, melde dich bitte an."

                    });

            }


            const passwordRecord =
                await createPasswordHash(
                    password
                );

            const creatorId =
                createCreatorAccountId();


            const result =
                await pool.query(
                    `
                    INSERT INTO creator_accounts (

                        id,
                        email,
                        password_hash,
                        password_salt,
                        password_kdf_version,
                        display_name,
                        plan,
                        status,
                        email_verified_at,
                        created_at,
                        updated_at

                    )

                    VALUES (
                        $1,
                        $2,
                        $3,
                        $4,
                        $5,
                        $6,
                        'free',
                        $7,
                        NULL,
                        NOW(),
                        NOW()
                    )

                    RETURNING
                        id,
                        email,
                        display_name,
                        plan,
                        status,
                        email_verified_at,
                        created_at,
                        updated_at
                    `,
                    [
                        creatorId,
                        email,
                        passwordRecord.hash,
                        passwordRecord.salt,
                        passwordRecord.kdfVersion,
                        displayName,
                        ACCOUNT_MAIL_CONFIG.verificationRequired ? "pending_email" : "active"
                    ]
                );


            const account =
                result.rows[0];


            await saveCreatorSettings(
                creatorId,
                defaultCreatorSettings()
            );


            await recordSecurityEvent(
                creatorId,
                "account_registered"
            );
            await recordSecurityEvent(creatorId,`legal_terms_${LEGAL_TERMS_VERSION}_accepted`);
            await recordSecurityEvent(creatorId,`privacy_notice_${LEGAL_PRIVACY_NOTICE_VERSION}_acknowledged`);
            await recordSecurityEvent(creatorId,`beta_notice_${LEGAL_BETA_NOTICE_VERSION}_acknowledged`);
            await recordSecurityEvent(creatorId,`minimum_age_${PRIVATE_BETA_MINIMUM_AGE}_confirmed`);

            if (ACCOUNT_MAIL_CONFIG.verificationRequired) {
                const verification = await issueAccountActionToken(creatorId,"verify_email",EMAIL_VERIFICATION_TOKEN_TTL_MS);
                await queueAccountMail(verificationMailMessage(account, verification.token),{creatorId});
                await recordSecurityEvent(creatorId,"email_verification_requested");
            } else {
                await createCreatorSession(
                    res,
                    creatorId,
                    "registration"
                );
            }

            // Neue Creator werden während der geschlossenen Provider-Beta automatisch
            // als Pending-Kandidat geführt. Der Admin schaltet TikTok/Twitch danach
            // gezielt frei; Admin-Konten selbst brauchen keine Beta-Freigabe.
            const access=await creatorAccessProfile(account);

            return res
                .status(201)
                .json({

                    ok:
                        true,

                    authenticated:
                        !ACCOUNT_MAIL_CONFIG.verificationRequired,

                    verification_required:
                        ACCOUNT_MAIL_CONFIG.verificationRequired,

                    account:
                        publicCreatorAccount(
                            account
                        ),

                    entitlements:
                        access.entitlements,

                    access,

                    modules:
                        publicModuleRegistry(
                            account,
                            access.entitlements
                        )

                });

        }
        catch (error) {

            safeLogError("Creator Registrierung Fehler:",error);

            if (
                error?.code ===
                "23505"
            ) {

                return res
                    .status(409)
                    .json({

                        ok:
                            false,

                        error:
                            "Die Registrierung konnte nicht abgeschlossen werden. Falls bereits ein Konto existiert, melde dich bitte an."

                    });

            }

            return res
                .status(500)
                .json({

                    ok:
                        false,

                    error:
                        "Das Creator-Konto konnte nicht erstellt werden."

                });

        }

    }
);


