app.put(
    "/api/creator/settings",

    requireCreatorAccount,

    async (
        req,
        res
    ) => {

        res.set(
            "Cache-Control",
            "no-store"
        );

        try {

            const settings =
                sanitizeCreatorSettings(
                    req.body?.settings
                );


            const plan =
                normalizePlan(
                    req.creatorAccount.plan
                );


            const entitlements =
                getPlanEntitlements(
                    plan
                );


            // ------------------------------------------------
            // Theme serverseitig prüfen
            // ------------------------------------------------

            if (
                settings?.profile?.theme &&
                !entitlements
                    .themes
                    .includes(
                        settings.profile.theme
                    )
            ) {

                return res
                    .status(403)
                    .json({

                        ok:
                            false,

                        error:
                            "Dieses Theme ist für deinen aktuellen Plan nicht freigeschaltet."

                    });

            }


            const result =
                await saveCreatorSettings(
                    req.creatorAccount.id,
                    settings
                );


            return res.json({

                ok:
                    true,

                settings:
                    result.settings,

                updated_at:
                    result.updated_at

            });

        }
        catch (error) {

            return res
                .status(500)
                .json({

                    ok:
                        false,

                    ...clientSafeErrorPayload(req,error,500,"Creator-Einstellungen konnten nicht gespeichert werden.")

                });

        }

    }
);


