app.get(
    "/api/creator/widget-studio/widgets",
    requireCreatorAccount,
    async (req, res) => {

        res.set("Cache-Control", "no-store");

        try {

            const rows =
                await listStudioWidgets(
                    req.creatorAccount.id
                );

            const tiktok =
                await getFollowerWidgetTikTokData(
                    req.creatorAccount.id
                );

            const access=await creatorAccessProfile(req.creatorAccount);
            const entitlements=access.entitlements;
            const providerAccess=await creatorWidgetProviderAccess(req.creatorAccount.id);
            const [twitchConnection,youtubeConnection,youtubeLive]=await Promise.all([getTwitchConnection(req.creatorAccount.id),getYouTubeConnection(req.creatorAccount.id),getProviderLiveState(req.creatorAccount.id,"youtube")]);

            const live =
                await getStudioLiveState(
                    req.creatorAccount.id
                );
            const visibleRows=rows.filter(row=>{
                const provider=studioWidgetProvider(studioWidgetDefinition(row.widget_type));
                return provider==="obs"||providerAccess?.[provider]?.connected===true;
            });

            return res.json({
                ok: true,
                widgets:
                    visibleRows.map(publicStudioWidgetRow),
                tiktok,
                twitch: publicTwitchConnection(twitchConnection),
                youtube: publicYouTubeConnection(youtubeConnection,youtubeLive),
                provider_access:providerAccess,
                live,
                bridge: await getStudioBridgeStatus(req.creatorAccount.id),
                registry: studioWidgetRegistryPublic(req.creatorAccount.plan,entitlements,providerAccess),
                access,
                providers: studioProviderRegistryPublic(),
                sessions: await getStudioLiveSessions(req.creatorAccount.id, 5),
                interactions: await listStudioInteractionRules(req.creatorAccount.id),
                plan: normalizePlan(req.creatorAccount.plan),
                limits:{max_widgets:entitlements.max_widgets,max_scenes:entitlements.max_scenes},
                entitlements
            });

        }
        catch (error) {

            safeLogError("Widget Studio Liste Fehler:",error);

            return res.status(500).json({
                ok: false,
                error: "Widgets konnten nicht geladen werden."
            });

        }

    }
);

