  if(cfg.scenes)items.push({kind:"scene_template",key:platform==="tiktok"?"tiktok-live":"landscape-live",platform:platform==="tiktok"?"tiktok":"neutral"},{kind:"scene_template",key:"landscape-break",platform:"neutral"});
