const CFS_ADMIN_CONVERTER_OUTPUT_MODES=new Set(["bundle_only","singles_only","bundle_and_singles"]);
const CFS_ADMIN_CONVERTER_TYPES=new Set(["stream_status","overlays","panels","widgets","creator_pack"]);
