    if(!item||!CFS_STORE_ALLOWED_PACKAGE_KINDS.has(String(item.kind||""))||!/^[a-z0-9_-]{1,80}$/.test(String(item.key||"")))throw new Error("Paket enthält einen nicht erlaubten Eintrag.");
