  if(["widget_template","overlay_template"].includes(kind))return Boolean((await client.query(`SELECT 1 FROM creator_widgets WHERE id=$1 AND creator_id=$2 AND widget_type=$3 LIMIT 1`,[ref,creatorId,key])).rows[0]);
