app.get("/api/creator/shop/products/:id",requireCreatorAccount,async(req,res)=>{
  res.set("Cache-Control","no-store");await refreshDynamicStoreProducts();const product=cfsStoreProduct(req.params.id);if(!product)return res.status(404).json({ok:false,error:"Produkt nicht gefunden."});
  try{
    validateStoreProduct(product);const stored=normalizeStoreState((await getModuleState(req.creatorAccount.id,"shop")).state),library_item=stored.library.find(item=>item.product_id===product.id)||null;let version_history=[],related_offers=[];
    if(product.admin_generated){
      version_history=(await pool.query(`SELECT version,release_notes,created_at,published_at FROM admin_store_product_versions WHERE product_id=$1 AND published_at IS NOT NULL ORDER BY created_at DESC LIMIT 20`,[product.id])).rows;
      const rows=(await pool.query(`SELECT p.*,a.public_token AS asset_public_token FROM admin_store_products p LEFT JOIN admin_bundle_assets a ON a.id=p.source_asset_id WHERE p.status='published' AND p.offer_enabled=TRUE AND (p.parent_bundle_id=$1 OR p.id=$2) ORDER BY p.offer_type,p.title`,[product.id,product.parent_bundle_id||""])).rows;
      related_offers=rows.map(adminStoreRowToProduct).map(publicStoreProduct);
    }
    const childSum=related_offers.filter(x=>x.parent_bundle_id===product.id&&x.list_price_cents>0).reduce((sum,x)=>sum+x.list_price_cents,0),bundle_savings_cents=product.offer_type==="bundle"&&product.list_price_cents>0&&childSum>product.list_price_cents?childSum-product.list_price_cents:0;
    return res.json({ok:true,commercial_mode:COMMERCIAL_MODE,product:publicStoreProduct(product),library_item:publicStoreLibraryItem(library_item),workflow_links:storeWorkflowLinks(library_item,product.id),version_history,related_offers,bundle_savings_cents});
  }catch(error){safeLogError("Creator Shop Produktdetail Fehler:",error);return res.status(400).json({ok:false,error:"Produktdetail konnte nicht geladen werden."});}
});
app.post("/api/creator/shop/products/:id/acquire",requireCreatorAccount,async(req,res)=>{res.set("Cache-Control","no-store");await refreshDynamicStoreProducts();const product=cfsStoreProduct(req.params.id);if(!product)return res.status(404).json({ok:false,error:"Produkt nicht gefunden."});if(!["free","beta"].includes(product.pricing_mode))return res.status(403).json({ok:false,error:"Dieses Produkt ist in der privaten Beta noch nicht verfügbar."});try{validateStoreProduct(product);const out=await mutateStoreState(req.creatorAccount.id,async state=>{let item=state.library.find(entry=>entry.product_id===product.id);if(!item){item={product_id:product.id,entitlement:"beta",acquired_at:new Date().toISOString(),installed_version:"",installed_at:null,install_state:"library",installed_items:[],last_install_attempt_at:null,install_generation:0};state.library.unshift(item);}return item;});return res.json({ok:true,product:publicStoreProduct(product),library:out.state.library.map(publicStoreLibraryItem)});}catch(error){safeLogError("Creator Shop Acquire Fehler:",error);return res.status(400).json({ok:false,error:"Produkt konnte nicht hinzugefügt werden."});}});
async function handleStoreInstallAction(req,res,mode){res.set("Cache-Control","no-store");await refreshDynamicStoreProducts();const product=cfsStoreProduct(req.params.id);if(!product)return res.status(404).json({ok:false,error:"Produkt nicht gefunden."});if(!["free","beta"].includes(product.pricing_mode))return res.status(403).json({ok:false,error:"Dieses Produkt ist noch nicht installierbar."});try{validateStoreProduct(product);const stored=normalizeStoreState((await getModuleState(req.creatorAccount.id,"shop")).state),owned=stored.library.some(item=>item.product_id===product.id);if(["update","reinstall"].includes(mode)&&!owned)return res.status(409).json({ok:false,error:"Füge das Produkt zuerst deiner Bibliothek hinzu."});const [access,providerAccess]=await Promise.all([creatorAccessProfile(req.creatorAccount),creatorWidgetProviderAccess(req.creatorAccount.id)]);const out=await mutateStoreState(req.creatorAccount.id,(state,client)=>installStorePackage(req.creatorAccount,product,state,client,{access,providerAccess,mode}));const result=out.result;return res.json({ok:true,installed:result.complete,partial:!result.complete,product:publicStoreProduct(product),library:out.state.library.map(publicStoreLibraryItem),library_item:publicStoreLibraryItem(out.state.library.find(item=>item.product_id===product.id)||null),workflow_links:storeWorkflowLinks(out.state.library.find(item=>item.product_id===product.id)||null,product.id),install_summary:{installed:result.installed_count,pending:result.pending_count,retired:result.retired_count,stale_detected:result.stale_count,repaired:result.repaired_count,items:result.receipts,mode:result.mode},message:storeInstallMessage(result),launch_url:product.launch_url});}catch(error){safeLogError(`Creator Shop ${mode} Fehler:`,error);return res.status(400).json({ok:false,error:"Paket konnte nicht sicher verarbeitet werden."});}}
app.post("/api/creator/shop/products/:id/install",requireCreatorAccount,(req,res)=>handleStoreInstallAction(req,res,"install"));
app.post("/api/creator/shop/products/:id/update",requireCreatorAccount,(req,res)=>handleStoreInstallAction(req,res,"update"));
app.post("/api/creator/shop/products/:id/reinstall",requireCreatorAccount,(req,res)=>handleStoreInstallAction(req,res,"reinstall"));


