app.post("/auth/launcher/integrations/start",tiktokConnectLimiter,requireTrustedPublicWrite,async(req,res)=>{
    res.set("Cache-Control","no-store");
    res.set("Referrer-Policy","no-referrer");
    try{
        const provider=launcherProviderOAuthKey(req.body?.provider);
        const row=await consumeLauncherProviderOAuthHandoff(provider,req.body?.handoff);
        if(!row)return res.status(400).send(renderPage("Provider verbinden",`<p class="error">Der Launcher-Verbindungscode ist ungültig, abgelaufen oder wurde bereits verwendet.</p>`));
        if(["tiktok","twitch"].includes(provider)){
            try{await requireProviderBetaAccess(row.creator_id,provider)}catch(error){if(error?.code==="provider_beta_required")return res.status(403).send(renderPage("Beta-Freigabe",`<p class="error">${escapeHtml(error.message)}</p><p class="muted">Bitte warte auf die Freigabe durch den cfs_zockt Admin.</p>`));throw error}
        }
        if(provider==="tiktok")return await beginTikTokOAuth(res,row.creator_id);
        if(provider==="twitch")return await beginTwitchOAuth(res,row.creator_id);
        if(provider==="youtube")return await beginYouTubeOAuth(res,row.creator_id);
        return res.status(400).send(renderPage("Provider verbinden",`<p class="error">Provider wird noch nicht unterstützt.</p>`));
    }catch(error){
        safeLogError("Launcher Provider OAuth Start Fehler:",error);
        return res.status(500).send(renderPage("Provider verbinden",`<p class="error">Provider-Verbindung konnte nicht gestartet werden.</p>`));
    }
});

