app.get("/store-covers/:publicToken",publicRuntimeIpLimiter,widgetReadLimiter,async(req,res)=>{const token=String(req.params.publicToken||"");if(!/^[a-f0-9]{48}$/i.test(token))return res.status(404).end();try{const row=(await pool.query(`SELECT cover_mime,cover_content,cover_sha256 FROM admin_store_products WHERE cover_public_token=$1 AND status='published' LIMIT 1`,[token])).rows[0];if(!row?.cover_content)return res.status(404).end();const mime=String(row.cover_mime||"image/svg+xml");if(!new Set(["image/svg+xml","image/png","image/webp"]).has(mime))return res.status(415).end();res.set("Content-Type",mime);res.set("Cache-Control","private, max-age=300, must-revalidate");res.set("CDN-Cache-Control","no-store");res.set("Surrogate-Control","no-store");res.set("ETag",`"${String(row.cover_sha256||"")}"`);res.set("Content-Disposition","inline");res.set("X-Content-Type-Options","nosniff");return res.send(row.cover_content);}catch(error){safeLogError("Store Cover Public Fehler:",error);return res.status(500).end();}});
app.get("/store-assets/:publicToken",publicRuntimeIpLimiter,widgetReadLimiter,async(req,res)=>{const token=String(req.params.publicToken||"");if(!/^[a-f0-9]{48}$/i.test(token))return res.status(404).end();try{const row=(await pool.query(`SELECT mime_type,content,sha256 FROM admin_bundle_assets WHERE public_token=$1 AND rights_status='approved' AND shop_use_allowed=TRUE LIMIT 1`,[token])).rows[0];if(!row)return res.status(404).end();res.set("Content-Type",String(row.mime_type||"application/octet-stream"));res.set("Cache-Control","private, max-age=300, must-revalidate");res.set("CDN-Cache-Control","no-store");res.set("Surrogate-Control","no-store");res.set("ETag",`"${String(row.sha256||"")}"`);res.set("Content-Disposition","inline");res.set("X-Content-Type-Options","nosniff");return res.send(row.content);}catch(error){safeLogError("Store Asset Public Fehler:",error);return res.status(500).end();}});

app.get("/widget-assets/:publicToken",publicRuntimeIpLimiter,widgetReadLimiter,async(req,res)=>{
    const token=String(req.params.publicToken||"");
    if(!/^[a-f0-9]{48}$/i.test(token))return res.status(404).end();
    try{
        const result=await pool.query(`
            SELECT a.mime_type,a.content,a.sha256
            FROM creator_widget_assets a
            JOIN creator_accounts c ON c.id=a.creator_id
            WHERE a.public_token=$1 AND c.status='active'
            LIMIT 1
        `,[token]);
        const row=result.rows[0];
        if(!row)return res.status(404).end();
        res.set("Content-Type",String(row.mime_type||"application/octet-stream"));
        res.set("Cache-Control","private, max-age=300, must-revalidate");
        res.set("CDN-Cache-Control","no-store");
        res.set("Surrogate-Control","no-store");
        res.set("ETag",`"${String(row.sha256||"")}"`);
        res.set("Content-Disposition","inline");
        res.set("X-Content-Type-Options","nosniff");
        return res.send(row.content);
    }catch(error){
        safeLogError("Widget Asset Public Fehler:",error);
        return res.status(500).end();
    }
});

