app.get(
    "/api/widgets/studio/:publicToken",
    publicRuntimeIpLimiter,
    widgetReadLimiter,
    async (req, res) => {

        res.set("Cache-Control", "no-store");

        try {

            const row =
                await getPublicStudioWidget(
                    req.params.publicToken
                );

            if (!row) {
                return res.status(404).json({
                    ok: false,
                    error: "Widget nicht gefunden oder nicht veröffentlicht."
                });
            }

            const definition = studioWidgetDefinition(row.widget_type);
            const staticObs = definition.source_kind === "static";
            const manualOnly = definition.source_kind === "manual";
            const detachedData = staticObs || manualOnly;
            const widgetProvider=studioWidgetProvider(definition);
            if(["tiktok","twitch"].includes(widgetProvider)){
                const runtimeAccess=await creatorAccessProfile(row.creator_id);
                const betaAccess=providerBetaPolicy(runtimeAccess,widgetProvider);
                if(!betaAccess.allowed)return res.status(403).json({ok:false,code:"provider_beta_required",provider:widgetProvider,error:"Dieses Provider-Widget ist für diesen Creator derzeit nicht für die Beta freigeschaltet."});
            }
            const snapshot = detachedData
                ? null
                : await studioDataSnapshot(
                    row.creator_id,
                    widgetProvider
                );
            const publicSnapshot = detachedData
                ? {
                    profile: {
                        connected: false,
                        display_name: "",
                        avatar_url: "",
                        followers: 0,
                        likes_total: 0,
                        updated_at: null
                    },
                    live: {
                        connected: false,
                        provider: "none",
                        stale: true,
                        likes: 0,
                        viewers: 0,
                        shares: 0,
                        gifts_count: 0,
                        gifts_value: 0,
                        followers_gained: 0,
                        session_id: null,
                        last_event_at: null
                    },
                    bridge: {
                        configured: false,
                        online: false
                    }
                }
                : snapshot;
            const eventType = detachedData ? null : (definition.event_type || null);
            const events = eventType
                ? await getRecentStudioLiveEvents(row.creator_id, eventType, 20, snapshot.live.session_id, ["twitch","youtube"].includes(widgetProvider)?widgetProvider:null)
                : [];

            return res.json({
                ok: true,
                widget: {
                    id: row.id,
                    type: row.widget_type,
                    name: row.name,
                    definition,
                    config: sanitizeStudioWidgetConfig(row.published_config, row.widget_type),
                    published_at: row.published_at
                },
                creator: {
                    display_name:
                        (detachedData ? row.creator_display_name : publicSnapshot.profile.display_name) ||
                        row.creator_display_name ||
                        "Creator",
                    avatar_url:
                        detachedData ? "" : (publicSnapshot.profile.avatar_url || "")
                },
                data: publicSnapshot,
                events,
                tiktok: detachedData
                    ? {
                        connected: false,
                        display_name: "",
                        avatar_url: "",
                        follower_count: 0,
                        likes_count: 0,
                        updated_at: null
                    }
                    : widgetProvider === "tiktok" ? {
                        connected: publicSnapshot.profile.connected,
                        display_name: publicSnapshot.profile.display_name,
                        avatar_url: publicSnapshot.profile.avatar_url,
                        follower_count: publicSnapshot.profile.followers,
                        likes_count: publicSnapshot.profile.likes_total,
                        updated_at: publicSnapshot.profile.updated_at
                    } : {connected:false,display_name:"",avatar_url:"",follower_count:0,likes_count:0,updated_at:null},
                twitch: !detachedData && widgetProvider === "twitch" ? {
                    connected: publicSnapshot.profile.connected,
                    display_name: publicSnapshot.profile.display_name,
                    avatar_url: publicSnapshot.profile.avatar_url,
                    updated_at: publicSnapshot.profile.updated_at
                } : {connected:false,display_name:"",avatar_url:"",updated_at:null},
                live: publicSnapshot.live,
                bridge: publicSnapshot.bridge
            });

        }
        catch (error) {

            safeLogError("Widget Studio Public Fehler:",error);

            return res.status(500).json({
                ok: false,
                error: "Widget-Daten konnten nicht geladen werden."
            });

        }

    }
);


