let twitchRuntimeWorkerTimer=null;
let twitchRuntimeWorkerPromise=null;

async function runTwitchRuntimeReconcile(){
    if(twitchRuntimeWorkerPromise||!twitchConfigured())return twitchRuntimeWorkerPromise;
    twitchRuntimeWorkerPromise=(async()=>{
        const rows=(await pool.query(`SELECT creator_id FROM twitch_connections WHERE connected=TRUE ORDER BY COALESCE(last_runtime_checked_at,0) ASC LIMIT $1`,[TWITCH_RUNTIME_RECONCILE_BATCH])).rows;
        for(const item of rows){
            try{
                const betaAccess=await requireProviderBetaAccess(item.creator_id,"twitch").catch(()=>null);
                if(!betaAccess)continue;
                const connection=await ensureValidTwitchConnection(item.creator_id);
                if(connection?.connected)await ensureTwitchEventSubSubscriptions(item.creator_id,connection);
            }catch(error){
                await pool.query(`UPDATE twitch_connections SET runtime_error=$2,last_runtime_checked_at=$3,updated_at=NOW() WHERE creator_id=$1`,[item.creator_id,String(error?.message||error).slice(0,240),Date.now()]).catch(()=>{});
                safeLogError("Twitch Runtime Reconcile Warnung:",error);
            }
        }
    })().finally(()=>{twitchRuntimeWorkerPromise=null});
    return twitchRuntimeWorkerPromise;
}

function startTwitchRuntimeWorker(){
    if(twitchRuntimeWorkerTimer||!twitchConfigured())return;
    twitchRuntimeWorkerTimer=setInterval(()=>{void runTwitchRuntimeReconcile()},TWITCH_RUNTIME_RECONCILE_INTERVAL_MS);
    twitchRuntimeWorkerTimer.unref?.();
    setTimeout(()=>{void runTwitchRuntimeReconcile()},10_000).unref?.();
}

async function stopTwitchRuntimeWorker(){
    if(twitchRuntimeWorkerTimer){clearInterval(twitchRuntimeWorkerTimer);twitchRuntimeWorkerTimer=null;}
    if(twitchRuntimeWorkerPromise)await Promise.race([twitchRuntimeWorkerPromise,new Promise(resolve=>setTimeout(resolve,10_000))]);
}

// ============================================================
// TWITCH OAUTH / ACCOUNT LINK
// ============================================================

function twitchConfigured(){
    return Boolean(TWITCH_CLIENT_ID && TWITCH_CLIENT_SECRET && TWITCH_REDIRECT_URI);
}

async function getTwitchConnection(creatorId){
    const result=await pool.query(`SELECT * FROM twitch_connections WHERE creator_id=$1 LIMIT 1`,[normalizeCreatorId(creatorId)]);
    const row=result.rows[0];
    if(!row)return null;
    return {...row,access_token:row.access_token?decryptSecret(row.access_token):"",refresh_token:row.refresh_token?decryptSecret(row.refresh_token):""};
}

function publicTwitchConnection(row){
    const scopes=String(row?.scope||"").split(/[\s,]+/).map(v=>v.trim()).filter(Boolean);
    const missingScopes=TWITCH_EVENTSUB_REQUIRED_SCOPES.filter(scope=>!scopes.includes(scope));
    const streamTargetMissing=TWITCH_STREAM_TARGET_SCOPES.filter(scope=>!scopes.includes(scope));
    return {
        connected:Boolean(row?.connected),
        account:{user_id:row?.twitch_user_id||"",login:row?.login||"",display_name:row?.display_name||"",profile_image_url:row?.profile_image_url||""},
        scopes,
        required_scopes:[...TWITCH_EVENTSUB_REQUIRED_SCOPES],
        missing_scopes:missingScopes,
        scope_ready:Boolean(row?.connected)&&missingScopes.length===0,
        stream_target:{
            automatic_import:true,
            required_scopes:[...TWITCH_STREAM_TARGET_SCOPES],
            missing_scopes:streamTargetMissing,
            ready:Boolean(row?.connected)&&streamTargetMissing.length===0,
            reauth_required:Boolean(row?.connected)&&streamTargetMissing.length>0
        },
        validated_at:row?.last_validated_at?new Date(Number(row.last_validated_at)).toISOString():null,
        updated_at:row?.updated_at||null,
        configured:twitchConfigured(),
        runtime_checked_at:row?.last_runtime_checked_at?new Date(Number(row.last_runtime_checked_at)).toISOString():null,
        runtime_error:studioText(row?.runtime_error,240,""),
        runtime:{eventsub_implemented:true,eventsub_ready:false,chat_events_implemented:true,production_ready:false}
    };
}

async function twitchFetch(url,options={}){
    const controller=new AbortController();
    const timer=setTimeout(()=>controller.abort(),15000);
    try{
        const response=await fetch(url,{...options,signal:controller.signal});
        const text=await response.text();
        let data={}; try{data=text?JSON.parse(text):{}}catch{data={message:text.slice(0,300)}}
        if(!response.ok){const error=new Error(String(data?.message||data?.error||`Twitch HTTP ${response.status}`));error.status=response.status;error.payload=data;throw error;}
        return data;
    }finally{clearTimeout(timer)}
}

async function saveTwitchTokens(creatorId,data,existing=null){
    const now=Date.now();
    const refresh=String(data.refresh_token||existing?.refresh_token||"").trim();
    await pool.query(`
        INSERT INTO twitch_connections(creator_id,connected,access_token,refresh_token,access_expires_at,scope,last_validated_at,updated_at)
        VALUES($1,TRUE,$2,$3,$4,$5,$6,NOW())
        ON CONFLICT(creator_id) DO UPDATE SET connected=TRUE,access_token=EXCLUDED.access_token,
          refresh_token=COALESCE(EXCLUDED.refresh_token,twitch_connections.refresh_token),access_expires_at=EXCLUDED.access_expires_at,
          scope=EXCLUDED.scope,last_validated_at=EXCLUDED.last_validated_at,updated_at=NOW()
    `,[normalizeCreatorId(creatorId),encryptSecret(String(data.access_token||"")),refresh?encryptSecret(refresh):null,
       now+Math.max(0,Number(data.expires_in||0))*1000,Array.isArray(data.scope)?data.scope.join(" "):String(data.scope||existing?.scope||""),now]);
}

async function validateTwitchToken(accessToken){
    return twitchFetch(TWITCH_VALIDATE_URL,{headers:{Authorization:`OAuth ${accessToken}`}});
}

async function refreshTwitchTokens(creatorId,connection){
    if(!connection?.refresh_token)throw new Error("Twitch Refresh-Token fehlt.");
    const body=new URLSearchParams({grant_type:"refresh_token",refresh_token:connection.refresh_token,client_id:TWITCH_CLIENT_ID,client_secret:TWITCH_CLIENT_SECRET});
    const data=await twitchFetch(TWITCH_TOKEN_URL,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body});
    await saveTwitchTokens(creatorId,data,connection);
    return getTwitchConnection(creatorId);
}

async function ensureValidTwitchConnection(creatorId){
    let connection=await getTwitchConnection(creatorId);
    if(!connection?.connected||!connection.access_token)return connection;
    const now=Date.now();
    if(Number(connection.access_expires_at||0) <= now+TWITCH_TOKEN_SAFETY_WINDOW_MS){
        connection=await refreshTwitchTokens(creatorId,connection);
    }
    if(!connection.last_validated_at || now-Number(connection.last_validated_at)>TWITCH_VALIDATE_INTERVAL_MS){
        try{
            const validation=await validateTwitchToken(connection.access_token);
            if(validation.client_id!==TWITCH_CLIENT_ID)throw new Error("Twitch Token gehört nicht zu dieser Anwendung.");
            await pool.query(`UPDATE twitch_connections SET twitch_user_id=COALESCE($2,twitch_user_id),login=COALESCE($3,login),scope=$4,last_validated_at=$5,updated_at=NOW() WHERE creator_id=$1`,
              [normalizeCreatorId(creatorId),validation.user_id||null,validation.login||null,Array.isArray(validation.scopes)?validation.scopes.join(" "):connection.scope,now]);
            connection=await getTwitchConnection(creatorId);
        }catch(error){
            if(Number(error?.status)===401){
                connection=await refreshTwitchTokens(creatorId,connection);
                const validation=await validateTwitchToken(connection.access_token);
                await pool.query(`UPDATE twitch_connections SET twitch_user_id=COALESCE($2,twitch_user_id),login=COALESCE($3,login),scope=$4,last_validated_at=$5,updated_at=NOW() WHERE creator_id=$1`,
                  [normalizeCreatorId(creatorId),validation.user_id||null,validation.login||null,Array.isArray(validation.scopes)?validation.scopes.join(" "):connection.scope,Date.now()]);
                connection=await getTwitchConnection(creatorId);
            }else throw error;
        }
    }
    return connection;
}

async function syncTwitchProfile(creatorId,connection=null){
    const row=connection||await ensureValidTwitchConnection(creatorId);
    if(!row?.access_token)return row;
    const data=await twitchFetch(TWITCH_USERS_URL,{headers:{Authorization:`Bearer ${row.access_token}`,"Client-Id":TWITCH_CLIENT_ID}});
    const user=Array.isArray(data?.data)?data.data[0]:null;
    if(user){
        try{await assertProviderAccountAvailable("twitch",user.id,creatorId)}catch(error){
            if(error?.code==="provider_account_in_use")await pool.query(`DELETE FROM twitch_connections WHERE creator_id=$1`,[normalizeCreatorId(creatorId)]);
            throw error;
        }
        await pool.query(`UPDATE twitch_connections SET twitch_user_id=$2,login=$3,display_name=$4,profile_image_url=$5,updated_at=NOW() WHERE creator_id=$1`,
          [normalizeCreatorId(creatorId),String(user.id||""),String(user.login||""),String(user.display_name||""),String(user.profile_image_url||"")]);
    }
    return getTwitchConnection(creatorId);
}


const twitchAppTokenCache={token:"",expires_at:0};

function twitchEventSubSecret(){
    if(!TWITCH_CLIENT_SECRET)return"";
    return crypto.createHmac("sha256",TWITCH_CLIENT_SECRET).update("cfs_zockt:twitch:eventsub:v1").digest("hex");
}

async function twitchAppAccessToken(){
    if(twitchAppTokenCache.token&&twitchAppTokenCache.expires_at>Date.now()+120000)return twitchAppTokenCache.token;
    const body=new URLSearchParams({client_id:TWITCH_CLIENT_ID,client_secret:TWITCH_CLIENT_SECRET,grant_type:"client_credentials"});
    const data=await twitchFetch(TWITCH_TOKEN_URL,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body});
    twitchAppTokenCache.token=String(data.access_token||"");
    twitchAppTokenCache.expires_at=Date.now()+Math.max(0,Number(data.expires_in||0))*1000;
    return twitchAppTokenCache.token;
}

const TWITCH_EVENTSUB_DEFINITIONS=Object.freeze([
    {type:"stream.online",version:"1",scopes:[]},
    {type:"stream.offline",version:"1",scopes:[]},
    {type:"channel.follow",version:"2",scopes:["moderator:read:followers"]},
    {type:"channel.subscribe",version:"1",scopes:["channel:read:subscriptions"]},
    {type:"channel.subscription.message",version:"1",scopes:["channel:read:subscriptions"]},
    {type:"channel.subscription.gift",version:"1",scopes:["channel:read:subscriptions"]},
    {type:"channel.cheer",version:"1",scopes:["bits:read"]},
    {type:"channel.chat.message",version:"1",scopes:["user:read:chat","user:bot","channel:bot"]}
]);

function twitchEventSubScopes(definition={}){
    const many=Array.isArray(definition.scopes)?definition.scopes:[];
    const one=String(definition.scope||"").trim();
    return [...new Set([...many,one].map(value=>String(value||"").trim()).filter(Boolean))];
}

function twitchEventSubCondition(type,broadcasterUserId){
    const id=String(broadcasterUserId||"");
    const condition={broadcaster_user_id:id};
    if(type==="channel.follow")condition.moderator_user_id=id;
    if(type==="channel.chat.message")condition.user_id=id;
    return condition;
}

async function getTwitchEventSubStatus(creatorId){
    const rows=(await pool.query(`SELECT subscription_type,subscription_id,status,required_scope,last_error,updated_at FROM twitch_eventsub_subscriptions WHERE creator_id=$1 ORDER BY subscription_type`,[normalizeCreatorId(creatorId)])).rows;
    const enabled=new Set(rows.filter(row=>String(row.status)==="enabled").map(row=>row.subscription_type));
    const expected=TWITCH_EVENTSUB_DEFINITIONS.map(item=>item.type);
    return {
        implemented:true,
        callback_url:TWITCH_EVENTSUB_CALLBACK_URL,
        enabled_count:enabled.size,
        expected_count:expected.length,
        ready:expected.every(type=>enabled.has(type)),
        subscriptions:rows.map(row=>({type:row.subscription_type,status:row.status,required_scope:row.required_scope||"",error:row.last_error||"",updated_at:row.updated_at||null}))
    };
}

async function upsertTwitchEventSubStatus(creatorId,definition,{subscriptionId=null,status="pending",error=""}={}){
    await pool.query(`
        INSERT INTO twitch_eventsub_subscriptions(creator_id,subscription_type,subscription_id,status,required_scope,last_error,updated_at)
        VALUES($1,$2,$3,$4,$5,$6,NOW())
        ON CONFLICT(creator_id,subscription_type) DO UPDATE SET
          subscription_id=COALESCE(EXCLUDED.subscription_id,twitch_eventsub_subscriptions.subscription_id),
          status=EXCLUDED.status,required_scope=EXCLUDED.required_scope,last_error=EXCLUDED.last_error,updated_at=NOW()
    `,[normalizeCreatorId(creatorId),definition.type,subscriptionId,status,twitchEventSubScopes(definition).join(" "),String(error||"").slice(0,400)]);
}

async function listTwitchEventSubSubscriptionsForUser(broadcasterUserId,appToken){
    const all=[];
    let after="";
    for(let page=0;page<10;page+=1){
        const params=new URLSearchParams({user_id:String(broadcasterUserId||"")});
        if(after)params.set("after",after);
        const data=await twitchFetch(`${TWITCH_EVENTSUB_URL}?${params.toString()}`,{headers:{Authorization:`Bearer ${appToken}`,"Client-Id":TWITCH_CLIENT_ID}});
        if(Array.isArray(data?.data))all.push(...data.data);
        after=String(data?.pagination?.cursor||"");
        if(!after)break;
    }
    return all;
}

function twitchEventSubRemoteMatches(definition,remote,broadcasterUserId){
    if(!remote||String(remote.type)!==String(definition.type)||String(remote.version)!==String(definition.version))return false;
    const transport=remote.transport||{};
    if(String(transport.method)!=="webhook"||String(transport.callback)!==TWITCH_EVENTSUB_CALLBACK_URL)return false;
    const expected=twitchEventSubCondition(definition.type,broadcasterUserId),actual=remote.condition||{};
    return Object.entries(expected).every(([key,value])=>String(actual[key]||"")===String(value));
}

async function deleteTwitchEventSubSubscription(subscriptionId,appToken){
    const id=String(subscriptionId||"").trim();
    if(!id)return;
    try{
        await twitchFetch(`${TWITCH_EVENTSUB_URL}?id=${encodeURIComponent(id)}`,{method:"DELETE",headers:{Authorization:`Bearer ${appToken}`,"Client-Id":TWITCH_CLIENT_ID}});
    }catch(error){if(Number(error?.status)!==404)throw error}
}

async function syncTwitchLiveState(creatorId,connection=null,appToken=null){
    const row=connection||await ensureValidTwitchConnection(creatorId);
    if(!row?.connected||!row.twitch_user_id||!twitchConfigured())return getProviderLiveState(creatorId,"twitch");
    const previous=await getProviderLiveState(creatorId,"twitch");
    const token=appToken||await twitchAppAccessToken();
    const data=await twitchFetch(`${TWITCH_STREAMS_URL}?user_id=${encodeURIComponent(row.twitch_user_id)}`,{headers:{Authorization:`Bearer ${token}`,"Client-Id":TWITCH_CLIENT_ID}});
    const stream=Array.isArray(data?.data)?data.data[0]:null;
    if(stream){
        await saveTwitchProviderLiveState(creatorId,{connected:true,sessionId:`twitch:${String(stream.id||row.twitch_user_id).slice(0,180)}`,startedAt:stream.started_at||new Date().toISOString(),lastEventAt:new Date().toISOString()});
    }else if(previous?.connected===true){
        await saveTwitchProviderLiveState(creatorId,{connected:false,lastEventAt:new Date().toISOString()});
    }else if(!previous?.updated_at){
        await saveTwitchProviderLiveState(creatorId,{connected:false});
    }
    return getProviderLiveState(creatorId,"twitch");
}

async function ensureTwitchEventSubSubscriptions(creatorId,connection=null){
    const row=connection||await ensureValidTwitchConnection(creatorId);
    if(!row?.connected||!row.twitch_user_id||!twitchConfigured())return getTwitchEventSubStatus(creatorId);
    const scopes=new Set(String(row.scope||"").split(/[\s,]+/).filter(Boolean));
    const appToken=await twitchAppAccessToken();
    const remote=await listTwitchEventSubSubscriptionsForUser(row.twitch_user_id,appToken);
    for(const definition of TWITCH_EVENTSUB_DEFINITIONS){
        const requiredScopes=twitchEventSubScopes(definition);
        const missingScopes=requiredScopes.filter(scope=>!scopes.has(scope));
        if(missingScopes.length){
            await upsertTwitchEventSubStatus(creatorId,definition,{status:"missing_scope",error:`OAuth Scope fehlt: ${missingScopes.join(", ")}`});
            continue;
        }
        const exact=remote.filter(item=>twitchEventSubRemoteMatches(definition,item,row.twitch_user_id)&&["enabled","webhook_callback_verification_pending"].includes(String(item.status)));
        exact.sort((a,b)=>Number(String(b.status)==="enabled")-Number(String(a.status)==="enabled"));
        const current=exact[0]||null;
        if(current){
            await upsertTwitchEventSubStatus(creatorId,definition,{subscriptionId:current.id||null,status:current.status||"pending"});
            for(const duplicate of exact.slice(1)){try{await deleteTwitchEventSubSubscription(duplicate.id,appToken)}catch(error){safeLogError("Twitch EventSub Duplicate Cleanup Warnung:",error)}}
            continue;
        }
        // Alte Callback-URLs derselben App/Creator-Kombination entfernen, damit kein Event an veraltete Deployments geht.
        const stale=remote.filter(item=>String(item.type)===definition.type&&String(item.version)===definition.version&&String(item?.condition?.broadcaster_user_id||"")===String(row.twitch_user_id));
        for(const old of stale){try{await deleteTwitchEventSubSubscription(old.id,appToken)}catch(error){safeLogError("Twitch EventSub Alt-Callback Cleanup Warnung:",error)}}
        try{
            const payload={type:definition.type,version:definition.version,condition:twitchEventSubCondition(definition.type,row.twitch_user_id),transport:{method:"webhook",callback:TWITCH_EVENTSUB_CALLBACK_URL,secret:twitchEventSubSecret()}};
            const data=await twitchFetch(TWITCH_EVENTSUB_URL,{method:"POST",headers:{Authorization:`Bearer ${appToken}`,"Client-Id":TWITCH_CLIENT_ID,"Content-Type":"application/json"},body:JSON.stringify(payload)});
            const created=Array.isArray(data?.data)?data.data[0]:null;
            await upsertTwitchEventSubStatus(creatorId,definition,{subscriptionId:created?.id||null,status:created?.status||"webhook_callback_verification_pending"});
        }catch(error){
            // Twitch liefert bei bereits vorhandener type+condition-Kombination 409. Dann beim nächsten Reconcile remote übernehmen statt Duplikate zu erzeugen.
            const conflictId=Number(error?.status)===409?String(error?.payload?.id||""):"";
            await upsertTwitchEventSubStatus(creatorId,definition,{subscriptionId:conflictId||null,status:conflictId?"reconcile_required":"error",error:String(error?.message||error)});
        }
    }
    await syncTwitchLiveState(creatorId,row,appToken);
    await pool.query(`UPDATE twitch_connections SET last_runtime_checked_at=$2,runtime_error='',updated_at=NOW() WHERE creator_id=$1`,[normalizeCreatorId(creatorId),Date.now()]);
    return getTwitchEventSubStatus(creatorId);
}

async function getProviderLiveState(creatorId,provider){
    const key=String(provider||"").toLowerCase();
    if(key==="tiktok")return getStudioLiveState(creatorId);
    const row=(await pool.query(`SELECT * FROM creator_provider_live_state WHERE creator_id=$1 AND provider=$2 LIMIT 1`,[normalizeCreatorId(creatorId),key])).rows[0];
    if(!row)return{connected:false,provider:key||"none",session_id:null,likes:0,viewers:0,shares:0,gifts_count:0,gifts_value:0,followers_gained:0,started_at:null,last_event_at:null,updated_at:null,stale:false};
    return{connected:Boolean(row.connected),provider:key,session_id:row.session_id||null,likes:0,viewers:0,shares:0,gifts_count:0,gifts_value:0,followers_gained:0,started_at:row.started_at||null,last_event_at:row.last_event_at||null,updated_at:row.updated_at||null,stale:false};
}

async function saveTwitchProviderLiveState(creatorId,{connected,sessionId=null,startedAt=null,lastEventAt=null}={}){
    await pool.query(`
      INSERT INTO creator_provider_live_state(creator_id,provider,session_id,connected,started_at,last_event_at,updated_at)
      VALUES($1,'twitch',$2,$3,$4,$5,NOW())
      ON CONFLICT(creator_id,provider) DO UPDATE SET
        session_id=COALESCE(EXCLUDED.session_id,creator_provider_live_state.session_id),
        connected=EXCLUDED.connected,
        started_at=CASE WHEN EXCLUDED.connected THEN COALESCE(EXCLUDED.started_at,creator_provider_live_state.started_at,NOW()) ELSE creator_provider_live_state.started_at END,
        last_event_at=COALESCE(EXCLUDED.last_event_at,creator_provider_live_state.last_event_at),updated_at=NOW()
    `,[normalizeCreatorId(creatorId),sessionId,Boolean(connected),startedAt,lastEventAt]);
}

async function insertTwitchRuntimeEvent(creatorId,eventType,event,messageId){
    const state=await getProviderLiveState(creatorId,"twitch");
    const id=crypto.randomUUID();
    const actor=studioText(event?.chatter_user_name||event?.chatter_user_login||event?.user_name||event?.user_login||(event?.is_anonymous?"Anonymous":""),100,"");
    const amount=eventType==="cheer"?Math.max(0,Number(event?.bits||0)):eventType==="subscribe"?Math.max(1,Number(event?.total||1)||1):1;
    const payload={
        message:studioText(event?.message?.text||event?.message||"",280,""),
        tier:studioText(event?.tier,20,""),
        is_gift:event?.is_gift===true,
        is_anonymous:event?.is_anonymous===true,
        source_provider:"twitch",
        source_channel:studioText(event?.broadcaster_user_login||event?.broadcaster_user_name,120,""),
        source_event_id:String(event?.message_id||messageId||"").slice(0,160),
        is_bot:false
    };
    await pool.query(`
      INSERT INTO creator_live_events(id,creator_id,session_id,provider,event_key,event_type,actor_name,amount,event_value,payload,created_at)
      VALUES($1,$2,$3,'twitch',$4,$5,$6,$7,$8,$9::jsonb,NOW())
      ON CONFLICT DO NOTHING
    `,[id,normalizeCreatorId(creatorId),state.session_id||null,String(messageId||"").slice(0,200)||null,eventType,actor,amount,eventType==="cheer"?amount:0,JSON.stringify(payload)]);
    await pool.query(`UPDATE creator_provider_live_state SET last_event_at=NOW(),updated_at=NOW() WHERE creator_id=$1 AND provider='twitch'`,[normalizeCreatorId(creatorId)]);
}

async function handleTwitchEventSubNotification(messageId,body){
    const subscription=body?.subscription||{},event=body?.event||{};
    const broadcasterId=String(event.broadcaster_user_id||subscription?.condition?.broadcaster_user_id||"");
    if(!broadcasterId)return;
    const owner=(await pool.query(`SELECT creator_id FROM twitch_connections WHERE connected=TRUE AND twitch_user_id=$1 LIMIT 1`,[broadcasterId])).rows[0];
    if(!owner)return;
    const creatorId=owner.creator_id,type=String(subscription.type||"");
    const betaAccess=await requireProviderBetaAccess(creatorId,"twitch").catch(()=>null);
    if(!betaAccess)return;
    if(type==="stream.online"){
        const sessionId=`twitch:${String(event.id||messageId||crypto.randomUUID()).slice(0,180)}`;
        await saveTwitchProviderLiveState(creatorId,{connected:true,sessionId,startedAt:event.started_at||new Date().toISOString(),lastEventAt:new Date().toISOString()});
        return;
    }
    if(type==="stream.offline"){
        await saveTwitchProviderLiveState(creatorId,{connected:false,lastEventAt:new Date().toISOString()});
        return;
    }
    const eventType=type==="channel.chat.message"?"chat":type==="channel.follow"?"follow":type==="channel.cheer"?"cheer":type.startsWith("channel.subscription")||type==="channel.subscribe"?"subscribe":"";
    if(eventType)await insertTwitchRuntimeEvent(creatorId,eventType,event,messageId);
}

async function handleTwitchEventSubRevocation(body){
    const subscription=body?.subscription||{},subscriptionId=String(subscription.id||""),status=String(subscription.status||"revoked");
    const row=subscriptionId?(await pool.query(`SELECT creator_id,subscription_type FROM twitch_eventsub_subscriptions WHERE subscription_id=$1 LIMIT 1`,[subscriptionId])).rows[0]:null;
    const broadcasterId=String(subscription?.condition?.broadcaster_user_id||"");
    const owner=row||(!broadcasterId?null:(await pool.query(`SELECT creator_id FROM twitch_connections WHERE connected=TRUE AND twitch_user_id=$1 LIMIT 1`,[broadcasterId])).rows[0]);
    if(!owner)return;
    if(["authorization_revoked","user_removed"].includes(status)){
        await pool.query(`UPDATE twitch_connections SET connected=FALSE,access_token=NULL,refresh_token=NULL,runtime_error=$2,last_runtime_checked_at=$3,updated_at=NOW() WHERE creator_id=$1`,[owner.creator_id,`EventSub: ${status}`,Date.now()]);
        await saveTwitchProviderLiveState(owner.creator_id,{connected:false});
    }else{
        await pool.query(`UPDATE twitch_connections SET runtime_error=$2,last_runtime_checked_at=$3,updated_at=NOW() WHERE creator_id=$1`,[owner.creator_id,`EventSub ${String(owner.subscription_type||subscription.type||"")}: ${status}`,Date.now()]);
    }
}

async function twitchEventSubWebhook(req,res){
    res.set("Cache-Control","no-store");
    try{
        if(!twitchConfigured()||!twitchEventSubSecret())return res.status(503).end();
        const messageId=String(req.get("Twitch-Eventsub-Message-Id")||"");
        const timestamp=String(req.get("Twitch-Eventsub-Message-Timestamp")||"");
        const signature=String(req.get("Twitch-Eventsub-Message-Signature")||"");
        if(!messageId||!timestamp||!signature||!Buffer.isBuffer(req.body))return res.status(400).end();
        const sentAt=new Date(timestamp).getTime();
        if(!Number.isFinite(sentAt)||Math.abs(Date.now()-sentAt)>10*60*1000)return res.status(403).end();
        const expected=`sha256=${crypto.createHmac("sha256",twitchEventSubSecret()).update(Buffer.concat([Buffer.from(messageId+timestamp),req.body])).digest("hex")}`;
        const a=Buffer.from(expected),b=Buffer.from(signature);
        if(a.length!==b.length||!crypto.timingSafeEqual(a,b))return res.status(403).end();
        let body={};try{body=JSON.parse(req.body.toString("utf8"))}catch{return res.status(400).end()}
        const messageType=String(req.get("Twitch-Eventsub-Message-Type")||"");
        const subId=String(body?.subscription?.id||"");
        if(subId){
            await pool.query(`UPDATE twitch_eventsub_subscriptions SET status=$2,last_error='',updated_at=NOW() WHERE subscription_id=$1`,[subId,messageType==="revocation"?String(body?.subscription?.status||"revoked"):"enabled"]);
        }
        if(messageType==="webhook_callback_verification")return res.status(200).type("text/plain").send(String(body?.challenge||""));
        if(messageType==="revocation")await handleTwitchEventSubRevocation(body);
        if(messageType==="notification")await handleTwitchEventSubNotification(messageId,body);
        return res.status(204).end();
    }catch(error){safeLogError("Twitch EventSub Webhook Fehler:",error);return res.status(500).end()}
}

async function creatorWidgetProviderAccess(creatorId){
    const [tiktok,twitch,youtube,bridge,twitchEventSub,twitchLive,youtubeLive,access]=await Promise.all([
        getConnection(creatorId),
        getTwitchConnection(creatorId),
        getYouTubeConnection(creatorId),
        getStudioBridgeStatus(creatorId),
        getTwitchEventSubStatus(creatorId),
        getProviderLiveState(creatorId,"twitch"),
        getProviderLiveState(creatorId,"youtube"),
        creatorAccessProfile(creatorId)
    ]);
    const liveProvider=bridge?.capabilities?.integration_health?.live_provider||{};
    const liveProviderKey=String(liveProvider.key||bridge?.capabilities?.provider||"").toLowerCase();
    const tiktokLiveReady=bridge?.online===true&&liveProvider.ready===true&&["tiktool","tikfinity"].includes(liveProviderKey);
    const twitchScopes=String(twitch?.scope||"").split(/[\s,]+/).filter(Boolean);
    const twitchMissing=TWITCH_EVENTSUB_REQUIRED_SCOPES.filter(scope=>!twitchScopes.includes(scope));
    const youtubeScopes=String(youtube?.scope||"").split(/[\s,]+/).filter(Boolean);
    const youtubeMissing=YOUTUBE_OAUTH_SCOPES.filter(scope=>!youtubeScopes.includes(scope));
    const tiktokBeta=providerBetaPolicy(access,"tiktok"),twitchBeta=providerBetaPolicy(access,"twitch");
    return{
        obs:{connected:true,ready:true},
        tiktok:{connected:Boolean(tiktok?.connected),beta_access:tiktokBeta,available_for_widgets:Boolean(tiktok?.connected)&&tiktokBeta.allowed,live_events_ready:tiktokBeta.allowed&&tiktokLiveReady,live_provider:liveProviderKey||"none"},
        twitch:{
            connected:Boolean(twitch?.connected),
            beta_access:twitchBeta,
            available_for_widgets:Boolean(twitch?.connected)&&twitchBeta.allowed,
            scopes:twitchScopes,
            required_scopes:[...TWITCH_EVENTSUB_REQUIRED_SCOPES],
            missing_scopes:twitchMissing,
            scope_ready:Boolean(twitch?.connected)&&twitchMissing.length===0,
            eventsub:twitchEventSub,
            live:twitchLive,
            live_events_ready:twitchBeta.allowed&&twitchEventSub.ready,
            runtime_checked_at:twitch?.last_runtime_checked_at?new Date(Number(twitch.last_runtime_checked_at)).toISOString():null,
            runtime_error:studioText(twitch?.runtime_error,240,"")
        },
        youtube:{
            connected:Boolean(youtube?.connected),
            scopes:youtubeScopes,
            required_scopes:[...YOUTUBE_OAUTH_SCOPES],
            missing_scopes:youtubeMissing,
            scope_ready:Boolean(youtube?.connected)&&youtubeMissing.length===0,
            live_events_ready:Boolean(youtube?.connected)&&youtubeMissing.length===0,
            live:youtubeLive,
            runtime_checked_at:youtube?.last_runtime_checked_at?new Date(Number(youtube.last_runtime_checked_at)).toISOString():null,
            runtime_error:studioText(youtube?.runtime_error,240,"")
        }
    };
}

async function assertProviderAccountAvailable(provider,externalId,creatorId){
    const id=String(externalId||"").trim();if(!id)return;
    const map={tiktok:{table:"tiktok_connections",field:"open_id",label:"TikTok"},twitch:{table:"twitch_connections",field:"twitch_user_id",label:"Twitch"},youtube:{table:"youtube_connections",field:"youtube_channel_id",label:"YouTube"}};
    const cfg=map[String(provider||"").toLowerCase()];if(!cfg)throw new Error("Unbekannter Provider für Account-Isolation.");
    const result=await pool.query(`SELECT creator_id FROM ${cfg.table} WHERE ${cfg.field}=$1 AND creator_id<>$2 AND connected=TRUE LIMIT 1`,[id,normalizeCreatorId(creatorId)]);
    if(result.rows[0]){const error=new Error(`Dieser ${cfg.label}-Account ist bereits mit einem anderen Creator-Konto verbunden.`);error.code="provider_account_in_use";throw error;}
}

async function beginTwitchOAuth(res,creatorId){
    if(!twitchConfigured())return res.status(503).send(renderPage("Twitch Verbindung",`<p class="error">Twitch OAuth ist auf diesem Server noch nicht konfiguriert.</p>`));
    const state=crypto.randomBytes(32).toString("hex");
    await pool.query(`DELETE FROM twitch_oauth_states WHERE expires_at<NOW() OR creator_id=$1`,[normalizeCreatorId(creatorId)]);
    await pool.query(`INSERT INTO twitch_oauth_states(state_hash,creator_id,expires_at) VALUES($1,$2,NOW()+INTERVAL '10 minutes')`,[hashValue(state),normalizeCreatorId(creatorId)]);
    res.cookie(TWITCH_STATE_COOKIE,state,{httpOnly:true,secure:NODE_ENV!=="development",sameSite:"lax",priority:"high",maxAge:OAUTH_TTL_MS,path:"/auth/twitch"});
    const params=new URLSearchParams({client_id:TWITCH_CLIENT_ID,redirect_uri:TWITCH_REDIRECT_URI,response_type:"code",scope:TWITCH_OAUTH_SCOPES.join(" "),state,force_verify:"false"});
    return res.redirect(`${TWITCH_AUTHORIZE_URL}?${params.toString()}`);
}

app.get("/api/creator/twitch/status",requireCreatorAccount,async(req,res)=>{
    res.set("Cache-Control","no-store");
    try{
        const access=await creatorAccessProfile(req.creatorAccount),betaAccess=providerBetaPolicy(access,"twitch");
        let row=await getTwitchConnection(req.creatorAccount.id);
        if(betaAccess.allowed&&row?.connected&&twitchConfigured())row=await ensureValidTwitchConnection(req.creatorAccount.id);
        let eventsub=await getTwitchEventSubStatus(req.creatorAccount.id);
        if(betaAccess.allowed&&row?.connected&&twitchConfigured()&&!eventsub.ready){try{eventsub=await ensureTwitchEventSubSubscriptions(req.creatorAccount.id,row)}catch(error){safeLogError("Twitch EventSub Status Warnung:",error)}}
        return res.json({ok:true,...publicTwitchConnection(row),beta_access:betaAccess,runtime:{eventsub_implemented:true,eventsub_ready:betaAccess.allowed&&eventsub.ready,chat_events_implemented:true,chat_ready:betaAccess.allowed&&eventsub.subscriptions?.some(item=>item.type==="channel.chat.message"&&String(item.status)==="enabled"),production_ready:false},eventsub});
    }catch(error){safeLogError("Creator Twitch Status Fehler:",error);return res.status(502).json({ok:false,connected:false,configured:twitchConfigured(),error:"Twitch-Verbindung konnte nicht validiert werden."});}
});

app.get("/auth/creator/twitch",requireCreatorAccount,creatorWriteLimiter,async(req,res)=>{
    res.set("Cache-Control","no-store");
    try{
        await requireProviderBetaAccess(req.creatorAccount,"twitch");
        return await beginTwitchOAuth(res,req.creatorAccount.id);
    }catch(error){
        if(error?.code==="provider_beta_required")return res.status(403).send(renderPage("Twitch Beta",`<p class="error">${escapeHtml(error.message)}</p><p class="muted">Dein Account bleibt bestehen. Sobald der Admin dich freigibt, kannst du Twitch hier verbinden.</p>`));
        safeLogError("Twitch OAuth Start Fehler:",error);return res.status(500).send(renderPage("Twitch Verbindung",`<p class="error">Twitch Login konnte nicht gestartet werden.</p>`));
    }
});

app.get("/auth/twitch/callback",async(req,res)=>{
    res.set("Cache-Control","no-store");
    try{
        const {code,state,error,error_description:errorDescription}=req.query;
        if(error)return res.status(400).send(renderPage("Twitch Verbindung",`<p>Twitch Verbindung wurde nicht abgeschlossen.</p><p class="muted">${escapeHtml(errorDescription||error)}</p>`));
        const cookieState=parseCookies(req)[TWITCH_STATE_COOKIE];
        if(!code||!state||!cookieState||!safeEqualText(String(state),String(cookieState)))return res.status(400).send(renderPage("Sicherheitsprüfung",`<p>OAuth Sicherheitsprüfung fehlgeschlagen.</p>`));
        const stateResult=await pool.query(`DELETE FROM twitch_oauth_states WHERE state_hash=$1 AND expires_at>=NOW() RETURNING creator_id`,[hashValue(String(state))]);
        if(!stateResult.rowCount)return res.status(400).send(renderPage("Sicherheitsprüfung",`<p>Login ist abgelaufen oder wurde bereits verwendet.</p>`));
        const creatorId=normalizeCreatorId(stateResult.rows[0].creator_id);
        await requireProviderBetaAccess(creatorId,"twitch");
        const body=new URLSearchParams({client_id:TWITCH_CLIENT_ID,client_secret:TWITCH_CLIENT_SECRET,code:String(code),grant_type:"authorization_code",redirect_uri:TWITCH_REDIRECT_URI});
        const tokenData=await twitchFetch(TWITCH_TOKEN_URL,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body});
        await saveTwitchTokens(creatorId,tokenData,null);
        let connection=await ensureValidTwitchConnection(creatorId);
        connection=await syncTwitchProfile(creatorId,connection);
        try{await ensureTwitchEventSubSubscriptions(creatorId,connection)}catch(eventSubError){safeLogError("Twitch EventSub Setup Warnung:",eventSubError)}
        res.clearCookie(TWITCH_STATE_COOKIE,{path:"/auth/twitch"});
        await recordSecurityEvent(creatorId,"twitch_connected");
        return res.redirect("/pages/integrations.html?twitch=connected");
    }catch(error){
        if(error?.code==="provider_beta_required")return res.status(403).send(renderPage("Twitch Beta",`<p class="error">${escapeHtml(error.message)}</p><p class="muted">Die Verbindung wurde nicht gespeichert. Sobald der Admin die Beta freigibt, kannst du Twitch erneut verbinden.</p>`));
        safeLogError("Twitch OAuth Callback Fehler:",error);return res.status(502).send(renderPage("Twitch Verbindung",`<p class="error">Twitch Verbindung konnte nicht abgeschlossen werden.</p>`));
    }
});

app.post("/api/creator/twitch/sync",requireCreatorAccount,creatorWriteLimiter,async(req,res)=>{
    res.set("Cache-Control","no-store");
    try{await requireProviderBetaAccess(req.creatorAccount,"twitch");const row=await syncTwitchProfile(req.creatorAccount.id);const eventsub=await ensureTwitchEventSubSubscriptions(req.creatorAccount.id,row);return res.json({ok:true,...publicTwitchConnection(row),beta_access:providerBetaPolicy(await creatorAccessProfile(req.creatorAccount),"twitch"),runtime:{eventsub_implemented:true,eventsub_ready:eventsub.ready,chat_events_implemented:true,chat_ready:eventsub.subscriptions?.some(item=>item.type==="channel.chat.message"&&String(item.status)==="enabled"),production_ready:false},eventsub})}
    catch(error){if(error?.code==="provider_beta_required")return res.status(403).json(providerBetaDeniedPayload(error.access,"twitch"));safeLogError("Twitch Sync Fehler:",error);return res.status(502).json({ok:false,error:"Twitch Profil konnte nicht synchronisiert werden."})}
});

app.post("/api/creator/twitch/disconnect",requireCreatorAccount,requireCreatorAccountElevation,async(req,res)=>{
    res.set("Cache-Control","no-store");
    try{
        const row=await getTwitchConnection(req.creatorAccount.id);
        if(row?.access_token&&TWITCH_CLIENT_ID){
            try{const body=new URLSearchParams({client_id:TWITCH_CLIENT_ID,token:row.access_token});await twitchFetch(TWITCH_REVOKE_URL,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body})}catch(error){console.warn("Twitch Revoke Warnung:",String(error?.message||error).slice(0,300))}
        }
        const eventSubs=(await pool.query(`SELECT subscription_id FROM twitch_eventsub_subscriptions WHERE creator_id=$1 AND subscription_id IS NOT NULL`,[req.creatorAccount.id])).rows;
        if(eventSubs.length&&twitchConfigured()){
            try{const appToken=await twitchAppAccessToken();for(const sub of eventSubs){await twitchFetch(`${TWITCH_EVENTSUB_URL}?id=${encodeURIComponent(sub.subscription_id)}`,{method:"DELETE",headers:{Authorization:`Bearer ${appToken}`,"Client-Id":TWITCH_CLIENT_ID}})}}catch(error){console.warn("Twitch EventSub Cleanup Warnung:",String(error?.message||error).slice(0,300))}
        }
        await pool.query(`DELETE FROM twitch_eventsub_subscriptions WHERE creator_id=$1`,[req.creatorAccount.id]);
        await pool.query(`DELETE FROM creator_provider_live_state WHERE creator_id=$1 AND provider='twitch'`,[req.creatorAccount.id]);
        await pool.query(`DELETE FROM twitch_connections WHERE creator_id=$1`,[req.creatorAccount.id]);
        await pool.query(`DELETE FROM twitch_oauth_states WHERE creator_id=$1`,[req.creatorAccount.id]);
        await pool.query(`DELETE FROM launcher_provider_oauth_handoffs WHERE creator_id=$1 AND provider='twitch'`,[req.creatorAccount.id]);
        await recordSecurityEvent(req.creatorAccount.id,"twitch_disconnected");
        return res.json({ok:true,connected:false});
    }catch(error){safeLogError("Twitch Disconnect Fehler:",error);return res.status(500).json({ok:false,error:"Twitch-Verbindung konnte nicht getrennt werden."})}
});

// ============================================================
// YOUTUBE OAUTH / CHANNEL LINK / LIVE + CHAT RUNTIME
// ============================================================

function youtubeConfigured(){
    return Boolean(GOOGLE_CLIENT_ID && GOOGLE_CLIENT_SECRET && YOUTUBE_REDIRECT_URI);
}

async function getYouTubeConnection(creatorId){
    const result=await pool.query(`SELECT * FROM youtube_connections WHERE creator_id=$1 LIMIT 1`,[normalizeCreatorId(creatorId)]);
    const row=result.rows[0];
    if(!row)return null;
    return {...row,access_token:row.access_token?decryptSecret(row.access_token):"",refresh_token:row.refresh_token?decryptSecret(row.refresh_token):""};
}

function publicYouTubeConnection(row,live=null){
    const scopes=String(row?.scope||"").split(/[\s,]+/).map(v=>v.trim()).filter(Boolean);
    const missingScopes=YOUTUBE_OAUTH_SCOPES.filter(scope=>!scopes.includes(scope));
    return{
        connected:Boolean(row?.connected),
        channel:{
            id:row?.youtube_channel_id||"",
            title:row?.channel_title||"",
            handle:row?.channel_handle||"",
            profile_image_url:row?.profile_image_url||"",
            subscriber_count:Number(row?.subscriber_count||0),
            subscriber_count_hidden:Boolean(row?.subscriber_count_hidden)
        },
        scopes,
        required_scopes:[...YOUTUBE_OAUTH_SCOPES],
        missing_scopes:missingScopes,
        scope_ready:Boolean(row?.connected)&&missingScopes.length===0,
        configured:youtubeConfigured(),
        runtime_checked_at:row?.last_runtime_checked_at?new Date(Number(row.last_runtime_checked_at)).toISOString():null,
        runtime_error:studioText(row?.runtime_error,240,""),
        active_broadcast:{id:row?.active_broadcast_id||"",title:row?.active_broadcast_title||"",live_chat_id:Boolean(row?.active_live_chat_id)},
        live:live||null,
        runtime:{live_status_implemented:true,chat_read_implemented:true,membership_events_implemented:true,super_chat_events_implemented:true,production_ready:false},
        updated_at:row?.updated_at||null
    };
}

async function youtubeFetch(url,options={}){
    const controller=new AbortController();
    const timer=setTimeout(()=>controller.abort(),15000);
    try{
        const response=await fetch(url,{...options,signal:controller.signal});
        const text=await response.text();
        let data={};try{data=text?JSON.parse(text):{}}catch{data={message:text.slice(0,400)}}
        if(!response.ok){
            const apiError=Array.isArray(data?.error?.errors)?data.error.errors[0]:null;
            const error=new Error(String(data?.error?.message||apiError?.message||data?.error_description||data?.error||`YouTube HTTP ${response.status}`));
            error.status=response.status;error.reason=String(apiError?.reason||data?.error?.status||"");error.payload=data;throw error;
        }
        return data;
    }finally{clearTimeout(timer)}
}

async function saveYouTubeTokens(creatorId,data,existing=null){
    const previous=existing||await getYouTubeConnection(creatorId),now=Date.now();
    const refresh=String(data?.refresh_token||previous?.refresh_token||"").trim();
    const scope=Array.isArray(data?.scope)?data.scope.join(" "):String(data?.scope||previous?.scope||"");
    await pool.query(`
      INSERT INTO youtube_connections(creator_id,connected,access_token,refresh_token,access_expires_at,scope,updated_at)
      VALUES($1,TRUE,$2,$3,$4,$5,NOW())
      ON CONFLICT(creator_id) DO UPDATE SET connected=TRUE,access_token=EXCLUDED.access_token,
        refresh_token=COALESCE(EXCLUDED.refresh_token,youtube_connections.refresh_token),access_expires_at=EXCLUDED.access_expires_at,
        scope=CASE WHEN EXCLUDED.scope<>'' THEN EXCLUDED.scope ELSE youtube_connections.scope END,runtime_error='',updated_at=NOW()
    `,[normalizeCreatorId(creatorId),encryptSecret(String(data?.access_token||"")),refresh?encryptSecret(refresh):null,
       now+Math.max(0,Number(data?.expires_in||0))*1000,scope]);
    return getYouTubeConnection(creatorId);
}

async function refreshYouTubeTokens(creatorId,connection=null){
    const row=connection||await getYouTubeConnection(creatorId);
    if(!row?.refresh_token)throw Object.assign(new Error("YouTube Refresh-Token fehlt. Bitte YouTube erneut verbinden."),{code:"youtube_reauth_required"});
    const body=new URLSearchParams({client_id:GOOGLE_CLIENT_ID,client_secret:GOOGLE_CLIENT_SECRET,refresh_token:row.refresh_token,grant_type:"refresh_token"});
    const data=await youtubeFetch(YOUTUBE_TOKEN_URL,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body});
    return saveYouTubeTokens(creatorId,data,row);
}

async function ensureValidYouTubeConnection(creatorId){
    let row=await getYouTubeConnection(creatorId);
    if(!row?.connected||!row.access_token)return row;
    if(Number(row.access_expires_at||0)<=Date.now()+YOUTUBE_TOKEN_SAFETY_WINDOW_MS){
        try{row=await refreshYouTubeTokens(creatorId,row)}catch(error){
            await pool.query(`UPDATE youtube_connections SET runtime_error=$2,updated_at=NOW() WHERE creator_id=$1`,[normalizeCreatorId(creatorId),String(error?.message||error).slice(0,240)]).catch(()=>{});
            throw error;
        }
    }
    return row;
}

async function syncYouTubeChannel(creatorId,connection=null){
    const row=connection||await ensureValidYouTubeConnection(creatorId);
    if(!row?.access_token)return row;
    const params=new URLSearchParams({part:"snippet,statistics",mine:"true",maxResults:"5"});
    const data=await youtubeFetch(`${YOUTUBE_CHANNELS_URL}?${params.toString()}`,{headers:{Authorization:`Bearer ${row.access_token}`}});
    const channel=Array.isArray(data?.items)?data.items[0]:null;
    if(!channel?.id)throw Object.assign(new Error("Für dieses Google-Konto wurde kein YouTube-Kanal gefunden."),{code:"youtube_channel_missing"});
    try{await assertProviderAccountAvailable("youtube",channel.id,creatorId)}catch(error){
        if(error?.code==="provider_account_in_use")await pool.query(`DELETE FROM youtube_connections WHERE creator_id=$1`,[normalizeCreatorId(creatorId)]);
        throw error;
    }
    const snippet=channel.snippet||{},stats=channel.statistics||{},thumbs=snippet.thumbnails||{};
    const avatar=thumbs.high?.url||thumbs.medium?.url||thumbs.default?.url||"";
    await pool.query(`UPDATE youtube_connections SET youtube_channel_id=$2,channel_title=$3,channel_handle=$4,profile_image_url=$5,subscriber_count=$6,subscriber_count_hidden=$7,runtime_error='',updated_at=NOW() WHERE creator_id=$1`,[
        normalizeCreatorId(creatorId),String(channel.id),studioText(snippet.title,120,""),studioText(snippet.customUrl,120,""),studioText(avatar,2000,""),Math.max(0,Number(stats.subscriberCount||0)),Boolean(stats.hiddenSubscriberCount)
    ]);
    return getYouTubeConnection(creatorId);
}

async function saveYouTubeProviderLiveState(creatorId,{connected,sessionId=null,startedAt=null,lastEventAt=null}={}){
    await pool.query(`
      INSERT INTO creator_provider_live_state(creator_id,provider,session_id,connected,started_at,last_event_at,updated_at)
      VALUES($1,'youtube',$2,$3,$4,$5,NOW())
      ON CONFLICT(creator_id,provider) DO UPDATE SET
        session_id=CASE WHEN EXCLUDED.connected THEN COALESCE(EXCLUDED.session_id,creator_provider_live_state.session_id) ELSE creator_provider_live_state.session_id END,
        connected=EXCLUDED.connected,
        started_at=CASE WHEN EXCLUDED.connected THEN COALESCE(EXCLUDED.started_at,creator_provider_live_state.started_at,NOW()) ELSE creator_provider_live_state.started_at END,
        last_event_at=COALESCE(EXCLUDED.last_event_at,creator_provider_live_state.last_event_at),updated_at=NOW()
    `,[normalizeCreatorId(creatorId),sessionId,Boolean(connected),startedAt,lastEventAt]);
}

function youtubeChatEventType(item={}){
    const type=String(item?.snippet?.type||"");
    if(type==="textMessageEvent")return"chat";
    if(["newSponsorEvent","memberMilestoneChatEvent","membershipGiftingEvent","giftMembershipReceivedEvent"].includes(type))return"membership";
    if(["superChatEvent","superStickerEvent"].includes(type))return"super_chat";
    return"";
}

async function insertYouTubeRuntimeEvent(creatorId,item){
    const eventType=youtubeChatEventType(item);if(!eventType)return;
    const state=await getProviderLiveState(creatorId,"youtube"),snippet=item?.snippet||{},author=item?.authorDetails||{};
    const eventKey=`youtube:${String(item?.id||crypto.randomUUID()).slice(0,180)}`;
    const superDetails=snippet.superChatDetails||snippet.superStickerDetails||{};
    const giftDetails=snippet.membershipGiftingDetails||{};
    const amount=eventType==="membership"?Math.max(1,Number(giftDetails.giftMembershipsCount||1)||1):1;
    const eventValue=eventType==="super_chat"?Math.max(0,Number(superDetails.amountMicros||0)/1_000_000):0;
    const message=studioText(snippet.displayMessage||snippet.textMessageDetails?.messageText||superDetails.userComment||"",280,"");
    const payload={
        message,
        source_provider:"youtube",
        source_channel:studioText(author.channelId,120,""),
        source_event_id:String(item?.id||"").slice(0,160),
        membership_level:studioText(snippet.memberMilestoneChatDetails?.memberLevelName||snippet.newSponsorDetails?.memberLevelName||"",80,""),
        currency:studioText(superDetails.currency,16,""),
        amount_display:studioText(superDetails.amountDisplayString,48,""),
        is_bot:false
    };
    await pool.query(`
      INSERT INTO creator_live_events(id,creator_id,session_id,provider,event_key,event_type,actor_name,actor_avatar,amount,event_value,payload,created_at)
      VALUES($1,$2,$3,'youtube',$4,$5,$6,$7,$8,$9,$10::jsonb,$11)
      ON CONFLICT DO NOTHING
    `,[crypto.randomUUID(),normalizeCreatorId(creatorId),state.session_id||null,eventKey,eventType,studioText(author.displayName,100,""),studioText(author.profileImageUrl,2000,""),amount,eventValue,JSON.stringify(payload),snippet.publishedAt||new Date().toISOString()]);
    await pool.query(`UPDATE creator_provider_live_state SET last_event_at=GREATEST(COALESCE(last_event_at,'epoch'::timestamptz),$2::timestamptz),updated_at=NOW() WHERE creator_id=$1 AND provider='youtube'`,[normalizeCreatorId(creatorId),snippet.publishedAt||new Date().toISOString()]);
}

async function syncYouTubeLiveState(creatorId,connection=null){
    const row=connection||await ensureValidYouTubeConnection(creatorId);
    if(!row?.connected||!row.access_token||!youtubeConfigured())return getProviderLiveState(creatorId,"youtube");
    const params=new URLSearchParams({part:"id,snippet,status",broadcastStatus:"active",mine:"true",maxResults:"5"});
    let data;
    try{data=await youtubeFetch(`${YOUTUBE_BROADCASTS_URL}?${params.toString()}`,{headers:{Authorization:`Bearer ${row.access_token}`}})}catch(error){
        if(Number(error?.status)===401){const refreshed=await refreshYouTubeTokens(creatorId,row);return syncYouTubeLiveState(creatorId,refreshed)}
        throw error;
    }
    const broadcast=Array.isArray(data?.items)?data.items.find(item=>String(item?.status?.lifeCycleStatus||"")==="live")||data.items[0]:null;
    const now=Date.now();
    if(!broadcast?.id){
        await saveYouTubeProviderLiveState(creatorId,{connected:false});
        await pool.query(`UPDATE youtube_connections SET active_broadcast_id=NULL,active_broadcast_title=NULL,active_live_chat_id=NULL,chat_page_token=NULL,chat_initialized_at=NULL,next_chat_poll_at=NULL,next_runtime_poll_at=$2,last_runtime_checked_at=$3,runtime_error='',updated_at=NOW() WHERE creator_id=$1`,[normalizeCreatorId(creatorId),now+YOUTUBE_RUNTIME_IDLE_INTERVAL_MS,now]);
        return getProviderLiveState(creatorId,"youtube");
    }
    const liveChatId=String(broadcast?.snippet?.liveChatId||""),broadcastId=String(broadcast.id),changed=broadcastId!==String(row.active_broadcast_id||"")||liveChatId!==String(row.active_live_chat_id||"");
    await saveYouTubeProviderLiveState(creatorId,{connected:true,sessionId:`youtube:${broadcastId}`.slice(0,200),startedAt:broadcast?.snippet?.actualStartTime||broadcast?.snippet?.scheduledStartTime||new Date().toISOString()});
    await pool.query(`UPDATE youtube_connections SET active_broadcast_id=$2,active_broadcast_title=$3,active_live_chat_id=$4,chat_page_token=CASE WHEN $5 THEN NULL ELSE chat_page_token END,chat_initialized_at=CASE WHEN $5 THEN $6 ELSE chat_initialized_at END,next_chat_poll_at=CASE WHEN $4<>'' THEN CASE WHEN $5 THEN $6 ELSE COALESCE(next_chat_poll_at,$6) END ELSE NULL END,next_runtime_poll_at=$7,last_runtime_checked_at=$6,runtime_error='',updated_at=NOW() WHERE creator_id=$1`,[
        normalizeCreatorId(creatorId),broadcastId,studioText(broadcast?.snippet?.title,160,""),liveChatId,changed,now,now+YOUTUBE_RUNTIME_ACTIVE_INTERVAL_MS
    ]);
    return getProviderLiveState(creatorId,"youtube");
}

async function pollYouTubeLiveChat(creatorId,connection=null){
    let row=connection||await ensureValidYouTubeConnection(creatorId);
    const chatId=String(row?.active_live_chat_id||"");
    if(!row?.connected||!row.access_token||!chatId)return{ok:true,polled:false};
    const params=new URLSearchParams({liveChatId:chatId,part:"id,snippet,authorDetails",maxResults:"200",profileImageSize:"88"});
    if(row.chat_page_token)params.set("pageToken",String(row.chat_page_token));
    let data;
    try{data=await youtubeFetch(`${YOUTUBE_CHAT_MESSAGES_URL}?${params.toString()}`,{headers:{Authorization:`Bearer ${row.access_token}`}})}catch(error){
        if(Number(error?.status)===401){row=await refreshYouTubeTokens(creatorId,row);return pollYouTubeLiveChat(creatorId,row)}
        if(["liveChatEnded","liveChatNotFound"].includes(String(error?.reason))){
            await pool.query(`UPDATE youtube_connections SET active_live_chat_id=NULL,chat_page_token=NULL,next_chat_poll_at=NULL,runtime_error=$2,updated_at=NOW() WHERE creator_id=$1`,[normalizeCreatorId(creatorId),String(error.reason)]);
            return{ok:true,polled:false,ended:true};
        }
        throw error;
    }
    const initial=!row.chat_page_token,initializedAt=Number(row.chat_initialized_at||Date.now()),items=Array.isArray(data?.items)?data.items:[];
    for(const item of items){
        if(initial){const published=new Date(item?.snippet?.publishedAt||0).getTime();if(!Number.isFinite(published)||published<initializedAt-3000)continue;}
        await insertYouTubeRuntimeEvent(creatorId,item);
    }
    const delay=Math.max(1000,Math.min(60_000,Number(data?.pollingIntervalMillis||5000)));
    await pool.query(`UPDATE youtube_connections SET chat_page_token=$2,next_chat_poll_at=$3,last_runtime_checked_at=$4,runtime_error='',updated_at=NOW() WHERE creator_id=$1`,[normalizeCreatorId(creatorId),String(data?.nextPageToken||row.chat_page_token||""),Date.now()+delay,Date.now()]);
    if(data?.offlineAt){await saveYouTubeProviderLiveState(creatorId,{connected:false,lastEventAt:data.offlineAt});}
    return{ok:true,polled:true,events:items.length,next_poll_ms:delay};
}

let youtubeRuntimeWorkerTimer=null,youtubeRuntimeWorkerPromise=null;
async function runYouTubeRuntimeReconcile(){
    if(youtubeRuntimeWorkerPromise||!youtubeConfigured())return youtubeRuntimeWorkerPromise;
    youtubeRuntimeWorkerPromise=(async()=>{
        const now=Date.now();
        const rows=(await pool.query(`SELECT creator_id FROM youtube_connections WHERE connected=TRUE AND (next_runtime_poll_at IS NULL OR next_runtime_poll_at<=$1 OR (active_live_chat_id IS NOT NULL AND (next_chat_poll_at IS NULL OR next_chat_poll_at<=$1))) ORDER BY COALESCE(next_runtime_poll_at,0) ASC LIMIT $2`,[now,YOUTUBE_RUNTIME_BATCH])).rows;
        for(const item of rows){
            const creatorId=item.creator_id;
            try{
                let row=await ensureValidYouTubeConnection(creatorId);
                if(!row)continue;
                if(!row.next_runtime_poll_at||Number(row.next_runtime_poll_at)<=Date.now()){await syncYouTubeLiveState(creatorId,row);row=await getYouTubeConnection(creatorId);}
                if(row?.active_live_chat_id&&(!row.next_chat_poll_at||Number(row.next_chat_poll_at)<=Date.now()))await pollYouTubeLiveChat(creatorId,row);
            }catch(error){
                await pool.query(`UPDATE youtube_connections SET runtime_error=$2,last_runtime_checked_at=$3,next_runtime_poll_at=$4,updated_at=NOW() WHERE creator_id=$1`,[normalizeCreatorId(creatorId),String(error?.message||error).slice(0,240),Date.now(),Date.now()+60_000]).catch(()=>{});
                safeLogError("YouTube Runtime Warnung:",error);
            }
        }
    })().finally(()=>{youtubeRuntimeWorkerPromise=null});
    return youtubeRuntimeWorkerPromise;
}
function startYouTubeRuntimeWorker(){
    if(youtubeRuntimeWorkerTimer||!youtubeConfigured())return;
    youtubeRuntimeWorkerTimer=setInterval(()=>{void runYouTubeRuntimeReconcile()},YOUTUBE_RUNTIME_WORKER_TICK_MS);youtubeRuntimeWorkerTimer.unref?.();
    setTimeout(()=>{void runYouTubeRuntimeReconcile()},12_000).unref?.();
}
async function stopYouTubeRuntimeWorker(){
    if(youtubeRuntimeWorkerTimer){clearInterval(youtubeRuntimeWorkerTimer);youtubeRuntimeWorkerTimer=null;}
    if(youtubeRuntimeWorkerPromise)await Promise.race([youtubeRuntimeWorkerPromise,new Promise(resolve=>setTimeout(resolve,10_000))]);
}

async function beginYouTubeOAuth(res,creatorId){
    if(!youtubeConfigured())return res.status(503).send(renderPage("YouTube Verbindung",`<p class="error">YouTube OAuth ist auf diesem Server noch nicht konfiguriert.</p>`));
    const state=crypto.randomBytes(32).toString("hex");
    await pool.query(`DELETE FROM youtube_oauth_states WHERE expires_at<NOW() OR creator_id=$1`,[normalizeCreatorId(creatorId)]);
    await pool.query(`INSERT INTO youtube_oauth_states(state_hash,creator_id,expires_at) VALUES($1,$2,NOW()+INTERVAL '10 minutes')`,[hashValue(state),normalizeCreatorId(creatorId)]);
    res.cookie(YOUTUBE_STATE_COOKIE,state,{httpOnly:true,secure:NODE_ENV!=="development",sameSite:"lax",priority:"high",maxAge:OAUTH_TTL_MS,path:"/auth/youtube"});
    const params=new URLSearchParams({client_id:GOOGLE_CLIENT_ID,redirect_uri:YOUTUBE_REDIRECT_URI,response_type:"code",scope:YOUTUBE_OAUTH_SCOPES.join(" "),state,access_type:"offline",include_granted_scopes:"true",prompt:"consent"});
    return res.redirect(`${YOUTUBE_AUTHORIZE_URL}?${params.toString()}`);
}

app.get("/api/creator/youtube/status",requireCreatorAccount,async(req,res)=>{
    res.set("Cache-Control","no-store");
    try{
        let row=await getYouTubeConnection(req.creatorAccount.id);
        if(row?.connected&&youtubeConfigured()){row=await ensureValidYouTubeConnection(req.creatorAccount.id);if(!row?.youtube_channel_id)row=await syncYouTubeChannel(req.creatorAccount.id,row);}
        const live=await getProviderLiveState(req.creatorAccount.id,"youtube");
        return res.json({ok:true,...publicYouTubeConnection(row,live),live_events_ready:Boolean(row?.connected)&&publicYouTubeConnection(row).scope_ready});
    }catch(error){safeLogError("Creator YouTube Status Fehler:",error);return res.status(502).json({ok:false,connected:false,configured:youtubeConfigured(),error:"YouTube-Verbindung konnte nicht validiert werden."});}
});

app.get("/auth/creator/youtube",requireCreatorAccount,creatorWriteLimiter,async(req,res)=>{
    res.set("Cache-Control","no-store");
    try{return await beginYouTubeOAuth(res,req.creatorAccount.id)}catch(error){safeLogError("YouTube OAuth Start Fehler:",error);return res.status(500).send(renderPage("YouTube Verbindung",`<p class="error">YouTube Login konnte nicht gestartet werden.</p>`))}
});

app.get("/auth/youtube/callback",async(req,res)=>{
    res.set("Cache-Control","no-store");
    try{
        const {code,state,error,error_description:errorDescription}=req.query;
        if(error)return res.status(400).send(renderPage("YouTube Verbindung",`<p>YouTube Verbindung wurde nicht abgeschlossen.</p><p class="muted">${escapeHtml(errorDescription||error)}</p>`));
        const cookieState=parseCookies(req)[YOUTUBE_STATE_COOKIE];
        if(!code||!state||!cookieState||!safeEqualText(String(state),String(cookieState)))return res.status(400).send(renderPage("Sicherheitsprüfung",`<p>OAuth Sicherheitsprüfung fehlgeschlagen.</p>`));
        const stateResult=await pool.query(`DELETE FROM youtube_oauth_states WHERE state_hash=$1 AND expires_at>=NOW() RETURNING creator_id`,[hashValue(String(state))]);
        if(!stateResult.rowCount)return res.status(400).send(renderPage("Sicherheitsprüfung",`<p>Login ist abgelaufen oder wurde bereits verwendet.</p>`));
        const creatorId=normalizeCreatorId(stateResult.rows[0].creator_id);
        const body=new URLSearchParams({client_id:GOOGLE_CLIENT_ID,client_secret:GOOGLE_CLIENT_SECRET,code:String(code),grant_type:"authorization_code",redirect_uri:YOUTUBE_REDIRECT_URI});
        const tokenData=await youtubeFetch(YOUTUBE_TOKEN_URL,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body});
        await saveYouTubeTokens(creatorId,tokenData,null);
        let connection=await syncYouTubeChannel(creatorId);
        try{await syncYouTubeLiveState(creatorId,connection)}catch(runtimeError){safeLogError("YouTube LIVE Sync Warnung:",runtimeError)}
        res.clearCookie(YOUTUBE_STATE_COOKIE,{path:"/auth/youtube"});
        await recordSecurityEvent(creatorId,"youtube_connected");
        return res.redirect("/pages/integrations.html?youtube=connected");
    }catch(error){safeLogError("YouTube OAuth Callback Fehler:",error);return res.status(502).send(renderPage("YouTube Verbindung",`<p class="error">YouTube Verbindung konnte nicht abgeschlossen werden.</p>`))}
});

app.post("/api/creator/youtube/sync",requireCreatorAccount,creatorWriteLimiter,async(req,res)=>{
    res.set("Cache-Control","no-store");
    try{let row=await syncYouTubeChannel(req.creatorAccount.id);const live=await syncYouTubeLiveState(req.creatorAccount.id,row);row=await getYouTubeConnection(req.creatorAccount.id);return res.json({ok:true,...publicYouTubeConnection(row,live),live_events_ready:true})}
    catch(error){safeLogError("YouTube Sync Fehler:",error);return res.status(502).json({ok:false,error:"YouTube Kanal/LIVE-Status konnte nicht synchronisiert werden."})}
});

app.post("/api/creator/youtube/disconnect",requireCreatorAccount,requireCreatorAccountElevation,async(req,res)=>{
    res.set("Cache-Control","no-store");
    try{
        const row=await getYouTubeConnection(req.creatorAccount.id);
        const token=row?.refresh_token||row?.access_token;
        if(token){try{const body=new URLSearchParams({token});await youtubeFetch(YOUTUBE_REVOKE_URL,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body})}catch(error){console.warn("YouTube Revoke Warnung:",String(error?.message||error).slice(0,300))}}
        await pool.query(`DELETE FROM creator_provider_live_state WHERE creator_id=$1 AND provider='youtube'`,[req.creatorAccount.id]);
        await pool.query(`DELETE FROM youtube_connections WHERE creator_id=$1`,[req.creatorAccount.id]);
        await pool.query(`DELETE FROM youtube_oauth_states WHERE creator_id=$1`,[req.creatorAccount.id]);
        await pool.query(`DELETE FROM launcher_provider_oauth_handoffs WHERE creator_id=$1 AND provider='youtube'`,[req.creatorAccount.id]);
        await recordSecurityEvent(req.creatorAccount.id,"youtube_disconnected");
        return res.json({ok:true,connected:false});
    }catch(error){safeLogError("YouTube Disconnect Fehler:",error);return res.status(500).json({ok:false,error:"YouTube-Verbindung konnte nicht getrennt werden."})}
});

// ============================================================
// TIKTOK CONNECTION LADEN
// ============================================================

async function getConnection(
    creatorId = DEFAULT_CREATOR_ID
) {

    const result =
        await pool.query(
            `
            SELECT *
            FROM tiktok_connections
            WHERE creator_id = $1
            LIMIT 1
            `,
            [
                normalizeCreatorId(
                    creatorId
                )
            ]
        );


    if (
        !result.rows[0]
    ) {

        return null;

    }


    const row =
        result.rows[0];


    return {

        ...row,

        access_token:
            decryptSecret(
                row.access_token
            ),

        refresh_token:
            decryptSecret(
                row.refresh_token
            )

    };

}


// ============================================================
// TIKTOK TOKENS SPEICHERN
// ============================================================

async function saveTokens(
    creatorId,
    data
) {

    creatorId =
        normalizeCreatorId(
            creatorId
        );


    const existing =
        await getConnection(
            creatorId
        );


    const now =
        Date.now();


    const refreshToken =
        data.refresh_token ||
        existing?.refresh_token ||
        null;


    const accessExpiresAt =
        data.expires_in != null
            ? now +
              Number(
                  data.expires_in
              ) *
              1000
            : existing?.access_expires_at ||
              null;


    const refreshExpiresAt =
        data.refresh_expires_in != null
            ? now +
              Number(
                  data.refresh_expires_in
              ) *
              1000
            : existing?.refresh_expires_at ||
              null;


    await pool.query(
        `
        INSERT INTO tiktok_connections (

            creator_id,
            connected,
            open_id,
            access_token,
            refresh_token,
            access_expires_at,
            refresh_expires_at,
            scope,
            updated_at

        )

        VALUES (
            $1,
            TRUE,
            $2,
            $3,
            $4,
            $5,
            $6,
            $7,
            NOW()
        )

        ON CONFLICT (
            creator_id
        )

        DO UPDATE SET

            connected =
                TRUE,

            open_id =
                COALESCE(
                    EXCLUDED.open_id,
                    tiktok_connections.open_id
                ),

            access_token =
                EXCLUDED.access_token,

            refresh_token =
                COALESCE(
                    EXCLUDED.refresh_token,
                    tiktok_connections.refresh_token
                ),

            access_expires_at =
                EXCLUDED.access_expires_at,

            refresh_expires_at =
                COALESCE(
                    EXCLUDED.refresh_expires_at,
                    tiktok_connections.refresh_expires_at
                ),

            scope =
                EXCLUDED.scope,

            updated_at =
                NOW()
        `,
        [
            creatorId,

            data.open_id ||
            existing?.open_id ||
            null,

            encryptSecret(
                data.access_token
            ),

            refreshToken
                ? encryptSecret(
                    refreshToken
                )
                : null,

            accessExpiresAt,

            refreshExpiresAt,

            data.scope ||
            existing?.scope ||
            ""
        ]
    );

}


