async function saveProfile(
    creatorId,
    profile
) {

    try{await assertProviderAccountAvailable("tiktok",profile?.open_id,creatorId)}catch(error){
        if(error?.code==="provider_account_in_use")await pool.query(`DELETE FROM tiktok_connections WHERE creator_id=$1`,[normalizeCreatorId(creatorId)]);
        throw error;
    }

    await pool.query(
        `
        UPDATE tiktok_connections

        SET
            open_id = $2,
            display_name = $3,
            avatar_url = $4,
            follower_count = $5,
            following_count = $6,
            likes_count = $7,
            video_count = $8,
            updated_at = NOW()

        WHERE creator_id = $1
        `,
        [
            normalizeCreatorId(
                creatorId
            ),

            profile.open_id ||
            null,

            profile.display_name ||
            "",

            profile.avatar_url ||
            "",

            Number(
                profile.follower_count ||
                0
            ),

            Number(
                profile.following_count ||
                0
            ),

            Number(
                profile.likes_count ||
                0
            ),

            Number(
                profile.video_count ||
                0
            )
        ]
    );

}


// ============================================================
// LAUNCHER API KEY
// ============================================================

function requireLauncherKey(
    req,
    res,
    next
) {

    const supplied =
        req.get(
            "X-CFS-API-Key"
        );


    if (
        !supplied
    ) {

        return res
            .status(401)
            .json({

                ok:
                    false,

                error:
                    "API-Key fehlt."

            });

    }


    if (
        !safeEqualText(
            LAUNCHER_API_KEY,
            supplied
        )
    ) {

        return res
            .status(403)
            .json({

                ok:
                    false,

                error:
                    "API-Key ungültig."

            });

    }


    next();

}


// ============================================================
// OPT-IN GAME-AKTIVITÄT FÜR DIE ÖFFENTLICHE COMMUNITY-SEITE
//
// Der Launcher übermittelt ausschließlich abgeschlossene Game-Capture-
// Sessions, wenn die lokale Freigabe aktiv ist. Gespeichert werden nur
// ein zufälliger Client-Event-Key, ein bereinigter Spielname sowie
// Start/Ende/Dauer. Keine PIDs, Fenstertitel, Executable-Pfade oder
// sonstigen Prozessdetails werden serverseitig gespeichert.
// ============================================================

function publicGameActivityText(value,max=80) {
    return String(value ?? "")
        .replace(/[\u0000-\u001f\u007f]/g," ")
        .replace(/\s+/g," ")
        .trim()
        .slice(0,max);
}

function normalizePublicGameName(value) {
    const raw=publicGameActivityText(value,120).replace(/\.exe$/i,"").trim();
    if (!raw) return "";
    const lower=raw.toLowerCase();
    const mappings=[
        [/counter[- _]?strike\s*2|\bcs2\b/,"Counter-Strike 2"],
        [/fortnite/,"Fortnite"],
        [/valorant/,"VALORANT"],
        [/minecraft/,"Minecraft"],
        [/rocket\s*league|rocketleague/,"Rocket League"],
        [/grand\s*theft\s*auto\s*v|gta\s*v|gta5|gta5_enhanced/,"Grand Theft Auto V"],
        [/ea\s*sports\s*fc\s*25|fc25|fc\s*25/,"EA SPORTS FC 25"],
        [/call\s*of\s*duty|warzone|\bcod\b/,"Call of Duty"],
        [/league\s*of\s*legends|leagueclient|\blol\b/,"League of Legends"],
        [/apex\s*legends|r5apex/,"Apex Legends"],
        [/overwatch/,"Overwatch 2"]
    ];
    for (const [pattern,name] of mappings) if (pattern.test(lower)) return name;
    return raw.replace(/[-_]+/g," ").replace(/\s+/g," ").trim().slice(0,80);
}

function publicGameActivityKey(name) {
    return normalizePublicGameName(name)
        .toLowerCase()
        .normalize("NFKD")
        .replace(/[\u0300-\u036f]/g,"")
        .replace(/[^a-z0-9]+/g,"-")
        .replace(/^-+|-+$/g,"")
        .slice(0,80);
}

function sanitizePublicGameActivityEvent(input={}) {
    const source=input&&typeof input==="object"&&!Array.isArray(input)?input:{};
    const clientEventId=String(source.client_event_id||"").trim();
    if (!/^cfsga_[a-f0-9]{32}$/.test(clientEventId)) {
        const error=new Error("Game-Aktivitäts-ID ist ungültig.");
        error.code="game_activity_invalid";
        throw error;
    }
    const gameName=normalizePublicGameName(source.game_name);
    const gameKey=publicGameActivityKey(gameName);
    if (!gameName || !gameKey) {
        const error=new Error("Spielname fehlt oder ist ungültig.");
        error.code="game_activity_invalid";
        throw error;
    }
    const startedMs=Date.parse(String(source.started_at||""));
    const endedMs=Date.parse(String(source.ended_at||""));
    if (!Number.isFinite(startedMs)||!Number.isFinite(endedMs)||endedMs<=startedMs) {
        const error=new Error("Game-Aktivitätszeitraum ist ungültig.");
        error.code="game_activity_invalid";
        throw error;
    }
    const now=Date.now();
    if (endedMs>now+5*60*1000 || startedMs<now-PUBLIC_GAME_ACTIVITY_RETENTION_DAYS*24*60*60*1000) {
        const error=new Error("Game-Aktivität liegt außerhalb des zulässigen Zeitfensters.");
        error.code="game_activity_invalid";
        throw error;
    }
    const measuredSeconds=Math.round((endedMs-startedMs)/1000);
    const suppliedSeconds=Math.round(Number(source.duration_seconds||0));
    const durationSeconds=Math.max(30,Math.min(12*60*60,Math.min(measuredSeconds,suppliedSeconds>0?suppliedSeconds:measuredSeconds)));
    if (measuredSeconds<30) {
        const error=new Error("Game-Aktivität ist zu kurz.");
        error.code="game_activity_invalid";
        throw error;
    }
    const allowedSources=new Set(["launcher_manual","stream_capture"]);
    const allowedPlatforms=new Set(["playstation_5","playstation_4","pc","xbox_series","xbox_one","switch","unknown"]);
    const activitySource=allowedSources.has(String(source.source||""))?String(source.source):"launcher_manual";
    const activityPlatform=allowedPlatforms.has(String(source.platform||""))?String(source.platform):"unknown";
    return {
        client_event_id:clientEventId,
        game_name:gameName,
        started_at:new Date(startedMs).toISOString(),
        ended_at:new Date(startedMs+durationSeconds*1000).toISOString(),
        duration_seconds:durationSeconds,
        source:activitySource,
        platform:activitySource==="stream_capture"?"pc":activityPlatform
    };
}

const PUBLIC_GAME_ACTIVITY_PRESENCE_TTL_MS=150*1000;

function sanitizePublicGameActivityPresence(input={}) {
    const source=input&&typeof input==="object"&&!Array.isArray(input)?input:{};
    const active=source.active===true;
    const activitySource=["launcher_manual","stream_capture"].includes(String(source.source||""))?String(source.source):"launcher_manual";
    const rawPlatform=["playstation_5","playstation_4","pc","xbox_series","xbox_one","switch","unknown"].includes(String(source.platform||""))?String(source.platform):"unknown";
    const platform=activitySource==="stream_capture"?"pc":rawPlatform;
    const gameName=normalizePublicGameName(source.game_name||source.gameName);
    if (active && !gameName) {
        const error=new Error("Aktive Game-Präsenz benötigt einen Spielnamen.");
        error.code="game_activity_invalid";
        throw error;
    }
    if (active && activitySource==="launcher_manual" && platform==="unknown") {
        const error=new Error("Aktive manuelle Game-Präsenz benötigt eine Plattform.");
        error.code="game_activity_invalid";
        throw error;
    }
    const startedMs=Date.parse(String(source.started_at||""));
    const now=Date.now();
    const startedAt=active&&Number.isFinite(startedMs)&&startedMs<=now+5*60*1000&&startedMs>=now-24*60*60*1000?new Date(startedMs).toISOString():null;
    const suppliedReported=Date.parse(String(source.reported_at||""));
    const reportedAt=Number.isFinite(suppliedReported)&&suppliedReported<=now+5*60*1000?new Date(suppliedReported).toISOString():new Date(now).toISOString();
    const suppliedChanged=Date.parse(String(source.state_changed_at||source.changed_at||""));
    const stateChangedAt=Number.isFinite(suppliedChanged)&&suppliedChanged<=now+5*60*1000&&suppliedChanged>=now-7*24*60*60*1000?new Date(suppliedChanged).toISOString():reportedAt;
    const transitionId=/^cfsgp_[a-f0-9]{32}$/.test(String(source.transition_id||""))?String(source.transition_id):null;
    if (!transitionId) {
        const error=new Error("Game-Präsenz benötigt eine gültige Transition-ID.");
        error.code="game_activity_invalid";
        throw error;
    }
    return {
        active,
        game_name:active?gameName:"",
        source:activitySource,
        platform:active?platform:"unknown",
        started_at:startedAt,
        resumed_after_restart:active&&source.resumed_after_restart===true,
        transition_id:transitionId,
        state_changed_at:stateChangedAt,
        reported_at:reportedAt
    };
}

function normalizeStoredGameActivityState(state={}) {
    const source=state&&typeof state==="object"&&!Array.isArray(state)?state:{};
    const cutoff=Date.now()-PUBLIC_GAME_ACTIVITY_RETENTION_DAYS*24*60*60*1000;
    const seen=new Set();
    const events=[];
    for (const raw of Array.isArray(source.events)?source.events:[]) {
        try {
            const event=sanitizePublicGameActivityEvent(raw);
            if (Date.parse(event.ended_at)<cutoff || seen.has(event.client_event_id)) continue;
            seen.add(event.client_event_id);
            events.push(event);
        } catch {}
    }
    events.sort((a,b)=>Date.parse(a.ended_at)-Date.parse(b.ended_at));
    let presence=null;
    try {
        if (source.presence&&typeof source.presence==="object") {
            const reported=Date.parse(String(source.presence.reported_at||""));
            if (Number.isFinite(reported)&&Date.now()-reported<=PUBLIC_GAME_ACTIVITY_PRESENCE_TTL_MS) presence=sanitizePublicGameActivityPresence(source.presence);
        }
    } catch {}
    const transitionMs=Date.parse(String(source.presence_transition_at||presence?.state_changed_at||""));
    const presenceTransitionAt=Number.isFinite(transitionMs)?new Date(transitionMs).toISOString():null;
    const presenceTransitionId=/^cfsgp_[a-f0-9]{32}$/.test(String(source.presence_transition_id||presence?.transition_id||""))?String(source.presence_transition_id||presence?.transition_id):null;
    const presenceAudit=[];
    for (const raw of Array.isArray(source.presence_audit)?source.presence_audit.slice(-20):[]) {
        const id=/^cfsgp_[a-f0-9]{32}$/.test(String(raw?.transition_id||""))?String(raw.transition_id):null;
        const at=Date.parse(String(raw?.state_changed_at||""));
        if (!id||!Number.isFinite(at)) continue;
        presenceAudit.push({transition_id:id,active:raw?.active===true,game_name:normalizePublicGameName(raw?.game_name||""),platform:["playstation_5","playstation_4","pc","xbox_series","xbox_one","switch","unknown"].includes(String(raw?.platform||""))?String(raw.platform):"unknown",source:["launcher_manual","stream_capture"].includes(String(raw?.source||""))?String(raw.source):"launcher_manual",state_changed_at:new Date(at).toISOString()});
    }
    return {version:4,events:events.slice(-PUBLIC_GAME_ACTIVITY_MAX_EVENTS),presence,presence_transition_at:presenceTransitionAt,presence_transition_id:presenceTransitionId,presence_audit:presenceAudit,updated_at:source.updated_at||null};
}

async function recordCreatorGameActivity(creatorId,input={}) {
    const event=sanitizePublicGameActivityEvent(input);
    const client=await pool.connect();
    try {
        await client.query("BEGIN");
        await client.query(
            `INSERT INTO creator_module_state (creator_id,module_key,state,updated_at)
             VALUES ($1,$2,'{"version":1,"events":[]}'::jsonb,NOW())
             ON CONFLICT (creator_id,module_key) DO NOTHING`,
            [creatorId,PUBLIC_GAME_ACTIVITY_MODULE_KEY]
        );
        const row=(await client.query(
            `SELECT state FROM creator_module_state WHERE creator_id=$1 AND module_key=$2 FOR UPDATE`,
            [creatorId,PUBLIC_GAME_ACTIVITY_MODULE_KEY]
        )).rows[0];
        const state=normalizeStoredGameActivityState(row?.state||{});
        const duplicate=state.events.some(item=>item.client_event_id===event.client_event_id);
        if (!duplicate) state.events.push(event);
        state.events=normalizeStoredGameActivityState(state).events;
        state.updated_at=new Date().toISOString();
        await client.query(
            `UPDATE creator_module_state SET state=$3::jsonb,updated_at=NOW() WHERE creator_id=$1 AND module_key=$2`,
            [creatorId,PUBLIC_GAME_ACTIVITY_MODULE_KEY,JSON.stringify(state)]
        );
        await client.query("COMMIT");
        if (String(creatorId)===String(DEFAULT_CREATOR_ID)) publicCommunityStatsCache.expires_at=0;
        return {accepted:true,duplicate,event:{client_event_id:event.client_event_id,game_name:event.game_name,duration_seconds:event.duration_seconds,source:event.source,platform:event.platform}};
    } catch (error) {
        try { await client.query("ROLLBACK"); } catch {}
        throw error;
    } finally {
        client.release();
    }
}


async function updateCreatorGameActivityPresence(creatorId,input={}) {
    const presence=sanitizePublicGameActivityPresence(input);
    const client=await pool.connect();
    try {
        await client.query("BEGIN");
        await client.query(
            `INSERT INTO creator_module_state (creator_id,module_key,state,updated_at)
             VALUES ($1,$2,'{"version":2,"events":[]}'::jsonb,NOW())
             ON CONFLICT (creator_id,module_key) DO NOTHING`,
            [creatorId,PUBLIC_GAME_ACTIVITY_MODULE_KEY]
        );
        const row=(await client.query(
            `SELECT state FROM creator_module_state WHERE creator_id=$1 AND module_key=$2 FOR UPDATE`,
            [creatorId,PUBLIC_GAME_ACTIVITY_MODULE_KEY]
        )).rows[0];
        const state=normalizeStoredGameActivityState(row?.state||{});
        const incomingChanged=Date.parse(presence.state_changed_at||"");
        const storedChanged=Date.parse(state.presence_transition_at||state.presence?.state_changed_at||"");
        const storedTransitionId=String(state.presence_transition_id||state.presence?.transition_id||"");
        const duplicateTransition=storedTransitionId&&storedTransitionId===presence.transition_id;
        if (Number.isFinite(storedChanged)&&Number.isFinite(incomingChanged)&&incomingChanged<storedChanged) {
            await client.query("ROLLBACK");
            return {accepted:false,stale:true,duplicate:false,presence:state.presence};
        }
        if (Number.isFinite(storedChanged)&&Number.isFinite(incomingChanged)&&incomingChanged===storedChanged&&!duplicateTransition) {
            await client.query("ROLLBACK");
            return {accepted:false,stale:true,conflict:true,duplicate:false,presence:state.presence};
        }
        state.presence=presence.active?presence:null;
        state.presence_transition_at=presence.state_changed_at;
        state.presence_transition_id=presence.transition_id;
        if (!duplicateTransition) {
            const auditEntry={transition_id:presence.transition_id,active:presence.active===true,game_name:presence.active?presence.game_name:"",platform:presence.active?presence.platform:"unknown",source:presence.source,state_changed_at:presence.state_changed_at};
            state.presence_audit=[...(Array.isArray(state.presence_audit)?state.presence_audit:[]),auditEntry].slice(-20);
        }
        state.updated_at=new Date().toISOString();
        await client.query(
            `UPDATE creator_module_state SET state=$3::jsonb,updated_at=NOW() WHERE creator_id=$1 AND module_key=$2`,
            [creatorId,PUBLIC_GAME_ACTIVITY_MODULE_KEY,JSON.stringify(state)]
        );
        await client.query("COMMIT");
        if (String(creatorId)===String(DEFAULT_CREATOR_ID)) publicCommunityStatsCache.expires_at=0;
        return {accepted:true,duplicate:Boolean(duplicateTransition),presence:state.presence};
    } catch (error) {
        try { await client.query("ROLLBACK"); } catch {}
        throw error;
    } finally {
        client.release();
    }
}
async function clearCreatorGameActivity(creatorId) {
    await pool.query(
        `INSERT INTO creator_module_state (creator_id,module_key,state,updated_at)
         VALUES ($1,$2,$3::jsonb,NOW())
         ON CONFLICT (creator_id,module_key) DO UPDATE SET state=EXCLUDED.state,updated_at=NOW()`,
        [creatorId,PUBLIC_GAME_ACTIVITY_MODULE_KEY,JSON.stringify({version:4,events:[],presence:null,presence_transition_at:new Date().toISOString(),presence_transition_id:null,presence_audit:[],updated_at:new Date().toISOString()})]
    );
    if (String(creatorId)===String(DEFAULT_CREATOR_ID)) publicCommunityStatsCache.expires_at=0;
    return {cleared:true};
}

async function getPublicRecentGames(creatorId,{days=PUBLIC_GAME_ACTIVITY_WINDOW_DAYS,limit=6}={}) {
    const safeDays=Math.max(1,Math.min(30,Math.round(Number(days)||PUBLIC_GAME_ACTIVITY_WINDOW_DAYS)));
    const safeLimit=Math.max(1,Math.min(8,Math.round(Number(limit)||6)));
    const moduleState=await getPublicGameActivityModuleState(creatorId);
    const state=normalizeStoredGameActivityState(moduleState?.state||{});
    const cutoff=Date.now()-safeDays*24*60*60*1000;
    const grouped=new Map();
    for (const event of state.events) {
        const start=Math.max(Date.parse(event.started_at),cutoff);
        const end=Date.parse(event.ended_at);
        if (!Number.isFinite(start)||!Number.isFinite(end)||end<=start) continue;
        const seconds=Math.max(0,Math.min(Number(event.duration_seconds||0),Math.round((end-start)/1000)));
        if (seconds<30) continue;
        const gameKey=publicGameActivityKey(event.game_name);
        if (!gameKey) continue;
        const current=grouped.get(gameKey)||{key:gameKey,name:event.game_name,duration_seconds:0,sessions:0,last_played_at:null,platform:event.platform||"unknown",source:event.source||"launcher_manual"};
        current.duration_seconds+=seconds;
        current.sessions+=1;
        if (!current.last_played_at||Date.parse(event.ended_at)>Date.parse(current.last_played_at)) { current.last_played_at=event.ended_at; current.platform=event.platform||current.platform||"unknown"; current.source=event.source||current.source||"launcher_manual"; }
        grouped.set(gameKey,current);
    }
    const groupedGames=[...grouped.values()];
    const games=groupedGames
        .slice()
        .sort((a,b)=>b.duration_seconds-a.duration_seconds||b.sessions-a.sessions||Date.parse(b.last_played_at||0)-Date.parse(a.last_played_at||0))
        .slice(0,safeLimit)
        .map((item,index)=>({rank:index+1,key:item.key,name:item.name,minutes:Math.max(1,Math.round(item.duration_seconds/60)),sessions:item.sessions,last_played_at:item.last_played_at,platform:item.platform||"unknown",source:item.source||"launcher_manual"}));
    const recent=groupedGames
        .slice()
        .sort((a,b)=>Date.parse(b.last_played_at||0)-Date.parse(a.last_played_at||0)||b.duration_seconds-a.duration_seconds)
        .slice(0,Math.min(3,safeLimit))
        .map((item,index)=>({position:index+1,key:item.key,name:item.name,minutes:Math.max(1,Math.round(item.duration_seconds/60)),sessions:item.sessions,last_played_at:item.last_played_at,platform:item.platform||"unknown",source:item.source||"launcher_manual"}));
    return {
        available:games.length>0,
        window_days:safeDays,
        source:"cfs_launcher_opt_in",
        playtime_scope:"rolling_window",
        updated_at:moduleState?.updated_at||null,
        active:state.presence?.active===true?{
            game_name:state.presence.game_name,
            platform:state.presence.platform,
            source:state.presence.source,
            started_at:state.presence.started_at,
            reported_at:state.presence.reported_at,
            state_changed_at:state.presence.state_changed_at,
            elapsed_seconds:state.presence.started_at?Math.max(0,Math.floor((Date.now()-Date.parse(state.presence.started_at))/1000)):0,
            resumed_after_restart:state.presence.resumed_after_restart===true,
            freshness_seconds:state.presence.reported_at?Math.max(0,Math.floor((Date.now()-Date.parse(state.presence.reported_at))/1000)):null,
            presence_id:state.presence.transition_id||null
        }:null,
        games,
        recent
    };
}

async function getPreferredPublicRecentGames(creatorId,{days=PUBLIC_GAME_ACTIVITY_WINDOW_DAYS,limit=6}={}) {
    const wantsPlayStation =
        String(creatorId) === String(DEFAULT_CREATOR_ID) &&
        PUBLIC_PLAYSTATION_ENABLED &&
        Boolean(PUBLIC_PLAYSTATION_NPSSO);

    if (!wantsPlayStation) {
        return getPublicRecentGames(creatorId,{days,limit});
    }

    try {
        return await fetchPublicPlayStationRecentGames({
            npsso: PUBLIC_PLAYSTATION_NPSSO,
            limit: Math.min(PUBLIC_PLAYSTATION_RECENT_LIMIT, Math.max(3, Number(limit) || 6)),
            timeoutMs: PUBLIC_COMMUNITY_STATS_PROVIDER_TIMEOUT_MS
        });
    } catch (error) {
        safeLogError("public-community-playstation", error);
        const launcherFallback = await getPublicRecentGames(creatorId,{days,limit});
        if (launcherFallback?.available) {
            return {
                ...launcherFallback,
                fallback_from: "playstation_network"
            };
        }
        throw error;
    }
}

function creatorGameIdentity(gameName="",platform="unknown") {
    const normalizedTitle=String(gameName||"").replace(/[™®©]/g,"").normalize("NFKC").replace(/[\u0000-\u001f\u007f]/g," ").replace(/[^a-z0-9äöüß]+/gi," ").replace(/\s+/g," ").trim().toLowerCase().slice(0,120);
    const safePlatform=["playstation_5","playstation_4","pc","xbox_series","xbox_one","switch","unknown"].includes(String(platform||""))?String(platform):"unknown";
    return {normalized_title:normalizedTitle,game_id:normalizedTitle?`cfsgi_${crypto.createHash("sha256").update(`${safePlatform}|${normalizedTitle}`).digest("hex").slice(0,24)}`:""};
}
function creatorGameContextFromActivity(activity={}) {
    const active=activity?.active&&activity.active.game_name?activity.active:null;
    if (active) { const identity=creatorGameIdentity(active.game_name,active.platform),freshness=Math.max(0,Number(active.freshness_seconds)||0); return {mode:"active",game_name:active.game_name,...identity,platform:active.platform||"unknown",source:active.source||"launcher_manual",started_at:active.started_at||null,elapsed_seconds:Math.max(0,Number(active.elapsed_seconds)||0),freshness_seconds:freshness,freshness_state:freshness<=Math.ceil(PUBLIC_GAME_ACTIVITY_PRESENCE_TTL_MS/1000)?"fresh":"stale",observed_at:active.reported_at||null,resumed_after_restart:active.resumed_after_restart===true,presence_id:active.presence_id||null}; }
    const recent=Array.isArray(activity?.recent)?activity.recent[0]:null;
    if (recent?.name) { const identity=creatorGameIdentity(recent.name,recent.platform); return {mode:"recent",game_name:recent.name,...identity,platform:recent.platform||"unknown",source:recent.source||"launcher_manual",last_played_at:recent.last_played_at||null,minutes:Math.max(0,Number(recent.minutes)||0)}; }
    return {mode:"none",game_name:"",normalized_title:"",game_id:"",platform:"unknown",source:"",last_played_at:null,minutes:0};
}

// ============================================================
// ÖFFENTLICHE COMMUNITY-KENNZAHLEN
//
// Nur grobe, bewusst öffentliche Kennzahlen. Keine Tokens, Account-IDs,
// Scopes oder Provider-Rohdaten werden an den Browser weitergegeben.
// TikTok wird über die bereits autorisierte Default-Creator-Verbindung
// aktualisiert. Discord wird über den öffentlichen Invite serverseitig
// abgefragt. Beide Provider liegen hinter einem gemeinsamen Cache.
// ============================================================

function publicCommunityCount(value) {
    const number = Number(value);
    if (!Number.isFinite(number) || number < 0) return null;
    return Math.floor(number);
}

async function fetchPublicDiscordCommunityStats() {
    if (!PUBLIC_DISCORD_INVITE_CODE) {
        throw new Error("Discord Invite-Code ist nicht konfiguriert.");
    }

    const target = assertOutboundHttpsUrl(
        `https://discord.com/api/v10/invites/${encodeURIComponent(PUBLIC_DISCORD_INVITE_CODE)}?with_counts=true&with_expiration=true`,
        { allowedHosts:["discord.com"], label:"Discord Invite API URL" }
    );

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), PUBLIC_COMMUNITY_STATS_PROVIDER_TIMEOUT_MS);

    try {
        const response = await fetch(target.href, {
            method:"GET",
            redirect:"error",
            headers:{
                "Accept":"application/json",
                "User-Agent":"cfs-zockt-community-stats/1.0 (+https://cfs-zockt.de)"
            },
            signal:controller.signal
        });
        const text = await readResponseTextBounded(response, 128 * 1024);
        let data = {};
        try { data = text ? JSON.parse(text) : {}; }
        catch { throw new Error("Discord Invite API lieferte ungültiges JSON."); }
        if (!response.ok) throw new Error(`Discord Invite API antwortete mit HTTP ${response.status}.`);

        const members = publicCommunityCount(data?.approximate_member_count);
        const online = publicCommunityCount(data?.approximate_presence_count);
        if (members === null) throw new Error("Discord Mitgliederzahl fehlt in der Provider-Antwort.");

        return {
            available:true,
            members,
            online,
            stale:false,
            updated_at:new Date().toISOString()
        };
    } catch (error) {
        if (error?.name === "AbortError") {
            throw new Error("Discord Mitgliederzahl konnte nicht rechtzeitig geladen werden.");
        }
        throw error;
    } finally {
        clearTimeout(timeout);
    }
}

async function resolvePublicTikTokProfileConnection() {
    // Prefer the Creator-Suite account that owns the legacy/public CFS TikTok slot.
    // This keeps the public homepage on the same TikTok profile already connected
    // inside the Creator Suite instead of requiring a second OAuth connection.
    try {
        const owner = await pool.query(
            `SELECT creator_id FROM creator_tiktok_legacy_owner WHERE slot='default' LIMIT 1`
        );
        const ownerId = owner.rows[0]?.creator_id ? String(owner.rows[0].creator_id) : "";
        if (ownerId) {
            const ownerConnection = await getConnection(ownerId);
            if (ownerConnection?.connected) {
                return { creatorId: ownerId, connection: ownerConnection, source:"creator_suite_owner" };
            }
        }
    } catch (error) {
        safeLogError("public-community-tiktok-owner", error);
    }

    const legacyConnection = await getConnection(DEFAULT_CREATOR_ID);
    return { creatorId: DEFAULT_CREATOR_ID, connection: legacyConnection, source:"legacy_default" };
}

async function fetchPublicTikTokCommunityStats() {
    const resolved = await resolvePublicTikTokProfileConnection();
    const creatorId = resolved.creatorId;
    const connection = resolved.connection;
    const scopes = String(connection?.scope || "")
        .split(/[\s,]+/)
        .map(value => value.trim())
        .filter(Boolean);

    if (!connection?.connected || !scopes.includes("user.info.stats")) {
        if (PUBLIC_TIKTOK_FOLLOWERS_FALLBACK !== null) {
            return {
                available:true,
                followers:PUBLIC_TIKTOK_FOLLOWERS_FALLBACK,
                stale:false,
                source:"environment_fallback",
                updated_at:null
            };
        }
        return {
            available:false,
            followers:null,
            stale:false,
            source:"unavailable",
            updated_at:connection?.updated_at || null
        };
    }

    let profile = {
        follower_count:publicCommunityCount(connection?.follower_count),
        updated_at:connection?.updated_at || null
    };
    let stale = false;
    const storedAt = connection?.updated_at ? new Date(connection.updated_at).getTime() : 0;
    const storedFresh = Number.isFinite(storedAt) && storedAt > 0 && (Date.now() - storedAt) < PUBLIC_COMMUNITY_STATS_CACHE_TTL_MS;

    if (!storedFresh) {
        try {
            profile = await fetchTikTokProfile(creatorId);
        } catch (error) {
            stale = true;
            safeLogError("public-community-tiktok-refresh", error);
        }
    }

    const followers = publicCommunityCount(profile?.follower_count);
    if (followers === null && PUBLIC_TIKTOK_FOLLOWERS_FALLBACK !== null) {
        return {
            available:true,
            followers:PUBLIC_TIKTOK_FOLLOWERS_FALLBACK,
            stale:false,
            source:"environment_fallback",
            updated_at:null
        };
    }
    return {
        available:followers !== null,
        followers,
        stale,
        source:resolved.source === "creator_suite_owner" ? "creator_suite_tiktok" : "tiktok_oauth",
        updated_at:profile?.updated_at || connection?.updated_at || null
    };
}

const PUBLIC_TWITCH_LIVE_CACHE_TTL_MS = Math.max(5_000, Math.min(60_000, Number(process.env.CFS_PUBLIC_TWITCH_LIVE_CACHE_TTL_MS || 12_000)));
const PUBLIC_TWITCH_STALE_LIVE_MAX_MS = 2 * 60 * 1000;
const publicTwitchLiveCache = new Map();

const PUBLIC_LIVE_EVENT_FRESH_MS = 10 * 60 * 1000;
const PUBLIC_LIVE_SESSION_FRESH_MS = 20 * 60 * 1000;
const PUBLIC_LIVE_OVERRIDE_MAX_MS = 12 * 60 * 60 * 1000;
const PUBLIC_LIVE_OVERRIDE_MODULE_KEY = "public_live_control";
const PUBLIC_LIVE_PROVIDER_ACTIVE_STATES = new Set(["live","active","connected","online","ready","streaming"]);

async function getCreatorPublicLiveControl(creatorId) {
    const result = await pool.query(
        `SELECT state,updated_at
         FROM creator_module_state
         WHERE creator_id=$1 AND module_key=$2
         LIMIT 1`,
        [creatorId,PUBLIC_LIVE_OVERRIDE_MODULE_KEY]
    );
    const raw = result.rows[0]?.state && typeof result.rows[0].state === "object" ? result.rows[0].state : {};
    const startedAt = raw.started_at ? new Date(raw.started_at).getTime() : 0;
    const expiresAt = raw.expires_at ? new Date(raw.expires_at).getTime() : 0;
    const active = raw.active === true && Number.isFinite(expiresAt) && expiresAt > Date.now();
    return {
        active,
        started_at:active && Number.isFinite(startedAt) ? new Date(startedAt).toISOString() : null,
        expires_at:active ? new Date(expiresAt).toISOString() : null,
        updated_at:result.rows[0]?.updated_at || null,
        expired:raw.active === true && !active
    };
}

async function setCreatorPublicLiveControl(creatorId, active) {
    const now = new Date();
    const state = active === true ? {
        version:1,
        active:true,
        started_at:now.toISOString(),
        expires_at:new Date(now.getTime()+PUBLIC_LIVE_OVERRIDE_MAX_MS).toISOString(),
        source:"creator_dashboard"
    } : {
        version:1,
        active:false,
        started_at:null,
        expires_at:null,
        stopped_at:now.toISOString(),
        source:"creator_dashboard"
    };
    const result = await pool.query(
        `INSERT INTO creator_module_state (creator_id,module_key,state,updated_at)
         VALUES ($1,$2,$3::jsonb,NOW())
         ON CONFLICT (creator_id,module_key)
         DO UPDATE SET state=EXCLUDED.state,updated_at=NOW()
         RETURNING state,updated_at`,
        [creatorId,PUBLIC_LIVE_OVERRIDE_MODULE_KEY,JSON.stringify(state)]
    );
    return {
        active:state.active === true,
        started_at:state.started_at,
        expires_at:state.expires_at,
        updated_at:result.rows[0]?.updated_at || now.toISOString()
    };
}

function twitchVideoDurationSeconds(value = "") {
    const raw=String(value||"").trim().toLowerCase();
    const match=raw.match(/^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/);
    if(!match)return 0;
    return Math.max(0,(Number(match[1]||0)*3600)+(Number(match[2]||0)*60)+Number(match[3]||0));
}

async function latestTwitchArchive(userId,appToken){
    const id=String(userId||"").trim();
    if(!id)return null;
    const params=new URLSearchParams({user_id:id,type:"archive",first:"1"});
    const data=await twitchFetch(`${TWITCH_VIDEOS_URL}?${params.toString()}`,{headers:{Authorization:`Bearer ${appToken}`,"Client-Id":TWITCH_CLIENT_ID}});
    const video=Array.isArray(data?.data)?data.data[0]:null;
    if(!video?.created_at)return null;
    const startedAt=new Date(video.created_at);
    if(!Number.isFinite(startedAt.getTime()))return null;
    const durationSeconds=twitchVideoDurationSeconds(video.duration);
    const endedAt=durationSeconds>0?new Date(startedAt.getTime()+durationSeconds*1000):null;
    return {
        started_at:startedAt.toISOString(),
        ended_at:endedAt&&Number.isFinite(endedAt.getTime())?endedAt.toISOString():null,
        title:studioText(video.title,220,""),
        url:/^https:\/\//i.test(String(video.url||""))?String(video.url):""
    };
}

async function seedTwitchLastLiveHistory(creatorId,{startedAt=null,endedAt=null}={}){
    if(!startedAt)return;
    await pool.query(`
      INSERT INTO creator_provider_live_state(creator_id,provider,session_id,connected,started_at,last_event_at,updated_at)
      VALUES($1,'twitch',NULL,FALSE,$2,$3,NOW())
      ON CONFLICT(creator_id,provider) DO UPDATE SET
        started_at=COALESCE(creator_provider_live_state.started_at,EXCLUDED.started_at),
        last_event_at=COALESCE(creator_provider_live_state.last_event_at,EXCLUDED.last_event_at)
    `,[normalizeCreatorId(creatorId),startedAt,endedAt]);
}

function publicTwitchChannelUrl(login = "") {
    const normalized = String(login || "").trim().toLowerCase();
    if (/^[a-z0-9_]{3,25}$/.test(normalized)) return `https://www.twitch.tv/${normalized}`;
    return PUBLIC_TWITCH_PROFILE_URL;
}

async function refreshPublicTwitchLiveSnapshot(creatorId) {
    const id = normalizeCreatorId(creatorId);
    const connectionResult = await pool.query(
        `SELECT connected,twitch_user_id,login,display_name,updated_at
         FROM twitch_connections
         WHERE creator_id=$1
         LIMIT 1`,
        [id]
    );
    const connection = connectionResult.rows[0] || null;
    const previous = await getProviderLiveState(id, "twitch");
    const profileUrl = publicTwitchChannelUrl(connection?.login);
    const base = {
        available:Boolean(connection?.connected && connection?.twitch_user_id && twitchConfigured()),
        connected:Boolean(connection?.connected),
        provider:"twitch",
        login:String(connection?.login || "").slice(0, 80),
        display_name:String(connection?.display_name || connection?.login || "cfs_zockt").slice(0, 120),
        profile_url:profileUrl,
        live:false,
        status:"unavailable",
        authoritative:false,
        viewer_count:0,
        title:"",
        game_name:"",
        started_at:null,
        last_live_started_at:previous?.started_at || null,
        last_live_ended_at:previous?.connected === false && previous?.started_at ? (previous?.last_event_at || null) : null,
        checked_at:null,
        stale:false
    };

    if (!base.available) return base;

    const checkedAt = new Date().toISOString();
    try {
        const appToken = await twitchAppAccessToken();
        const data = await twitchFetch(
            `${TWITCH_STREAMS_URL}?user_id=${encodeURIComponent(connection.twitch_user_id)}`,
            {headers:{Authorization:`Bearer ${appToken}`,"Client-Id":TWITCH_CLIENT_ID}}
        );
        const stream = Array.isArray(data?.data) ? data.data[0] : null;
        if (stream) {
            await saveTwitchProviderLiveState(id, {
                connected:true,
                sessionId:`twitch:${String(stream.id || connection.twitch_user_id).slice(0,180)}`,
                startedAt:stream.started_at || checkedAt,
                lastEventAt:checkedAt
            });
        } else if (previous?.connected === true) {
            // Der erste bestätigte Offline-Poll nach einer LIVE-Phase ist zugleich
            // unser belastbarer Fallback für "zuletzt live", falls EventSub ausfällt.
            await saveTwitchProviderLiveState(id, {connected:false,lastEventAt:checkedAt});
        } else if (!previous?.updated_at) {
            await saveTwitchProviderLiveState(id, {connected:false});
        }

        // Beim ersten Deploy kann noch kein historischer Offline-Zeitpunkt in CFS
        // existieren. In diesem Fall bootstrappen wir einmalig aus dem letzten
        // Twitch-Archiv (sofern der Kanal VODs veröffentlicht).
        if (!stream && (!previous?.started_at || !previous?.last_event_at)) {
            try {
                const archive = await latestTwitchArchive(connection.twitch_user_id, appToken);
                if (archive?.started_at) {
                    await seedTwitchLastLiveHistory(id, {startedAt:archive.started_at,endedAt:archive.ended_at || archive.started_at});
                }
            } catch (historyError) {
                safeLogError("public-twitch-history-refresh", historyError);
            }
        }

        const state = await getProviderLiveState(id, "twitch");
        return {
            ...base,
            live:Boolean(stream),
            status:stream ? "live" : "offline",
            authoritative:true,
            viewer_count:stream ? Math.max(0, Number(stream.viewer_count) || 0) : 0,
            title:stream ? studioText(stream.title, 220, "") : "",
            game_name:stream ? studioText(stream.game_name, 160, "") : "",
            started_at:stream?.started_at || null,
            last_live_started_at:state?.started_at || stream?.started_at || null,
            last_live_ended_at:!stream && state?.started_at ? (state?.last_event_at || null) : null,
            checked_at:checkedAt,
            stale:false
        };
    } catch (error) {
        safeLogError("public-twitch-live-refresh", error);
        const updatedMs = previous?.updated_at ? new Date(previous.updated_at).getTime() : 0;
        const recentCachedLive = previous?.connected === true && Number.isFinite(updatedMs) && updatedMs > 0 && (Date.now() - updatedMs) <= PUBLIC_TWITCH_STALE_LIVE_MAX_MS;
        return {
            ...base,
            live:recentCachedLive,
            status:recentCachedLive ? "live" : "unknown",
            authoritative:false,
            started_at:recentCachedLive ? (previous?.started_at || null) : null,
            last_live_started_at:previous?.started_at || null,
            last_live_ended_at:!recentCachedLive && previous?.started_at ? (previous?.last_event_at || null) : null,
            checked_at:checkedAt,
            stale:true
        };
    }
}

async function getPublicTwitchLiveSnapshot(creatorId) {
    const id = normalizeCreatorId(creatorId);
    const cached = publicTwitchLiveCache.get(id);
    if (cached?.payload && cached.expires_at > Date.now()) return cached.payload;
    if (cached?.in_flight) return cached.in_flight;
    const entry = cached || {payload:null,expires_at:0,in_flight:null};
    entry.in_flight = refreshPublicTwitchLiveSnapshot(id)
        .then(payload => {
            entry.payload = payload;
            entry.expires_at = Date.now() + PUBLIC_TWITCH_LIVE_CACHE_TTL_MS;
            return payload;
        })
        .finally(() => { entry.in_flight = null; });
    publicTwitchLiveCache.set(id, entry);
    return entry.in_flight;
}

async function getPublicLiveEvidence(creatorId) {
    const [live, bridge, latestEventResult, liveSessionResult, manualControl] = await Promise.all([
        getStudioLiveState(creatorId),
        getStudioBridgeStatus(creatorId),
        pool.query(
            `SELECT event_type,provider,created_at
             FROM creator_live_events
             WHERE creator_id=$1
             ORDER BY created_at DESC,id DESC
             LIMIT 1`,
            [creatorId]
        ),
        pool.query(
            `SELECT id,provider,status,metadata,started_at,updated_at,ended_at
             FROM creator_live_sessions
             WHERE creator_id=$1
             ORDER BY started_at DESC
             LIMIT 1`,
            [creatorId]
        ),
        getCreatorPublicLiveControl(creatorId)
    ]);

    const now = Date.now();
    const latestEvent = latestEventResult.rows[0] || null;
    const latestEventAt = latestEvent?.created_at ? new Date(latestEvent.created_at).getTime() : 0;
    const recentEvent = Boolean(latestEventAt) && now - latestEventAt <= PUBLIC_LIVE_EVENT_FRESH_MS;
    const latestEventType = String(latestEvent?.event_type || "");
    const explicitEnd = recentEvent && latestEventType === "live_end";
    const liveTraffic = recentEvent && !["live_end"].includes(latestEventType);

    const session = liveSessionResult.rows[0] || null;
    const sessionUpdatedAt = session?.updated_at ? new Date(session.updated_at).getTime() : 0;
    const recentOpenSession = Boolean(session && session.status === "live" && !session.ended_at && sessionUpdatedAt && now - sessionUpdatedAt <= PUBLIC_LIVE_SESSION_FRESH_MS);

    const caps = bridge?.capabilities && typeof bridge.capabilities === "object" ? bridge.capabilities : {};
    const integrationHealth = caps.integration_health && typeof caps.integration_health === "object" && !Array.isArray(caps.integration_health)
        ? caps.integration_health
        : {};
    const liveProviderHealth = integrationHealth.live_provider && typeof integrationHealth.live_provider === "object" && !Array.isArray(integrationHealth.live_provider)
        ? integrationHealth.live_provider
        : {};
    const providerKey = String(liveProviderHealth.key || caps.live_provider_key || caps.provider || "").toLowerCase();
    const providerStatus = String(liveProviderHealth.status || caps.live_provider_status || caps.tikfinity_status || "").toLowerCase();
    const providerReady = bridge?.online === true && (
        (caps.live_provider_health_v1 === true && liveProviderHealth.ready === true) ||
        (caps.live_provider_health_v1 === true && caps.live_provider_ready === true) ||
        caps.tikfinity_healthy === true
    );
    const providerLive = providerReady && (!providerStatus || PUBLIC_LIVE_PROVIDER_ACTIVE_STATES.has(providerStatus));

    const manualLive = manualControl?.active === true;
    const positiveSignal = live?.connected === true || liveTraffic || recentOpenSession || providerLive || manualLive;
    const detectedLive = positiveSignal;

    let status = "unknown";
    let source = "none";
    if (detectedLive) {
        status = "live";
        if (manualLive) source = "creator_dashboard";
        else if (live?.connected === true) source = "live_state";
        else if (liveTraffic) source = "recent_live_event";
        else if (providerLive) source = "launcher_provider";
        else if (recentOpenSession) source = "open_live_session";
    } else if (explicitEnd) {
        // Ein altes live_end darf ein neueres positives Signal nicht mehr überschreiben.
        // Ohne positives Signal ist das Ende dagegen eine belastbare OFFLINE-Aussage.
        status = "offline";
        source = "live_end";
    }

    return {
        live,
        bridge,
        manual_control:manualControl,
        status,
        source,
        latest_event_at: latestEvent?.created_at || null,
        latest_event_type: latestEventType || null,
        provider_key:providerKey,
        provider_status:providerStatus,
        provider_ready:providerReady,
        session: session ? {
            id:String(session.id || ""),
            provider:String(session.provider || "none"),
            provider_hint:String(session?.metadata?.provider || session?.metadata?.source_provider || "").toLowerCase().slice(0,40),
            status:String(session.status || ""),
            started_at:session.started_at || null,
            updated_at:session.updated_at || null,
            ended_at:session.ended_at || null
        } : null
    };
}

const PUBLIC_TIKTOK_TRACKING_PROVIDERS = new Set(["tiktool","tiktok","tikfinity"]);
const PUBLIC_TIKTOK_INACTIVE_STATES = new Set(["idle","offline","disconnected","stopped"]);

function isPublicTikTokTrackingProvider(value = "") {
    return PUBLIC_TIKTOK_TRACKING_PROVIDERS.has(String(value || "").trim().toLowerCase());
}

async function getPublicTikTokTrackingState(creatorId) {
    return (await pool.query(
        `SELECT creator_id,provider,session_id,connected,started_at,last_event_at,updated_at
         FROM creator_provider_live_state
         WHERE creator_id=$1 AND provider='tiktok'
         LIMIT 1`,
        [normalizeCreatorId(creatorId)]
    )).rows[0] || null;
}

async function savePublicTikTokTrackingState(creatorId,{connected,sessionId=null,startedAt=null,lastEventAt=null}={}) {
    await pool.query(`
      INSERT INTO creator_provider_live_state(creator_id,provider,session_id,connected,started_at,last_event_at,updated_at)
      VALUES($1,'tiktok',$2,$3,$4,$5,NOW())
      ON CONFLICT(creator_id,provider) DO UPDATE SET
        session_id=CASE WHEN EXCLUDED.connected THEN COALESCE(EXCLUDED.session_id,creator_provider_live_state.session_id) ELSE creator_provider_live_state.session_id END,
        connected=EXCLUDED.connected,
        started_at=CASE WHEN EXCLUDED.connected THEN COALESCE(EXCLUDED.started_at,creator_provider_live_state.started_at,NOW()) ELSE creator_provider_live_state.started_at END,
        last_event_at=COALESCE(EXCLUDED.last_event_at,creator_provider_live_state.last_event_at),
        updated_at=NOW()
    `,[normalizeCreatorId(creatorId),sessionId,Boolean(connected),startedAt,lastEventAt]);
}

async function getPublicTikTokLiveSnapshot(creatorId, evidence = null) {
    const id = normalizeCreatorId(creatorId);
    const [connectionResult, historyResult] = await Promise.all([
        pool.query(
            `SELECT connected,display_name,updated_at
             FROM tiktok_connections
             WHERE creator_id=$1
             LIMIT 1`,
            [id]
        ),
        pool.query(
            `SELECT id,provider,status,metadata,started_at,ended_at,updated_at
             FROM creator_live_sessions
             WHERE creator_id=$1
               AND ended_at IS NOT NULL
               AND (
                    LOWER(provider)='tiktok'
                    OR (
                        LOWER(provider)='launcher_bridge'
                        AND LOWER(COALESCE(metadata->>'provider',metadata->>'source_provider','')) IN ('tiktool','tiktok','tikfinity')
                    )
               )
             ORDER BY ended_at DESC NULLS LAST,started_at DESC
             LIMIT 1`,
            [id]
        )
    ]);
    const connection = connectionResult.rows[0] || null;
    const lastEnded = historyResult.rows[0] || null;
    const liveEvidence = evidence || await getPublicLiveEvidence(id);
    const providerKey = String(liveEvidence?.provider_key || "").toLowerCase();
    const providerStatus = String(liveEvidence?.provider_status || "").toLowerCase();
    const sessionHint = String(liveEvidence?.session?.provider_hint || "").toLowerCase();
    const providerIsTikTok = isPublicTikTokTrackingProvider(providerKey);
    const sessionIsTikTok = isPublicTikTokTrackingProvider(sessionHint) || String(liveEvidence?.session?.provider || "").toLowerCase() === "tiktok";
    const bridgeOnline = liveEvidence?.bridge?.online === true;
    const trackingReady = bridgeOnline && providerIsTikTok && liveEvidence?.provider_ready === true;
    const providerLive = bridgeOnline && providerIsTikTok && PUBLIC_LIVE_PROVIDER_ACTIVE_STATES.has(providerStatus);
    const providerOffline = bridgeOnline && providerIsTikTok && PUBLIC_TIKTOK_INACTIVE_STATES.has(providerStatus);
    let trackingState = await getPublicTikTokTrackingState(id);
    if (providerLive && trackingState?.connected !== true) {
        const detectedStart = liveEvidence?.manual_control?.started_at || liveEvidence?.live?.started_at || liveEvidence?.session?.started_at || new Date().toISOString();
        await savePublicTikTokTrackingState(id,{connected:true,sessionId:liveEvidence?.session?.id || null,startedAt:detectedStart,lastEventAt:new Date().toISOString()});
        trackingState = await getPublicTikTokTrackingState(id);
    } else if (providerOffline && trackingState?.connected === true) {
        await savePublicTikTokTrackingState(id,{connected:false,lastEventAt:new Date().toISOString()});
        trackingState = await getPublicTikTokTrackingState(id);
    }
    const evidenceTikTokLive = liveEvidence?.status === "live"
        && (providerIsTikTok || sessionIsTikTok || String(liveEvidence?.live?.provider || "").toLowerCase() === "tiktok")
        && !(providerIsTikTok && providerOffline);
    const live = providerLive || evidenceTikTokLive;
    const explicitOffline = liveEvidence?.status === "offline" && (providerIsTikTok || sessionIsTikTok || Boolean(lastEnded));
    const status = live ? "live" : ((explicitOffline || providerOffline || (trackingState?.connected === false && trackingState?.started_at)) ? "offline" : "unknown");
    const trackedHistory = trackingState?.connected === false && trackingState?.started_at
        ? {started_at:trackingState.started_at,ended_at:trackingState.last_event_at || trackingState.updated_at || null}
        : null;
    const latestEnded = latestPublicLiveHistory(
        {provider:"session",at:lastEnded?.ended_at || null,started_at:lastEnded?.started_at || null},
        {provider:"tracker",at:trackedHistory?.ended_at || null,started_at:trackedHistory?.started_at || null}
    );
    const checkedAt = liveEvidence?.bridge?.last_seen_at || liveEvidence?.latest_event_at || liveEvidence?.session?.updated_at || trackingState?.updated_at || null;

    return {
        available:Boolean(connection?.connected),
        connected:Boolean(connection?.connected),
        provider:"tiktok",
        profile_url:PUBLIC_TIKTOK_PROFILE_URL,
        display_name:String(connection?.display_name || "cfs_zockt").slice(0,120),
        live,
        status,
        authoritative:false,
        tracking_ready:trackingReady,
        tracking_provider:providerIsTikTok ? providerKey : "none",
        provider_status:providerStatus || "unknown",
        source:live ? "launcher_tiktok_provider" : ((explicitOffline || providerOffline) ? "launcher_tiktok_end" : "launcher_tiktok_unknown"),
        viewer_count:live ? Math.max(0,Number(liveEvidence?.live?.viewers)||0) : 0,
        likes:live ? Math.max(0,Number(liveEvidence?.live?.likes)||0) : 0,
        shares:live ? Math.max(0,Number(liveEvidence?.live?.shares)||0) : 0,
        started_at:live ? (trackingState?.started_at || liveEvidence?.manual_control?.started_at || liveEvidence?.live?.started_at || liveEvidence?.session?.started_at || null) : null,
        last_live_started_at:latestEnded?.started_at || null,
        last_live_ended_at:latestEnded?.at || null,
        checked_at:checkedAt,
        stale:!bridgeOnline
    };
}

function latestPublicLiveHistory(...items) {
    return items
        .filter(item => item?.at)
        .map(item => ({...item,ms:new Date(item.at).getTime()}))
        .filter(item => Number.isFinite(item.ms))
        .sort((a,b) => b.ms-a.ms)[0] || null;
}

async function getPublicLiveSessionSnapshot() {
    const resolved = await resolvePublicTikTokProfileConnection();
    const creatorIds = [...new Set([resolved?.creatorId, DEFAULT_CREATOR_ID].filter(Boolean).map(String))];
    const states = await Promise.all(creatorIds.map(async creatorId => {
        const [evidenceResult, twitchResult, gameResult] = await Promise.allSettled([
            getPublicLiveEvidence(creatorId),
            getPublicTwitchLiveSnapshot(creatorId),
            getPublicRecentGames(creatorId,{limit:3})
        ]);
        const evidence = evidenceResult.status === "fulfilled" ? evidenceResult.value : {
            live:emptyStudioLiveState(),
            bridge:{online:false,capabilities:{}},
            status:"unknown",
            source:"error",
            latest_event_at:null,
            latest_event_type:null,
            provider_key:"",
            provider_status:"",
            provider_ready:false,
            session:null
        };
        let tiktok;
        try {
            tiktok = await getPublicTikTokLiveSnapshot(creatorId, evidence);
        } catch (error) {
            safeLogError("public-tiktok-live-snapshot", error);
            tiktok = {
                available:false,connected:false,provider:"tiktok",profile_url:PUBLIC_TIKTOK_PROFILE_URL,display_name:"cfs_zockt",
                live:false,status:"unknown",authoritative:false,tracking_ready:false,tracking_provider:"none",provider_status:"unknown",
                source:"error",viewer_count:0,likes:0,shares:0,started_at:null,last_live_started_at:null,last_live_ended_at:null,checked_at:null,stale:true
            };
        }
        return {
            creatorId,
            evidence,
            twitch: twitchResult.status === "fulfilled" ? twitchResult.value : {
                available:false,
                connected:false,
                provider:"twitch",
                profile_url:PUBLIC_TWITCH_PROFILE_URL,
                live:false,
                status:"unknown",
                authoritative:false,
                viewer_count:0,
                title:"",
                game_name:"",
                started_at:null,
                last_live_started_at:null,
                last_live_ended_at:null,
                checked_at:null,
                stale:true
            },
            tiktok,
            games: gameResult.status === "fulfilled" ? gameResult.value : {active:null,recent:[]}
        };
    }));

    const twitchLiveEntry = states.find(entry => entry.twitch?.live === true) || null;
    const tiktokLiveEntry = states.find(entry => entry.tiktok?.live === true) || null;
    const genericLiveEntry = states.find(entry => {
        if (entry.evidence?.status !== "live") return false;
        if (entry.evidence?.manual_control?.active === true) return true;
        const providerKey = String(entry.evidence?.provider_key || "").toLowerCase();
        const sessionHint = String(entry.evidence?.session?.provider_hint || "").toLowerCase();
        return !isPublicTikTokTrackingProvider(providerKey) && !isPublicTikTokTrackingProvider(sessionHint);
    }) || null;
    const twitchStatusEntry = twitchLiveEntry || states.find(entry => entry.twitch?.available === true || entry.twitch?.connected === true) || null;
    const tiktokStatusEntry = tiktokLiveEntry || states.find(entry => entry.tiktok?.available === true || entry.tiktok?.tracking_ready === true) || null;
    const selected = twitchLiveEntry || tiktokLiveEntry || genericLiveEntry || twitchStatusEntry || tiktokStatusEntry || states[0] || {
        creatorId:String(DEFAULT_CREATOR_ID),
        evidence:{live:emptyStudioLiveState(),bridge:{online:false,capabilities:{}},status:"unknown",source:"none",latest_event_at:null,latest_event_type:null,provider_key:"",provider_status:"",provider_ready:false,session:null},
        twitch:{available:false,connected:false,provider:"twitch",profile_url:PUBLIC_TWITCH_PROFILE_URL,live:false,status:"unknown",authoritative:false,viewer_count:0,title:"",game_name:"",started_at:null,last_live_started_at:null,last_live_ended_at:null,checked_at:null,stale:true},
        tiktok:{available:false,connected:false,provider:"tiktok",profile_url:PUBLIC_TIKTOK_PROFILE_URL,display_name:"cfs_zockt",live:false,status:"unknown",authoritative:false,tracking_ready:false,tracking_provider:"none",provider_status:"unknown",source:"none",viewer_count:0,likes:0,shares:0,started_at:null,last_live_started_at:null,last_live_ended_at:null,checked_at:null,stale:true},
        games:{active:null,recent:[]}
    };
    const activeGameEntry = states.find(entry => entry.games?.active?.game_name) || selected;
    const evidence = selected.evidence || {};
    const live = evidence.live || emptyStudioLiveState();
    const publicTwitch = twitchStatusEntry?.twitch || selected.twitch || {};
    const publicTikTok = tiktokStatusEntry?.tiktok || selected.tiktok || {};
    const genericDetectedLive = evidence.status === "live";
    const twitchLive = twitchLiveEntry?.twitch?.live === true;
    const tiktokLive = tiktokLiveEntry?.tiktok?.live === true;
    const detectedLive = Boolean(twitchLive || tiktokLive || genericLiveEntry);

    const channelStates = [];
    if (publicTwitch?.connected === true || publicTwitch?.available === true) {
        channelStates.push(publicTwitch?.authoritative === true ? String(publicTwitch.status || "unknown") : "unknown");
    }
    if (publicTikTok?.connected === true || publicTikTok?.tracking_ready === true) {
        channelStates.push(String(publicTikTok.status || "unknown"));
    }
    let status = "unknown";
    if (detectedLive || channelStates.includes("live")) status = "live";
    else if (channelStates.length && channelStates.every(value => value === "offline")) status = "offline";
    else if (!channelStates.length && evidence.status === "offline") status = "offline";

    let provider = "none";
    if (twitchLive && tiktokLive) provider = "multistream";
    else if (twitchLive) provider = "twitch";
    else if (tiktokLive) provider = "tiktok";
    else if (genericDetectedLive) {
        const genericProvider = String(evidence.provider_key || evidence.session?.provider_hint || live.provider || evidence.session?.provider || "none").toLowerCase();
        provider = isPublicTikTokTrackingProvider(genericProvider) || genericProvider === "launcher_bridge" ? "tiktok" : genericProvider;
    }

    let source = evidence.source || "none";
    if (provider === "multistream") source = "twitch_api+launcher_tiktok_provider";
    else if (provider === "twitch") source = twitchLiveEntry?.twitch?.authoritative ? "twitch_api" : "twitch_cached_live";
    else if (provider === "tiktok") source = publicTikTok?.source || "launcher_tiktok_provider";
    else if (status === "offline" && publicTwitch?.authoritative === true && publicTwitch?.status === "offline") source = "twitch_api";

    const launcherGame = activeGameEntry.games?.active?.game_name ? activeGameEntry.games.active : null;
    const twitchGame = twitchLiveEntry?.twitch?.game_name ? {
        game_name:twitchLiveEntry.twitch.game_name,
        platform:"twitch",
        started_at:twitchLiveEntry.twitch.started_at || null,
        elapsed_seconds:twitchLiveEntry.twitch.started_at ? Math.max(0,Math.floor((Date.now()-new Date(twitchLiveEntry.twitch.started_at).getTime())/1000)) : 0,
        source:"twitch_api"
    } : null;
    const activeGame = twitchGame || launcherGame;
    const twitchProfileUrl = publicTwitch?.profile_url || PUBLIC_TWITCH_PROFILE_URL;
    const tiktokProfileName = String(publicTikTok?.display_name || resolved?.connection?.display_name || "cfs_zockt").slice(0,120);
    const twitchProfileName = String(publicTwitch?.display_name || publicTwitch?.login || "cfs_zockt").slice(0,120);
    const activeProfileName = provider === "twitch" ? twitchProfileName : (provider === "multistream" ? "cfs_zockt" : tiktokProfileName);
    const activeProfileUrl = provider === "twitch" ? twitchProfileUrl : PUBLIC_TIKTOK_PROFILE_URL;
    const twitchLastLiveAt = publicTwitch?.last_live_ended_at || null;
    const tiktokLastLiveAt = publicTikTok?.last_live_ended_at || null;
    const latestHistory = latestPublicLiveHistory(
        {provider:"twitch",at:twitchLastLiveAt,started_at:publicTwitch?.last_live_started_at || null},
        {provider:"tiktok",at:tiktokLastLiveAt,started_at:publicTikTok?.last_live_started_at || null}
    );
    const combinedViewers = (twitchLive ? Math.max(0,Number(twitchLiveEntry?.twitch?.viewer_count)||0) : 0)
        + (tiktokLive ? Math.max(0,Number(tiktokLiveEntry?.tiktok?.viewer_count)||0) : 0);

    return {
        ok:true,
        live:detectedLive,
        status,
        provider,
        live_source:source,
        profile_name:activeProfileName,
        profile_url:activeProfileUrl,
        viewers:detectedLive ? combinedViewers || (publicCommunityCount(live.viewers) || 0) : 0,
        likes:tiktokLive ? Math.max(0,Number(tiktokLiveEntry?.tiktok?.likes)||0) : (provider === "twitch" ? 0 : (publicCommunityCount(live.likes) || 0)),
        shares:tiktokLive ? Math.max(0,Number(tiktokLiveEntry?.tiktok?.shares)||0) : (provider === "twitch" ? 0 : (publicCommunityCount(live.shares) || 0)),
        followers_gained:provider === "twitch" ? 0 : (publicCommunityCount(live.followers_gained) || 0),
        title:twitchLive ? String(twitchLiveEntry?.twitch?.title || "").slice(0,220) : "",
        started_at:detectedLive
            ? (twitchLiveEntry?.twitch?.started_at || tiktokLiveEntry?.tiktok?.started_at || evidence.manual_control?.started_at || live.started_at || evidence.session?.started_at || null)
            : null,
        updated_at:twitchLiveEntry?.twitch?.checked_at || tiktokLiveEntry?.tiktok?.checked_at || publicTwitch?.checked_at || publicTikTok?.checked_at || live.updated_at || live.last_event_at || evidence.latest_event_at || evidence.session?.updated_at || null,
        last_live_at:latestHistory?.at || null,
        last_live_started_at:latestHistory?.started_at || null,
        last_live_provider:latestHistory?.provider || null,
        channels:{
            twitch:{
                connected:publicTwitch?.connected === true,
                available:publicTwitch?.available === true,
                status:String(publicTwitch?.status || "unknown"),
                authoritative:publicTwitch?.authoritative === true,
                stale:publicTwitch?.stale === true,
                profile_name:twitchProfileName,
                url:twitchProfileUrl,
                last_live_at:twitchLastLiveAt,
                last_live_started_at:publicTwitch?.last_live_started_at || null
            },
            tiktok:{
                connected:publicTikTok?.connected === true,
                available:publicTikTok?.available === true,
                status:String(publicTikTok?.status || "unknown"),
                authoritative:false,
                tracking_ready:publicTikTok?.tracking_ready === true,
                tracking_provider:String(publicTikTok?.tracking_provider || "none"),
                provider_status:String(publicTikTok?.provider_status || "unknown"),
                stale:publicTikTok?.stale === true,
                profile_name:tiktokProfileName,
                url:PUBLIC_TIKTOK_PROFILE_URL,
                last_live_at:tiktokLastLiveAt,
                last_live_started_at:publicTikTok?.last_live_started_at || null
            }
        },
        signal:{
            launcher_online:evidence.bridge?.online === true,
            launcher_reachable:evidence.bridge?.reachable === true,
            launcher_state:evidence.bridge?.connection_state || "offline",
            heartbeat_age_seconds:Number.isFinite(Number(evidence.bridge?.heartbeat_age_seconds)) ? Number(evidence.bridge.heartbeat_age_seconds) : null,
            latest_event_at:evidence.latest_event_at || null,
            latest_event_type:evidence.latest_event_type || null,
            twitch_checked_at:publicTwitch?.checked_at || null,
            twitch_authoritative:publicTwitch?.authoritative === true,
            tiktok_checked_at:publicTikTok?.checked_at || null,
            tiktok_tracking_ready:publicTikTok?.tracking_ready === true,
            tiktok_tracking_provider:String(publicTikTok?.tracking_provider || "none")
        },
        current_game:activeGame ? {
            name:String(activeGame.game_name || "").slice(0,160),
            platform:String(activeGame.platform || "unknown"),
            started_at:activeGame.started_at || null,
            elapsed_seconds:Math.max(0,Number(activeGame.elapsed_seconds)||0),
            source:String(activeGame.source || "launcher_manual")
        } : null
    };
}

async function getPublicCreatorStateSnapshot() {
    const [communityResult, liveResult] = await Promise.allSettled([
        getPublicCommunityStats(),
        getPublicLiveSessionSnapshot()
    ]);

    const community = communityResult.status === "fulfilled"
        ? communityResult.value
        : {
            ok:false,
            generated_at:new Date().toISOString(),
            refresh_seconds:Math.round(PUBLIC_COMMUNITY_STATS_CACHE_TTL_MS / 1000),
            discord:{available:false,members:null,online:null,stale:false,updated_at:null,url:PUBLIC_DISCORD_INVITE_URL},
            tiktok:{available:false,followers:null,stale:false,updated_at:null,url:PUBLIC_TIKTOK_PROFILE_URL},
            recent_games:{available:false,window_days:PUBLIC_PLAYSTATION_ENABLED?null:PUBLIC_GAME_ACTIVITY_WINDOW_DAYS,source:PUBLIC_PLAYSTATION_ENABLED?"playstation_network":"cfs_launcher_opt_in",playtime_scope:PUBLIC_PLAYSTATION_ENABLED?"lifetime":"rolling_window",updated_at:null,games:[],recent:[]}
        };
    const liveSession = liveResult.status === "fulfilled"
        ? liveResult.value
        : {
            ok:false,
            live:false,
            status:"unknown",
            provider:"none",
            live_source:"error",
            profile_name:"cfs_zockt",
            profile_url:PUBLIC_TIKTOK_PROFILE_URL,
            viewers:0,
            likes:0,
            shares:0,
            followers_gained:0,
            started_at:null,
            updated_at:null,
            last_live_at:null,
            last_live_started_at:null,
            last_live_provider:null,
            channels:{twitch:{connected:false,available:false,status:"unknown",authoritative:false,stale:true,profile_name:"cfs_zockt",url:PUBLIC_TWITCH_PROFILE_URL,last_live_at:null,last_live_started_at:null},tiktok:{connected:false,available:false,status:"unknown",authoritative:false,tracking_ready:false,tracking_provider:"none",provider_status:"unknown",stale:true,profile_name:"cfs_zockt",url:PUBLIC_TIKTOK_PROFILE_URL,last_live_at:null,last_live_started_at:null}},
            signal:{launcher_online:false,launcher_reachable:false,launcher_state:"offline",heartbeat_age_seconds:null,latest_event_at:null,latest_event_type:null,twitch_checked_at:null,twitch_authoritative:false,tiktok_checked_at:null,tiktok_tracking_ready:false,tiktok_tracking_provider:"none"},
            current_game:null
        };

    if (communityResult.status === "rejected") safeLogError("public-creator-state-community", communityResult.reason);
    if (liveResult.status === "rejected") safeLogError("public-creator-state-live", liveResult.reason);

    return buildPublicCreatorState({
        community,
        liveSession,
        generatedAt:new Date().toISOString()
    });
}

function creatorSecurityReadinessSnapshot(bridge = {}) {
    const production = NODE_ENV === "production";
    const checks = [];
    const add = (key, ok, {required=true, warning=false} = {}) => checks.push({key, ok:ok === true, required, warning:warning === true});

    add("https_origin", !production || APP_BASE.protocol === "https:");
    add("csrf_secret", !production || CSRF_SIGNING_SECRET.length >= 32);
    add("token_encryption", !production || Boolean(TOKEN_ENCRYPTION_KEY));
    add("mfa_recovery_secret", !production || MFA_RECOVERY_HASH_SALT.length >= 32);
    add("account_elevation_secret", !production || ACCOUNT_ELEVATION_SECRET.length >= 32);
    add("admin_audit_secret", !production || ADMIN_AUDIT_HMAC_SECRET.length >= 32);
    add("webauthn_origin", !production || (PASSKEY_EXPECTED_ORIGINS.length === 1 && PASSKEY_EXPECTED_ORIGINS[0] === APP_CANONICAL_ORIGIN && APP_CANONICAL_ORIGIN.startsWith("https://")));
    add("csp_enforced", CONTENT_SECURITY_POLICY.includes("default-src 'self'") && CONTENT_SECURITY_POLICY.includes("object-src 'none'"));
    add("hsts_enabled", !production || true);
    add("widget_conflict_guard", true);

    const bridgeConfigured = bridge?.configured === true;
    const bridgeCaps = bridge?.capabilities && typeof bridge.capabilities === "object" && !Array.isArray(bridge.capabilities) ? bridge.capabilities : {};
    const signed = bridgeConfigured && Number(bridge?.protocol || 0) >= 3 && bridgeCaps.signed_requests_v1 === true;
    const replay = signed && bridgeCaps.replay_guard_v1 === true;
    add("launcher_signed_requests", !bridgeConfigured || signed, {required:bridgeConfigured, warning:!bridgeConfigured});
    add("launcher_replay_guard", !bridgeConfigured || replay, {required:bridgeConfigured, warning:!bridgeConfigured});

    const failedRequired = checks.filter(row => row.required && !row.ok);
    const warnings = checks.filter(row => row.warning || (!row.required && !row.ok)).length;
    const passed = checks.filter(row => row.ok).length;
    return {
        ready:failedRequired.length === 0 && (!bridgeConfigured || (signed && replay)),
        blocked:failedRequired.length > 0,
        passed,
        total:checks.length,
        warnings,
        launcher_signed_requests:signed,
        launcher_replay_guard:replay,
        widget_conflict_guard:true,
        detail:failedRequired.length
            ? `${failedRequired.length} sicherheitsrelevante Prüfung(en) benötigen Aufmerksamkeit.`
            : (bridgeConfigured && signed && replay ? "Sicherheitsgrundstufe aktiv; Launcher-Anfragen werden signiert und gegen Replay geschützt." : "Server-Sicherheitsgrundstufe aktiv; Launcher-Signierung wird nach dem nächsten aktuellen Launcher-Heartbeat aktiv."),
        checks
    };
}


function creatorReleaseReadinessSnapshot({ database = {}, bridge = {}, security = {} } = {}) {
    const checks = [];
    const add = (key, ok, detail, { required = true } = {}) => checks.push({
        key,
        ok:ok === true,
        required,
        detail:String(detail || "").slice(0, 220)
    });

    const caps = bridge?.capabilities && typeof bridge.capabilities === "object" && !Array.isArray(bridge.capabilities)
        ? bridge.capabilities
        : {};
    const protocol = Number(bridge?.protocol || 0);
    const bridgeConfigured = bridge?.configured === true;
    const signed = bridgeConfigured && protocol >= 3 && caps.signed_requests_v1 === true;
    const replay = signed && caps.replay_guard_v1 === true;

    add("database_reachable", database?.ok === true, database?.ok === true ? "Datenbank erreichbar." : "Datenbank ist nicht erreichbar.");
    add("security_baseline", security?.ready === true, security?.detail || "Security Baseline ist noch nicht vollständig bereit.");
    add("widget_conflict_guard", security?.widget_conflict_guard !== false, "Widget Studio schützt Entwürfe/Publishes vor stillen Versionsüberschreibungen.");
    add("launcher_connected", bridgeConfigured, bridgeConfigured ? "Launcher ist mit dem Creator-Konto gekoppelt." : "Für die Release-Abnahme muss mindestens ein Launcher gekoppelt sein.");
    add("launcher_protocol_v3", bridgeConfigured && protocol >= 3, bridgeConfigured ? `Bridge-Protokoll ${protocol || 0}; erforderlich ist mindestens 3.` : "Launcher noch nicht gekoppelt.");
    add("launcher_signed_requests", signed, signed ? "Mutierende Launcher-Anfragen sind signiert." : "Signierte Launcher-Anfragen sind noch nicht nachgewiesen.");
    add("launcher_replay_guard", replay, replay ? "Replay-Schutz ist aktiv." : "Replay-Schutz ist noch nicht nachgewiesen.");

    const failed = checks.filter(row => row.required && !row.ok);
    const passed = checks.filter(row => row.ok).length;
    const externalGates = [
        {key:"external_penetration_test",status:"open",label:"Unabhängiger Penetrationstest"},
        {key:"dependency_advisory_audit",status:"open",label:"Online Dependency-/Supply-Chain-Audit"},
        {key:"windows_signed_installer",status:"open",label:"Signierter Windows-Installer + Update-Abnahme"},
        {key:"production_restore_drill",status:"open",label:"Produktiver Backup-/Restore-Drill"},
        {key:"multi_creator_soak",status:"open",label:"Mehraccount-/Reconnect-/Soak-Test"}
    ];

    return {
        local_ready:failed.length === 0,
        production_ready:false,
        state:failed.length === 0 ? "local_ready" : "blocked",
        passed,
        total:checks.length,
        blocking_internal:failed.length,
        external_acceptance:"open",
        detail:failed.length
            ? `${failed.length} interne Release-Prüfung(en) blockieren die lokale Freigabe.`
            : "Interne Release-Basis erfüllt. Externe Release-Gates bleiben vor Production verpflichtend offen.",
        checks,
        external_gates:externalGates
    };
}

function creatorSuiteCoreReadinessSnapshot({ bridge = {}, streamConfig = null } = {}) {
    const caps = bridge?.capabilities && typeof bridge.capabilities === "object" && !Array.isArray(bridge.capabilities) ? bridge.capabilities : {};
    const integration = caps.integration_health && typeof caps.integration_health === "object" && !Array.isArray(caps.integration_health) ? caps.integration_health : {};
    const checks = [];
    const add = (key, ok, state, detail) => checks.push({key,ok:ok===true,state,detail:String(detail||"").slice(0,240)});
    const bridgeOnline = bridge?.online === true || bridge?.reachable === true || bridge?.connection_state === "online";
    add("launcher_bridge", bridge?.configured === true && bridgeOnline, bridgeOnline ? "ready" : (bridge?.configured ? "degraded" : "setup_required"), bridgeOnline ? "Launcher ist mit dem Creator-Konto verbunden und erreichbar." : "Launcher muss gekoppelt und online sein.");
    add("bridge_security", Number(bridge?.protocol||0) >= 3 && caps.signed_requests_v1 === true && caps.replay_guard_v1 === true, "required", "Bridge-Protokoll v3, Signaturen und Replay-Schutz sind für den Produktionsbetrieb Pflicht.");
    add("widget_studio", true, "ready", "Widget Studio nutzt serverseitige Creator-Isolation, Sanitizing und Versionskonfliktschutz.");
    add("stream_studio_contract", Number(caps.stream_studio_protocol||0) >= 6, Number(caps.stream_studio_protocol||0) >= 6 ? "ready" : "update_required", `Launcher Stream-Studio-Protokoll ${Number(caps.stream_studio_protocol||0) || 0}; benötigt wird 6.`);
    add("stream_engine", caps.stream_engine_v1 === true, caps.stream_engine_v1 === true ? "ready" : "update_required", "Lokale Capture-/Encoding-Engine muss vom Launcher gemeldet werden.");
    add("local_credentials", caps.local_stream_credentials_v1 === true && integration?.stream_credentials?.encryption_available === true, integration?.stream_credentials?.encryption_available === true ? "ready" : "blocked", "Stream-Keys bleiben ausschließlich lokal und müssen über den Betriebssystem-Secret-Speicher verschlüsselt sein.");
    add("multistream", caps.multistream_local_v1 === true, caps.multistream_local_v1 === true ? "foundation_ready" : "update_required", "Multistream läuft lokal im Launcher; ein fehlerhaftes Ziel darf andere Ziele nicht mitreißen.");
    const obsIntegration = integration?.obs && typeof integration.obs === "object" ? integration.obs : {};
    const obsFoundation = caps.obs_browser_source_doctor_v1 === true && obsIntegration.websocket_available === true;
    add("obs", obsFoundation, obsIntegration.websocket_connected === true ? "connected" : (obsFoundation ? "acceptance_open" : "update_required"), obsIntegration.websocket_connected === true ? `OBS WebSocket ist verbunden${obsIntegration.current_scene ? ` · Szene: ${String(obsIntegration.current_scene).slice(0,100)}` : ""}.` : (obsFoundation ? "OBS WebSocket ist code-seitig verfügbar; die reale OBS-/Windows-Abnahme bleibt offen." : "Launcher-Update für OBS WebSocket erforderlich."));
    add("live_provider", caps.live_provider_health_v1 === true, caps.live_provider_health_v1 === true ? "foundation_ready" : "update_required", `LIVE Provider: ${String(integration?.live_provider?.key||"unbekannt")} · ${String(integration?.live_provider?.status||"unknown")}.`);
    add("interactive_games", caps.interactive_games_v1 === true, caps.interactive_games_v1 === true ? "ready" : "update_required", "Interactive Games werden vom Launcher als eigener Runtime-Baustein gemeldet.");
    const failed = checks.filter(row=>!row.ok && ["required","blocked","update_required","setup_required"].includes(row.state));
    return {
        ready:failed.length===0,
        state:failed.length===0?"core_ready":"attention",
        passed:checks.filter(row=>row.ok).length,
        total:checks.length,
        blocking:failed.length,
        checks,
        roadmap:{
            current:["widget_studio","launcher_bridge","stream_engine","interactive_games"],
            next:["multistream_destinations","creator_suite_feature_freeze"],
            later:["provider_acceptance","production_soak"]
        },
        policy:{
            stream_credentials:"launcher_local_encrypted",
            cloud_stream_keys:false,
            multistream_failure_policy:"isolate_destination",
            stream_studio_protocol:6
        },
        config_present:Boolean(streamConfig)
    };
}


async function getCreatorTechnicalStatusSnapshot(creatorId) {
    const dbStarted = Date.now();
    let database = {ok:false,latency_ms:null,detail:"Datenbankprüfung fehlgeschlagen."};
    try {
        await pool.query("SELECT 1");
        database = {ok:true,latency_ms:Date.now()-dbStarted,detail:"Datenbank erreichbar."};
    } catch (error) {
        safeLogError("creator-technical-database", error);
    }

    const [connectionResult, bridgeResult, evidenceResult, gameResult, publicStateResult, incidentResult] = await Promise.allSettled([
        pool.query(
            `SELECT connected,scope,display_name,follower_count,updated_at
             FROM tiktok_connections
             WHERE creator_id=$1
             LIMIT 1`,
            [normalizeCreatorId(creatorId)]
        ),
        getStudioBridgeStatus(creatorId),
        getPublicLiveEvidence(creatorId),
        getPublicRecentGames(creatorId,{limit:3}),
        getPublicCreatorStateSnapshot(),
        getWebsiteIncidentState()
    ]);

    const connection = connectionResult.status === "fulfilled" ? (connectionResult.value?.rows?.[0] || null) : null;
    const bridge = bridgeResult.status === "fulfilled" ? bridgeResult.value : {configured:false,online:false,client_version:"",machine_name:"",last_seen_at:null,capabilities:{}};
    const evidence = evidenceResult.status === "fulfilled" ? evidenceResult.value : {status:"unknown",source:"error",live:emptyStudioLiveState(),latest_event_at:null};
    const activity = gameResult.status === "fulfilled" ? gameResult.value : {available:false,active:null,recent:[]};
    const publicState = publicStateResult.status === "fulfilled" ? publicStateResult.value : null;
    const incident = incidentResult.status === "fulfilled" ? incidentResult.value : {mode:"unknown"};

    if (connectionResult.status === "rejected") safeLogError("creator-technical-tiktok", connectionResult.reason);
    if (bridgeResult.status === "rejected") safeLogError("creator-technical-launcher", bridgeResult.reason);
    if (evidenceResult.status === "rejected") safeLogError("creator-technical-live", evidenceResult.reason);
    if (gameResult.status === "rejected") safeLogError("creator-technical-game", gameResult.reason);
    if (publicStateResult.status === "rejected") safeLogError("creator-technical-public-state", publicStateResult.reason);

    const scopes = String(connection?.scope || "")
        .split(/[\s,]+/)
        .map(value=>value.trim())
        .filter(Boolean);
    const gameContext = creatorGameContextFromActivity(activity);
    const publicGame = publicState?.game || {};
    const publicDiscord = publicState?.social?.discord || {};
    const playstationConfigured = PUBLIC_PLAYSTATION_ENABLED && Boolean(PUBLIC_PLAYSTATION_NPSSO);
    const playstationAvailable = publicGame.source === "playstation_network" && Array.isArray(publicGame.recent) && publicGame.recent.length > 0;
    const securitySnapshot = creatorSecurityReadinessSnapshot(bridge);
    const suiteSnapshot = creatorSuiteCoreReadinessSnapshot({bridge,streamConfig:null});
    const releaseSnapshot = creatorReleaseReadinessSnapshot({database, bridge, security:securitySnapshot});

    return buildCreatorTechnicalState({
        generatedAt:new Date().toISOString(),
        website:{
            ok:incident?.mode === "normal",
            status:incident?.mode === "normal" ? "online" : String(incident?.mode || "unknown"),
            detail:incident?.mode === "normal" ? "Website läuft im Normalbetrieb." : `Website-Modus: ${String(incident?.mode || "unknown")}`
        },
        database,
        tiktok:{
            configured:Boolean(connection),
            connected:connection?.connected === true,
            stats_scope:scopes.includes("user.info.stats"),
            display_name:connection?.display_name || "",
            followers:Number.isFinite(Number(connection?.follower_count)) ? Number(connection.follower_count) : null,
            updated_at:connection?.updated_at || null,
            stale:false,
            detail:connection?.connected === true
                ? (scopes.includes("user.info.stats") ? "TikTok verbunden, Statistik-Scope vorhanden." : "TikTok verbunden, Statistik-Scope fehlt.")
                : "TikTok ist für diesen Creator nicht verbunden."
        },
        launcher:{
            configured:bridge?.configured === true,
            online:bridge?.online === true,
            reachable:bridge?.reachable === true,
            connection_state:bridge?.connection_state || "offline",
            client_version:bridge?.client_version || "",
            machine_name:bridge?.machine_name || "",
            last_seen_at:bridge?.last_seen_at || null,
            heartbeat_age_seconds:Number.isFinite(Number(bridge?.heartbeat_age_seconds)) ? Number(bridge.heartbeat_age_seconds) : null,
            heartbeat_after_ms:Number(bridge?.heartbeat_after_ms || WIDGET_BRIDGE_HEARTBEAT_AFTER_MS),
            heartbeat_grace_ms:Number(bridge?.heartbeat_grace_ms || WIDGET_BRIDGE_HEARTBEAT_GRACE_MS),
            protocol:Number(bridge?.protocol || 1),
            detail:bridge?.connection_state === "online"
                ? "Launcher-Bridge ist stabil online."
                : (bridge?.connection_state === "degraded"
                    ? "Launcher-Heartbeat ist verspätet; Verbindung bleibt innerhalb der Grace-Periode erhalten."
                    : (bridge?.configured ? "Launcher konfiguriert, aktuell aber nicht erreichbar." : "Noch kein Launcher verbunden."))
        },
        live:{
            active:evidence?.status === "live",
            status:evidence?.status || "unknown",
            source:evidence?.source || "none",
            viewers:Number(evidence?.live?.viewers || 0),
            last_event_at:evidence?.latest_event_at || evidence?.live?.last_event_at || null,
            detail:evidence?.status === "live" ? `LIVE-Signal aktiv (${evidence?.source || "unbekannt"}).` : (evidence?.status === "offline" ? "LIVE-Ende wurde bestätigt." : "LIVE-Status ist aktuell nicht eindeutig.")
        },
        game:{
            active:gameContext?.mode === "active",
            available:gameContext?.mode !== "none",
            name:gameContext?.game_name || "",
            platform:gameContext?.platform || "unknown",
            source:gameContext?.source || "",
            updated_at:gameContext?.observed_at || gameContext?.last_played_at || null,
            detail:gameContext?.mode === "active" ? "Aktive Game-Präsenz vom Creator-System erkannt." : (gameContext?.mode === "recent" ? "Keine aktive Präsenz; letzter Titel ist verfügbar." : "Noch keine Game-Präsenz erkannt.")
        },
        playstation:{
            configured:playstationConfigured,
            available:playstationAvailable,
            recent_count:Array.isArray(publicGame.recent) ? publicGame.recent.length : 0,
            updated_at:publicGame.updated_at || null,
            stale:false,
            detail:playstationAvailable ? "PlayStation-Network-Daten werden öffentlich geladen." : (playstationConfigured ? "PlayStation ist konfiguriert, liefert aktuell aber keine bestätigten Daten." : "PlayStation ist nicht konfiguriert.")
        },
        discord:{
            available:publicDiscord.available === true,
            members:publicDiscord.members,
            online:publicDiscord.online,
            updated_at:publicDiscord.updated_at || null,
            stale:publicDiscord.stale === true,
            detail:publicDiscord.available === true ? "Discord-Invite liefert Mitglieder- und Onlinezahlen." : "Discord-Zahlen sind aktuell nicht verfügbar."
        },
        security:securitySnapshot,
        suite:suiteSnapshot,
        release:releaseSnapshot
    });
}

async function refreshPublicCommunityStats() {
    const previous = publicCommunityStatsCache.payload;
    const [discordResult, tiktokResult, gamesResult] = await Promise.allSettled([
        fetchPublicDiscordCommunityStats(),
        fetchPublicTikTokCommunityStats(),
        getPreferredPublicRecentGames(DEFAULT_CREATOR_ID)
    ]);

    let discord;
    if (discordResult.status === "fulfilled") {
        discord = discordResult.value;
    } else {
        safeLogError("public-community-discord-refresh", discordResult.reason);
        discord = previous?.discord?.available
            ? { ...previous.discord, stale:true }
            : { available:false, members:null, online:null, stale:false, updated_at:null };
    }

    let tiktok;
    if (tiktokResult.status === "fulfilled") {
        tiktok = tiktokResult.value;
    } else {
        safeLogError("public-community-tiktok", tiktokResult.reason);
        tiktok = previous?.tiktok?.available
            ? { ...previous.tiktok, stale:true }
            : { available:false, followers:null, stale:false, updated_at:null };
    }

    let recentGames;
    if (gamesResult.status === "fulfilled") {
        recentGames = gamesResult.value;
    } else {
        safeLogError("public-community-games", gamesResult.reason);
        recentGames = previous?.recent_games?.available
            ? { ...previous.recent_games, stale:true }
            : { available:false, window_days:PUBLIC_PLAYSTATION_ENABLED?null:PUBLIC_GAME_ACTIVITY_WINDOW_DAYS, source:PUBLIC_PLAYSTATION_ENABLED?"playstation_network":"cfs_launcher_opt_in", playtime_scope:PUBLIC_PLAYSTATION_ENABLED?"lifetime":"rolling_window", updated_at:null, games:[], recent:[] };
    }

    const payload = {
        ok:Boolean(discord.available || tiktok.available || recentGames.available),
        generated_at:new Date().toISOString(),
        refresh_seconds:Math.round(PUBLIC_COMMUNITY_STATS_CACHE_TTL_MS / 1000),
        discord:{
            ...discord,
            url:PUBLIC_DISCORD_INVITE_URL
        },
        tiktok:{
            ...tiktok,
            url:PUBLIC_TIKTOK_PROFILE_URL
        },
        recent_games:recentGames
    };

    publicCommunityStatsCache.payload = payload;
    publicCommunityStatsCache.expires_at = Date.now() + PUBLIC_COMMUNITY_STATS_CACHE_TTL_MS;
    return payload;
}

async function getPublicCommunityStats() {
    if (publicCommunityStatsCache.payload && Date.now() < publicCommunityStatsCache.expires_at) {
        return publicCommunityStatsCache.payload;
    }
    if (!publicCommunityStatsCache.in_flight) {
        publicCommunityStatsCache.in_flight = refreshPublicCommunityStats()
            .finally(() => { publicCommunityStatsCache.in_flight = null; });
    }
    return publicCommunityStatsCache.in_flight;
}

