app.get(
    "/api/launcher/tiktok/profile",

    requireLauncherKey,

    async (
        req,
        res
    ) => {

        res.set(
            "Cache-Control",
            "no-store"
        );


        let creatorId =
            DEFAULT_CREATOR_ID;


        try {

            creatorId =
                creatorIdFromRequest(
                    req
                );


            const connection =
                await getConnection(
                    creatorId
                );


            if (
                !connection?.connected
            ) {

                return res
                    .status(401)
                    .json({

                        ok:
                            false,

                        connected:
                            false,

                        creator_id:
                            creatorId,

                        error:
                            "TikTok ist nicht verbunden."

                    });

            }


            if (
                !connection?.refresh_token
            ) {

                return res
                    .status(401)
                    .json({

                        ok:
                            false,

                        connected:
                            false,

                        creator_id:
                            creatorId,

                        error:
                            "TikTok Refresh Token fehlt."

                    });

            }


            const profile =
                await fetchTikTokProfile(
                    creatorId
                );


            return res.json({

                ok:
                    true,

                connected:
                    true,

                creator_id:
                    creatorId,

                profile

            });

        }
        catch (error) {

            const diagnostic =
                getSafeDiagnostic(
                    error,
                    "launcher_profile"
                );


            console.error(
                "[CFS TikTok] Launcher-Profil fehlgeschlagen:",
                diagnostic
            );


            return res
                .status(502)
                .json({

                    ok:
                        false,

                    connected:
                        false,

                    creator_id:
                        creatorId,

                    error:
                        diagnosticMessage(
                            diagnostic
                        ),

                    diagnostic

                });

        }

    }
);


