// ============================================================
// TIKTOK OAUTH START
// ============================================================

async function beginTikTokOAuth(
    res,
    creatorId = DEFAULT_CREATOR_ID
) {

    creatorId =
        normalizeCreatorId(
            creatorId
        );


    const state =
        crypto
            .randomBytes(
                32
            )
            .toString(
                "hex"
            );


    const stateHash =
        hashValue(
            state
        );


    await cleanupExpiredOAuthStates();


    await pool.query(
        `
        INSERT INTO tiktok_oauth_states (
            state_hash,
            creator_id,
            expires_at
        )

        VALUES (
            $1,
            $2,
            NOW() + INTERVAL '10 minutes'
        )
        `,
        [
            stateHash,
            creatorId
        ]
    );


    res.cookie(
        TIKTOK_STATE_COOKIE,
        state,
        {

            httpOnly:
                true,

            secure:
                NODE_ENV !==
                "development",

            sameSite:
                "lax",

            priority:
                "high",

            maxAge:
                OAUTH_TTL_MS,

            path:
                "/auth/tiktok"

        }
    );


    const params =
        new URLSearchParams({

            client_key:
                CLIENT_KEY,

            response_type:
                "code",

            scope:
                REQUESTED_SCOPES.join(
                    ","
                ),

            redirect_uri:
                REDIRECT_URI,

            state

        });


    return res.redirect(
        `${TIKTOK_AUTHORIZE_URL}?${params.toString()}`
    );

}


