// ============================================================
// TIKTOK CALLBACK
// ============================================================

app.get(
    "/auth/tiktok/callback",
    async (
        req,
        res
    ) => {

        res.set(
            "Cache-Control",
            "no-store"
        );


        try {

            const {
                code,
                state,
                error,
                error_description:
                    errorDescription
            } =
                req.query;


            if (
                error
            ) {

                return res
                    .status(400)
                    .send(
                        renderPage(
                            "TikTok Verbindung",
                            `
                            <p>
                                TikTok Verbindung wurde
                                nicht abgeschlossen.
                            </p>

                            <p class="muted">
                                ${escapeHtml(
                                    errorDescription ||
                                    error
                                )}
                            </p>
                            `
                        )
                    );

            }


            if (
                !code
            ) {

                return res
                    .status(400)
                    .send(
                        renderPage(
                            "TikTok Verbindung",
                            `
                            <p>
                                Kein Autorisierungscode
                                von TikTok erhalten.
                            </p>
                            `
                        )
                    );

            }


            const cookies =
                parseCookies(
                    req
                );


            const cookieState =
                cookies[
                    TIKTOK_STATE_COOKIE
                ];


            if (
                !state ||
                !cookieState ||
                !safeEqualText(
                    state,
                    cookieState
                )
            ) {

                return res
                    .status(400)
                    .send(
                        renderPage(
                            "Sicherheitsprüfung",
                            `
                            <p>
                                OAuth Sicherheitsprüfung
                                fehlgeschlagen.
                            </p>
                            `
                        )
                    );

            }


            const stateHash =
                hashValue(
                    state
                );


            const stateResult =
                await pool.query(
                    `
                    DELETE FROM tiktok_oauth_states

                    WHERE
                        state_hash = $1

                    AND
                        expires_at >= NOW()

                    RETURNING
                        creator_id
                    `,
                    [
                        stateHash
                    ]
                );


            if (
                !stateResult.rowCount
            ) {

                return res
                    .status(400)
                    .send(
                        renderPage(
                            "Sicherheitsprüfung",
                            `
                            <p>
                                Login ist abgelaufen
                                oder wurde bereits verwendet.
                            </p>
                            `
                        )
                    );

            }


            const creatorId =
                normalizeCreatorId(
                    stateResult
                        .rows[0]
                        .creator_id
                );

            // Der OAuth-State allein reicht nicht: Wird die Beta zwischen Start und
            // Callback pausiert, darf der Provider nicht mehr verknüpft werden.
            await requireProviderBetaAccess(creatorId,"tiktok");

            const tokenData =
                await exchangeAuthorizationCode(
                    code
                );


            await saveTokens(
                creatorId,
                tokenData
            );


            const profile =
                await fetchTikTokProfile(
                    creatorId
                );


            res.clearCookie(
                TIKTOK_STATE_COOKIE,
                {
                    httpOnly:true,
                    secure:NODE_ENV !== "development",
                    sameSite:"lax",
                    priority:"high",
                    path:"/auth/tiktok"
                }
            );


            return res.send(
                renderPage(
                    "TikTok erfolgreich verbunden",
                    `

                    <div class="success">
                        ✓ TikTok erfolgreich verbunden
                    </div>

                    ${
                        profile.avatar_url
                            ? `
                                <img
                                    class="avatar"
                                    src="${escapeHtml(
                                        profile.avatar_url
                                    )}"
                                    alt="TikTok Profilbild"
                                >
                              `
                            : ""
                    }

                    <h2>
                        ${escapeHtml(
                            profile.display_name ||
                            "TikTok Creator"
                        )}
                    </h2>

                    <div class="stats">

                        <div>
                            <span>
                                Follower
                            </span>

                            <strong>
                                ${formatNumber(
                                    profile.follower_count
                                )}
                            </strong>
                        </div>

                        <div>
                            <span>
                                Gefolgt
                            </span>

                            <strong>
                                ${formatNumber(
                                    profile.following_count
                                )}
                            </strong>
                        </div>

                        <div>
                            <span>
                                Likes
                            </span>

                            <strong>
                                ${formatNumber(
                                    profile.likes_count
                                )}
                            </strong>
                        </div>

                        <div>
                            <span>
                                Videos
                            </span>

                            <strong>
                                ${formatNumber(
                                    profile.video_count
                                )}
                            </strong>
                        </div>

                    </div>

                    <p>
                        <a
                            class="button"
                            href="/pages/tiktok.html"
                        >
                            Zum TikTok Hub
                        </a>
                    </p>

                    `
                )
            );

        }
        catch (error) {

            if(error?.code==="provider_beta_required"){
                return res.status(403).send(renderPage("TikTok Beta",`<p class="error">${escapeHtml(error.message)}</p><p class="muted">Die Verbindung wurde nicht gespeichert. Sobald der Admin die Beta freigibt, kannst du TikTok erneut verbinden.</p>`));
            }

            const diagnostic =
                getSafeDiagnostic(
                    error,
                    "oauth_callback"
                );


            console.error(
                "TikTok Callback Error:",
                diagnostic
            );


            return res
                .status(500)
                .send(
                    renderPage(
                        "TikTok Verbindung",
                        `

                        <p class="error">
                            Beim Verbinden mit TikTok
                            ist ein Fehler aufgetreten.
                        </p>

                        <p class="muted">
                            ${escapeHtml(
                                diagnosticMessage(
                                    diagnostic
                                )
                            )}
                        </p>

                        `
                    )
                );

        }

    }
);


// ============================================================
// TIKTOK TOKEN EXCHANGE
// ============================================================

async function exchangeAuthorizationCode(
    code
) {

    const body =
        new URLSearchParams({

            client_key:
                CLIENT_KEY,

            client_secret:
                CLIENT_SECRET,

            code:
                String(
                    code
                ),

            grant_type:
                "authorization_code",

            redirect_uri:
                REDIRECT_URI

        });


    const response =
        await fetchTikTok(
            TIKTOK_TOKEN_URL,
            {

                method:
                    "POST",

                headers: {

                    "Content-Type":
                        "application/x-www-form-urlencoded",

                    "Cache-Control":
                        "no-cache"

                },

                body

            }
        );


    const data =
        await safeJson(
            response
        );


    if (
        !response.ok ||
        !data?.access_token ||
        !data?.refresh_token
    ) {

        throw createTikTokApiError(
            "token_exchange",
            response,
            data,
            "TikTok Token Exchange fehlgeschlagen."
        );

    }


    return data;

}


// ============================================================
// ACCESS TOKEN PRÜFEN
// ============================================================

async function ensureFreshAccessToken(
    creatorId
) {

    const connection =
        await getConnection(
            creatorId
        );


    if (
        !connection?.connected
    ) {

        throw new Error(
            "Keine TikTok-Verbindung."
        );

    }


    const expiresAt =
        Number(
            connection
                .access_expires_at ||
            0
        );


    if (
        connection.access_token &&
        expiresAt &&
        Date.now() <
            expiresAt -
            ACCESS_TOKEN_SAFETY_WINDOW_MS
    ) {

        return true;

    }


    await refreshAccessToken(
        creatorId
    );


    return true;

}


// ============================================================
// TOKEN REFRESH
// ============================================================

async function refreshAccessToken(
    creatorId
) {

    const connection =
        await getConnection(
            creatorId
        );


    if (
        !connection?.refresh_token
    ) {

        throw new Error(
            "Kein Refresh Token vorhanden."
        );

    }


    const body =
        new URLSearchParams({

            client_key:
                CLIENT_KEY,

            client_secret:
                CLIENT_SECRET,

            grant_type:
                "refresh_token",

            refresh_token:
                connection
                    .refresh_token

        });


    const response =
        await fetchTikTok(
            TIKTOK_TOKEN_URL,
            {

                method:
                    "POST",

                headers: {

                    "Content-Type":
                        "application/x-www-form-urlencoded",

                    "Cache-Control":
                        "no-cache"

                },

                body

            }
        );


    const data =
        await safeJson(
            response
        );


    if (
        !response.ok ||
        !data?.access_token
    ) {

        throw createTikTokApiError(
            "token_refresh",
            response,
            data,
            "TikTok Token Refresh fehlgeschlagen."
        );

    }


    await saveTokens(
        creatorId,
        {

            ...data,

            refresh_token:
                data.refresh_token ||
                connection.refresh_token

        }
    );

}


// ============================================================
// TIKTOK PROFIL LADEN
// ============================================================

async function fetchTikTokProfile(
    creatorId
) {

    await ensureFreshAccessToken(
        creatorId
    );


    const connection =
        await getConnection(
            creatorId
        );


    if (
        !connection?.access_token
    ) {

        throw new Error(
            "Kein TikTok Access Token vorhanden."
        );

    }


    const fields = [

        "open_id",
        "avatar_url",
        "display_name",
        "follower_count",
        "following_count",
        "likes_count",
        "video_count"

    ].join(",");


    const url =
        TIKTOK_USER_INFO_URL +
        "?fields=" +
        encodeURIComponent(
            fields
        );


    const response =
        await fetchTikTok(
            url,
            {

                method:
                    "GET",

                headers: {

                    Authorization:
                        `Bearer ${connection.access_token}`,

                    "Cache-Control":
                        "no-cache"

                }

            }
        );


    const data =
        await safeJson(
            response
        );


    if (
        !response.ok ||
        !data?.data?.user
    ) {

        throw createTikTokApiError(
            "user_info",
            response,
            data,
            "TikTok User Info fehlgeschlagen."
        );

    }


    const user =
        data.data.user;


    const profile = {

        open_id:
            user.open_id ||
            connection.open_id ||
            "",

        display_name:
            user.display_name ||
            "",

        avatar_url:
            user.avatar_url ||
            "",

        follower_count:
            Number(
                user.follower_count ||
                0
            ),

        following_count:
            Number(
                user.following_count ||
                0
            ),

        likes_count:
            Number(
                user.likes_count ||
                0
            ),

        video_count:
            Number(
                user.video_count ||
                0
            ),

        updated_at:
            new Date()
                .toISOString()

    };


    await saveProfile(
        creatorId,
        profile
    );


    return profile;

}
