app.post(
    "/auth/tiktok/disconnect",

    requireLauncherKey,

    async (
        req,
        res
    ) => {

        res.set(
            "Cache-Control",
            "no-store"
        );

        try {

            const creatorId =
                creatorIdFromRequest(
                    req
                );


            const connection =
                await getConnection(
                    creatorId
                );


            if (
                connection?.access_token
            ) {

                const body =
                    new URLSearchParams({

                        client_key:
                            CLIENT_KEY,

                        client_secret:
                            CLIENT_SECRET,

                        token:
                            connection.access_token

                    });


                const revokeResponse =
                    await fetchTikTok(
                        TIKTOK_REVOKE_URL,
                        {

                            method:
                                "POST",

                            headers: {

                                "Content-Type":
                                    "application/x-www-form-urlencoded"

                            },

                            body

                        }
                    );


                if (
                    !revokeResponse.ok
                ) {

                    const revokeData =
                        await safeJson(
                            revokeResponse
                        );


                    console.warn(
                        "TikTok Revoke:",
                        sanitizeTikTokError(
                            revokeData
                        )
                    );

                }

            }


            await pool.query(
                `
                DELETE FROM tiktok_connections
                WHERE creator_id = $1
                `,
                [
                    creatorId
                ]
            );


            return res.json({

                ok:
                    true,

                connected:
                    false,

                creator_id:
                    creatorId

            });

        }
        catch (error) {

            safeLogError("Disconnect Error:",error);


            return res
                .status(500)
                .json({

                    ok:
                        false,

                    error:
                        "TikTok-Verbindung konnte nicht getrennt werden."

                });

        }

    }
);


// ============================================================
// TIKTOK FETCH MIT TIMEOUT
// ============================================================

async function fetchTikTok(
    url,
    options = {}
) {

    const target = assertOutboundHttpsUrl(url,{allowedHosts:["open.tiktokapis.com"],label:"TikTok API URL"});
    const controller =
        new AbortController();


    const timeout =
        setTimeout(
            () => {

                controller.abort();

            },
            TIKTOK_TIMEOUT_MS
        );


    try {

        return await fetch(
            target.href,
            {

                ...options,

                // TikTok API-Aufrufe dürfen nicht still zu einem anderen Host
                // weitergeleitet werden. Das verhindert Redirect-Leaks von Tokens.
                redirect:
                    "error",

                signal:
                    controller.signal

            }
        );

    }
    catch (error) {

        if (
            error?.name ===
            "AbortError"
        ) {

            const timeoutError =
                new Error(
                    "TikTok Anfrage hat das Zeitlimit überschritten."
                );


            timeoutError.tiktokDiagnostic = {

                stage:
                    "network_timeout",

                http_status:
                    null,

                code:
                    "timeout",

                description:
                    "TikTok API antwortete nicht innerhalb von 15 Sekunden.",

                log_id:
                    ""

            };


            throw timeoutError;

        }


        throw error;

    }
    finally {

        clearTimeout(
            timeout
        );

    }

}


// ============================================================
// JSON SICHER LESEN
// ============================================================

async function safeJson(
    response
) {

    const text =
        await readResponseTextBounded(response,1024*1024);


    if (
        !text
    ) {

        return {};

    }


    try {

        return JSON.parse(
            text
        );

    }
    catch {

        return {

            raw_response:
                text.slice(
                    0,
                    500
                )

        };

    }

}


// ============================================================
// TIKTOK FEHLER SÄUBERN
// ============================================================

function sanitizeTikTokError(
    data
) {

    if (
        !data ||
        typeof data !==
            "object"
    ) {

        return {};

    }


    const nested =
        data.error &&
        typeof data.error ===
            "object"
            ? data.error
            : {};


    const code =

        nested.code ??

        data.code ??

        data.error_code ??

        (
            typeof data.error ===
            "string"
                ? data.error
                : ""
        );


    const description =

        nested.message ??

        data.error_description ??

        data.message ??

        "";


    const logId =

        nested.log_id ??

        data.log_id ??

        "";


    return {

        code:
            cleanDiagnosticText(
                code,
                120
            ),

        description:
            cleanDiagnosticText(
                description,
                300
            ),

        log_id:
            cleanDiagnosticText(
                logId,
                160
            )

    };

}


// ============================================================
// TIKTOK API ERROR
// ============================================================

function createTikTokApiError(
    stage,
    response,
    data,
    fallbackMessage
) {

    const safe =
        sanitizeTikTokError(
            data
        );


    const diagnostic = {

        stage:
            cleanDiagnosticText(
                stage,
                80
            ),

        http_status:
            response &&
            Number.isFinite(
                Number(
                    response.status
                )
            )
                ? Number(
                    response.status
                )
                : null,

        code:
            safe.code ||
            "",

        description:
            safe.description ||
            "",

        log_id:
            safe.log_id ||
            ""

    };


    console.error(
        `[CFS TikTok] ${stage} fehlgeschlagen:`,
        diagnostic
    );


    const error =
        new Error(
            fallbackMessage ||
            "TikTok API Fehler."
        );


    error.tiktokDiagnostic =
        diagnostic;


    return error;

}


// ============================================================
// DIAGNOSE
// ============================================================

function getSafeDiagnostic(
    error,
    fallbackStage =
        "unknown"
) {

    if (
        error?.tiktokDiagnostic &&
        typeof error.tiktokDiagnostic ===
            "object"
    ) {

        const source =
            error.tiktokDiagnostic;


        return {

            stage:
                cleanDiagnosticText(
                    source.stage ||
                    fallbackStage,
                    80
                ),

            http_status:
                Number.isFinite(
                    Number(
                        source.http_status
                    )
                )
                    ? Number(
                        source.http_status
                    )
                    : null,

            code:
                cleanDiagnosticText(
                    source.code ||
                    "",
                    120
                ),

            description:
                cleanDiagnosticText(
                    source.description ||
                    "",
                    300
                ),

            log_id:
                cleanDiagnosticText(
                    source.log_id ||
                    "",
                    160
                )

        };

    }


    return {

        stage:
            cleanDiagnosticText(
                fallbackStage,
                80
            ),

        http_status:
            null,

        code:
            "",

        description:
            cleanDiagnosticText(
                error?.message ||
                "Unbekannter Fehler",
                300
            ),

        log_id:
            ""

    };

}


// ============================================================
// DIAGNOSE TEXT
// ============================================================

function diagnosticMessage(
    diagnostic
) {

    const parts = [
        "TikTok Profildaten konnten nicht aktualisiert werden."
    ];


    if (
        diagnostic?.stage
    ) {

        parts.push(
            `Stufe: ${diagnostic.stage}`
        );

    }


    if (
        diagnostic?.http_status
    ) {

        parts.push(
            `TikTok HTTP ${diagnostic.http_status}`
        );

    }


    if (
        diagnostic?.code
    ) {

        parts.push(
            `Code: ${diagnostic.code}`
        );

    }


    if (
        diagnostic?.description
    ) {

        parts.push(
            `Meldung: ${diagnostic.description}`
        );

    }


    if (
        diagnostic?.log_id
    ) {

        parts.push(
            `Log-ID: ${diagnostic.log_id}`
        );

    }


    return parts.join(
        " | "
    );

}


// ============================================================
// DIAGNOSE TEXT BEREINIGEN
// ============================================================

function cleanDiagnosticText(
    value,
    maxLength =
        300
) {

    return redactSensitiveText(
        value ??
        ""
    )
        .replace(
            /[\r\n\t]+/g,
            " "
        )
        .trim()
        .slice(
            0,
            maxLength
        );

}


// ============================================================
// COOKIES
// ============================================================

function parseCookies(
    req
) {

    const result =
        {};


    const header =
        req.headers.cookie ||
        "";


    for (
        const item
        of header.split(";")
    ) {

        const index =
            item.indexOf("=");


        if (
            index ===
            -1
        ) {

            continue;

        }


        const key =
            item
                .slice(
                    0,
                    index
                )
                .trim();


        const value =
            item
                .slice(
                    index + 1
                )
                .trim();


        if (
            !key
        ) {

            continue;

        }


        try {

            result[key] =
                decodeURIComponent(
                    value
                );

        }
        catch {

            result[key] =
                value;

        }

    }


    return result;

}


// ============================================================
// HTML ESCAPE
// ============================================================

function escapeHtml(
    value
) {

    return String(
        value ??
        ""
    )
        .replaceAll(
            "&",
            "&amp;"
        )
        .replaceAll(
            "<",
            "&lt;"
        )
        .replaceAll(
            ">",
            "&gt;"
        )
        .replaceAll(
            '"',
            "&quot;"
        )
        .replaceAll(
            "'",
            "&#039;"
        );

}


// ============================================================
// ZAHL FORMATIEREN
// ============================================================

function formatNumber(
    value
) {

    return new Intl
        .NumberFormat(
            "de-DE"
        )
        .format(
            Number(
                value ||
                0
            )
        );

}


// ============================================================
// PUBLIC ORDNER ERMITTELN
// ============================================================

function resolvePublicDirectory() {

    if (
        process.env.PUBLIC_DIR
    ) {

        return path.resolve(
            __dirname,
            process.env.PUBLIC_DIR
        );

    }


    const candidates = [

        path.join(
            __dirname,
            "public"
        ),

        path.join(
            __dirname,
            "Öffentlich"
        )

    ];


    for (
        const candidate
        of candidates
    ) {

        if (
            fs.existsSync(
                candidate
            )
        ) {

            return candidate;

        }

    }


    return path.join(
        __dirname,
        "public"
    );

}


const PUBLIC_DIR =
    resolvePublicDirectory();


