// ============================================================
// CREATOR PRODUCT HTML ACCESS · v180 BRAND / PUBLIC BOUNDARY
//
// Die öffentliche Website ist cfs_zockt. Produktoberflächen (Creator Suite,
// Dashboard, Shop, Studios, Launcher, Account/Setup und Admin) werden erst
// nach einer gültigen Creator-Session als HTML ausgeliefert. API-Endpunkte
// behalten zusätzlich ihre bestehenden requireCreatorAccount/Admin-Gates.
// ============================================================

const PUBLIC_PAGE_HTML_ALLOWLIST = new Set([
    "/pages/login.html",
    "/pages/forgot-password.html",
    "/pages/reset-password.html",
    "/pages/verify-email.html",
    "/pages/roadmap.html",
    "/pages/support.html",
    "/pages/security.html",
    "/pages/impressum.html",
    "/pages/datenschutz.html",
    "/pages/nutzungsbedingungen.html",
    "/pages/merch.html",
    "/pages/not-found.html",
    "/pages/error.html"
]);

function canonicalHtmlPagePath(pathname) {
    const value = String(pathname || "");
    if (!value.startsWith("/pages/")) return "";
    if (value.endsWith(".html")) return value;
    if (path.posix.extname(value)) return value;
    return `${value}.html`;
}

function safeCreatorReturnTo(req) {
    const raw = String(req.originalUrl || req.url || "");
    if (!raw.startsWith("/pages/") || raw.length > 700 || /[\r\n]/.test(raw)) {
        return "/pages/dashboard.html";
    }
    return raw;
}

app.use(async (req, res, next) => {
    if (!isSafeHttpMethod(req.method)) return next();

    const pagePath = canonicalHtmlPagePath(req.path);
    if (!pagePath || PUBLIC_PAGE_HTML_ALLOWLIST.has(pagePath)) return next();

    const pagesRoot = path.join(PUBLIC_DIR, "pages") + path.sep;
    const candidate = path.resolve(PUBLIC_DIR, pagePath.slice(1));
    if (!candidate.startsWith(pagesRoot) || !fs.existsSync(candidate)) return next();

    res.setHeader("X-Robots-Tag", "noindex, nofollow, noarchive");
    res.setHeader("Cache-Control", "no-store");

    try {
        const account = await getCreatorFromRequest(req);
        if (!account) {
            const returnTo = encodeURIComponent(safeCreatorReturnTo(req));
            return res.redirect(302, `/pages/login.html?returnTo=${returnTo}`);
        }
        req.creatorAccount = account;
        if ((pagePath === "/pages/admin-creators.html" || pagePath === "/pages/cfs-ai.html") && !(await isCreatorSuiteAdmin(account))) {
            return res.status(404).sendFile(path.join(PUBLIC_DIR, "pages", "not-found.html"));
        }
        ensureCreatorCsrfCookie(req, res);
        return next();
    }
    catch (error) {
        safeLogError("Creator HTML Access Fehler:", error);
        return res.status(500).sendFile(path.join(PUBLIC_DIR, "pages", "error.html"));
    }
});


// ============================================================
// SEO URL CANONICALIZATION · WEBSITE SEO PASS
//
// express.static({extensions:["html"]}) kann ansonsten auch
// extensionless Varianten derselben Datei ausliefern. Für die
// indexierbaren öffentlichen Seiten wird deshalb eine einzige
// kanonische URL erzwungen. Query-Strings bleiben erhalten.
// ============================================================

const SEO_CANONICAL_PATHS = new Map([
    ["/index.html", "/"],
    ["/pages/merch", "/pages/merch.html"],
    ["/pages/roadmap", "/pages/roadmap.html"],
    ["/pages/support", "/pages/support.html"],
    ["/pages/security", "/pages/security.html"],
    ["/pages/impressum", "/pages/impressum.html"],
    ["/pages/datenschutz", "/pages/datenschutz.html"],
    ["/pages/nutzungsbedingungen", "/pages/nutzungsbedingungen.html"]
]);

app.use((req, res, next) => {
    if (!isSafeHttpMethod(req.method)) {
        return next();
    }

    const targetPath = SEO_CANONICAL_PATHS.get(req.path);

    if (!targetPath) {
        return next();
    }

    const rawUrl = String(req.originalUrl || req.url || "");
    const queryIndex = rawUrl.indexOf("?");
    const query = queryIndex >= 0 ? rawUrl.slice(queryIndex) : "";

    return res.redirect(308, `${targetPath}${query}`);
});


// ============================================================
// ÖFFENTLICHE WEBSITE AUS /public
//
// WICHTIG:
// - API UND AUTH LIEGEN VOR EXPRESS.STATIC
// - HTML WIRD NICHT ALT GECACHT
// - CSS / JS / BILDER WERDEN BEI JEDEM AUFRUF
//   AUF AKTUALITÄT GEPRÜFT
// ============================================================

app.use(
    express.static(
        PUBLIC_DIR,
        {

            extensions: [
                "html"
            ],

            dotfiles:
                "deny",

            etag:
                true,

            lastModified:
                true,

            cacheControl:
                false,

            setHeaders:
                (
                    res,
                    filePath
                ) => {

                    const extension =
                        path
                            .extname(
                                filePath
                            )
                            .toLowerCase();


                    // ------------------------------------------
                    // HTML NICHT CACHEN
                    // ------------------------------------------

                    if (
                        extension ===
                        ".html"
                    ) {

                        res.setHeader(
                            "Cache-Control",
                            "no-store, no-cache, must-revalidate, proxy-revalidate"
                        );

                        res.setHeader(
                            "Pragma",
                            "no-cache"
                        );

                        res.setHeader(
                            "Expires",
                            "0"
                        );

                        return;

                    }


                    // ------------------------------------------
                    // CSS / JS / BILDER / SONSTIGE ASSETS
                    // ------------------------------------------

                    res.setHeader(
                        "Cache-Control",
                        "public, max-age=0, must-revalidate"
                    );

                }

        }
    )
);


// ============================================================
// ÖFFENTLICHE 404-SEITE · PUBLIC RESILIENCE PASS 15
// ============================================================

app.use((req,res)=>{
    res.setHeader("Cache-Control","no-store");
    res.setHeader("X-Robots-Tag","noindex, nofollow, noarchive");
    if(req.accepts("html")){
        return res.status(404).sendFile(path.join(PUBLIC_DIR,"pages","not-found.html"));
    }
    return res.status(404).type("text/plain; charset=utf-8").send(`Seite nicht gefunden. Referenz: ${req.requestId||"-"}`);
});


// ============================================================
// REQUEST BODY ERROR BOUNDARY · SECURITY PASS R50
// ============================================================

function requestBodyFailure(error) {
    const type=String(error?.type||"");
    const status=Number(error?.status||error?.statusCode||0);
    if(type==="entity.too.large"||type==="parameters.too.many"||status===413){
        return {status:413,message:"Der Request-Body ist zu groß."};
    }
    if(type==="entity.parse.failed"||type==="encoding.unsupported"||(error instanceof SyntaxError&&status===400)){
        return {status:400,message:"Der Request-Body ist ungültig."};
    }
    return null;
}

// ============================================================
// SERVER ERROR HANDLER
// ============================================================

app.use(
    (
        error,
        req,
        res,
        next
    ) => {

        if (
            res.headersSent
        ) {

            return next(
                error
            );

        }

        const bodyFailure=requestBodyFailure(error);
        if(bodyFailure){
            res.setHeader("Cache-Control","no-store");
            res.setHeader("CDN-Cache-Control","no-store");
            res.setHeader("Surrogate-Control","no-store");
            if(req.path.startsWith("/api/")||req.path.startsWith("/auth/")){
                return res.status(bodyFailure.status).json({ok:false,error:bodyFailure.message});
            }
            return res.status(bodyFailure.status).type("text/plain; charset=utf-8").send(bodyFailure.message);
        }

        safeLogError(
            `unhandled:${req?.requestId||"no-request-id"}`,
            error
        );


        if (
            req.path.startsWith(
                "/api/"
            ) ||
            req.path.startsWith(
                "/auth/"
            )
        ) {

            return res
                .status(500)
                .json({

                    ok:
                        false,

                    error:
                        "Interner Serverfehler.",

                    reference:
                        req.requestId || null

                });

        }


        res.setHeader("Cache-Control","no-store");
        res.setHeader("X-Robots-Tag","noindex, nofollow, noarchive");
        return res
            .status(500)
            .sendFile(
                path.join(PUBLIC_DIR,"pages","error.html")
            );

    }
);


